630	        media.timestamp += ts_step;
631	
632	        next += interval;
633	        std::this_thread::sleep_until(next);
634	    }
635	
636	    media.close();
637	
638	    if (opt.fec) {
639	        fec_row.close();
640	        fec_col.close();
641	    }
