using packet = std::vector<std::uint8_t>;
using packet_submitter = std::function<void(packet)>;

class packet_impairer {
public:
    packet_impairer(const options& opt, packet_submitter submit)
        : loss_rate_(opt.loss_rate)
        , duplicate_rate_(opt.duplicate_rate)
        , reorder_rate_(opt.reorder_rate)
        , submit_(std::move(submit))
        , rng_(opt.seed ? *opt.seed : std::random_device{}()) {}

    void submit(packet value) {
        const bool drop = hit(loss_rate_);
        const bool duplicate = hit(duplicate_rate_);
        const bool reorder = hit(reorder_rate_);

        if (delayed_) {
            if (!drop) {
                submit_with_duplicate(std::move(value), duplicate);
            }
            submit_(std::move(*delayed_));
            delayed_.reset();
            return;
        }

        if (drop) {
            return;
        }

        if (reorder) {
            delayed_ = std::move(value);
            return;
        }

        submit_with_duplicate(std::move(value), duplicate);
    }

    void flush() {
        if (delayed_) {
            submit_(std::move(*delayed_));
            delayed_.reset();
        }
    }

private:
    bool hit(double rate) {
        return rate > 0.0 && distribution_(rng_) < rate;
    }

    void submit_with_duplicate(packet value, bool duplicate) {
        if (duplicate) {
            submit_(value);
        }
        submit_(std::move(value));
    }

    double loss_rate_{0.0};
    double duplicate_rate_{0.0};
    double reorder_rate_{0.0};
    packet_submitter submit_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> distribution_{0.0, 1.0};
    std::optional<packet> delayed_;
};

enum class jitter_target_protocol {
    rtp,
    srt,
};

double jitter_target_offset_ms(
    jitter_target_protocol protocol,
    double target_ms,
    bool high_phase)
{
    if (!high_phase) return 0.0;
    return protocol == jitter_target_protocol::rtp ? target_ms : target_ms / 2.0;
}

class packet_scheduler {
public:
    packet_scheduler(
        const options& opt,
        packet_submitter send,
        jitter_target_protocol target_protocol)
        : jitter_ms_(opt.jitter_ms)
        , jitter_target_ms_(opt.jitter_target_ms)
        , target_reorder_(jitter_target_reorders(opt))
        , target_protocol_(target_protocol)
        , send_(std::move(send))
        , rng_(opt.seed ? (*opt.seed ^ 0x9e3779b9U) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , worker_([this] { run(); }) {}

    ~packet_scheduler() {
        stop();
    }

    packet_scheduler(const packet_scheduler&) = delete;
    packet_scheduler& operator=(const packet_scheduler&) = delete;

    void set_base_time(clock_type::time_point value) {
        base_time_ = value;
    }

    void submit(packet value) {
        auto due = base_time_.value_or(clock_type::now());
        if (jitter_target_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms()));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (target_reorder_ == false && last_due_ && due < *last_due_) {
            due = *last_due_;
        }
        last_due_ = due;

        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stopping_) {
                return;
            }
            scheduled_.emplace(std::make_pair(due, next_sequence_++), std::move(value));
        }
        wake_.notify_one();
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stopping_) {
                return;
            }
            stopping_ = true;
            scheduled_.clear();
        }
        wake_.notify_one();
        if (worker_.joinable()) {
            worker_.join();
        }
    }

private:
    using schedule_key = std::pair<clock_type::time_point, std::uint64_t>;

    void run() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (stopping_ == false) {
            if (scheduled_.empty()) {
                wake_.wait(lock);
                continue;
            }

            const auto due = scheduled_.begin()->first.first;
            if (clock_type::now() < due) {
                wake_.wait_until(lock, due);
                continue;
            }

            packet value = std::move(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
            lock.unlock();
            send_(std::move(value));
            lock.lock();
        }
    }

    double next_target_offset_ms() {
        const double offset_ms = jitter_target_offset_ms(
            target_protocol_, jitter_target_ms_, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    double jitter_ms_{0.0};
    double jitter_target_ms_{0.0};
    bool target_reorder_{false};
    jitter_target_protocol target_protocol_{jitter_target_protocol::rtp};
    packet_submitter send_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> jitter_distribution_;
    bool target_high_phase_{false};
    std::optional<clock_type::time_point> base_time_;
    std::optional<clock_type::time_point> last_due_;
    std::mutex mutex_;
    std::condition_variable wake_;
    std::map<schedule_key, packet> scheduled_;
    std::uint64_t next_sequence_{0};
    bool stopping_{false};
    std::thread worker_;
};

bool impairment_enabled(const options& opt) {
    return opt.loss_rate > 0.0 ||
           opt.duplicate_rate > 0.0 ||
           opt.reorder_rate > 0.0 ||
           opt.jitter_ms > 0.0 ||
           opt.jitter_target_ms > 0.0;
}

void print_impairment(const options& opt) {
    if (!impairment_enabled(opt)) {
        return;
    }

    std::cerr
        << "impairment: loss=" << opt.loss_rate
        << " duplicate=" << opt.duplicate_rate
        << " reorder=" << opt.reorder_rate
        << " jitter_ms=" << opt.jitter_ms
        << " jitter_target_ms=" << opt.jitter_target_ms;

    if (opt.jitter_target_ms > 0.0) {
        std::cerr << " jitter_target_mode=" << jitter_target_mode_name(opt.target_mode);
    }
    if (opt.seed) {
        std::cerr << " seed=" << *opt.seed;
    }

    std::cerr << "\n";
}

void print_impairment_warnings(const options& opt) {
    const double interval_ms = nominal_packet_interval_ms(opt);

    if (opt.jitter_ms > interval_ms) {
        std::cerr
            << "warning: --jitter-ms " << opt.jitter_ms
            << " exceeds the nominal packet interval " << interval_ms
            << " ms; ordered delivery clamps some delays, so the configured maximum delay may not be observed.\n";
    }

    if (jitter_target_reorders(opt)) {
        std::cerr
            << "warning: --jitter-target-mode reorder permits "
            << (opt.proto == proto_type::rtp ? "RTP" : "SRT")
            << " data packets to arrive out of order; --jitter-target-ms is best effort and the measured value includes reordering effects.\n";
    }

    if (opt.jitter_target_ms > 0.0 &&
        (opt.loss_rate > 0.0 || opt.duplicate_rate > 0.0 || opt.reorder_rate > 0.0)) {
        std::cerr
            << "warning: loss, duplicate, or --reorder injection changes the jitter estimator input; --jitter-target-ms is not guaranteed with these options.\n";
    }

    if (opt.loss_rate > 0.0 || opt.duplicate_rate > 0.0 || opt.reorder_rate > 0.0) {
        std::cerr
            << "warning: loss, duplicate, and --reorder are independent probabilities; short captures need not match their configured rates.\n";
    }

    if (opt.proto == proto_type::rtp && opt.jitter_target_ms > 0.0 &&
        opt.clock_rate > 0 && opt.jitter_target_ms < 1000.0 / opt.clock_rate) {
        std::cerr
            << "warning: --jitter-target-ms " << opt.jitter_target_ms
            << " is below the RTP timestamp resolution " << (1000.0 / opt.clock_rate)
            << " ms; the target cannot be represented exactly.\n";
    }

    if (opt.proto == proto_type::srt && opt.jitter_target_ms > 0.0 &&
        opt.jitter_target_ms < 10.0) {
        std::cerr
            << "warning: SRT impairment scheduling polls at up to 10 ms; small jitter targets can be dominated by scheduler latency.\n";
    }

    if (opt.proto == proto_type::srt &&
        (opt.loss_rate > 0.0 || opt.duplicate_rate > 0.0 || opt.reorder_rate > 0.0)) {
        std::cerr
            << "warning: SRT retransmission and receiver buffering can change observed loss, reorder, and jitter from the UDP proxy settings.\n";
    }
}

