std::uint16_t parse_u16(const char* s, const char* name) {
    const auto v = std::stoul(s);
    if (v > 65535) {
        throw std::runtime_error(std::string(name) + " out of range: " + s);
    }
    return static_cast<std::uint16_t>(v);
}

std::uint8_t parse_u8(const char* s, const char* name) {
    const auto v = std::stoul(s);
    if (v > 255) {
        throw std::runtime_error(std::string(name) + " out of range: " + s);
    }
    return static_cast<std::uint8_t>(v);
}

std::uint32_t parse_u32(const char* s, const char* name) {
    const auto v = std::stoull(s);
    if (v > 0xffffffffULL) {
        throw std::runtime_error(std::string(name) + " out of range: " + s);
    }
    return static_cast<std::uint32_t>(v);
}

std::uint64_t parse_positive_u64(const std::string& value, const char* name) {
    std::size_t parsed = 0;
    const auto result = std::stoull(value, &parsed);
    if (parsed != value.size() || result == 0) {
        throw std::runtime_error(std::string(name) + " must be a positive integer");
    }
    return result;
}

double parse_finite_double(const std::string& value, const char* name) {
    std::size_t parsed = 0;
    const double result = std::stod(value, &parsed);
    if (parsed != value.size() || !std::isfinite(result)) {
        throw std::runtime_error(std::string(name) + " must be finite");
    }
    return result;
}

bool parse_period(const std::string& value, periodic_occurrence& out, std::string& error) {
    try {
        if (value.size() > 1 && value.back() == 'p') {
            out.basis = period_basis::packets;
            out.packet_period = parse_positive_u64(value.substr(0, value.size() - 1), "period");
            return true;
        }

        std::string number;
        double multiplier_ms = 0.0;
        if (value.size() > 2 && value.ends_with("ms")) {
            number = value.substr(0, value.size() - 2);
            multiplier_ms = 1.0;
        } else if (value.size() > 1 && value.back() == 's') {
            number = value.substr(0, value.size() - 1);
            multiplier_ms = 1000.0;
        } else {
            error = "period must use p, ms, or s units";
            return false;
        }

        const double milliseconds = parse_finite_double(number, "period") * multiplier_ms;
        if (milliseconds <= 0.0 || milliseconds > 86400000.0) {
            error = "time period must be in 0..86400000 ms";
            return false;
        }

        out.basis = period_basis::time;
        out.time_period = std::chrono::duration_cast<clock_type::duration>(
            std::chrono::duration<double, std::milli>(milliseconds));
        if (out.time_period <= clock_type::duration::zero()) {
            error = "time period is below clock resolution";
            return false;
        }
        return true;
    } catch (const std::exception& e) {
        error = e.what();
        return false;
    }
}

