#include "packet_reorder_buffer.h"

#include <utility>

packet_reorder_buffer::packet_reorder_buffer(double holdback_sec)
	: m_holdback_sec(holdback_sec) {
}

void packet_reorder_buffer::set_holdback_sec(double holdback_sec) {
	m_holdback_sec = holdback_sec;
}

void packet_reorder_buffer::reset() {
	m_buffer.clear();
	m_latest_seen_time = 0.0;
	m_seen_any = false;
	m_seq = 0;
}

void packet_reorder_buffer::push(double time_epoch, std::string line) {
	m_buffer.emplace(key{
		                 .time_epoch = time_epoch,
		                 .seq = m_seq++,
	                 },
	                 std::move(line));

	if(!m_seen_any || time_epoch > m_latest_seen_time) {
		m_seen_any = true;
		m_latest_seen_time = time_epoch;
	}
}
#ifndef PACKET_REORDER_BUFFER_H
#define PACKET_REORDER_BUFFER_H

#include <cstdint>
#include <map>
#include <string>
#include <string_view>
#include <utility>

class packet_reorder_buffer {
public:
	explicit packet_reorder_buffer(double holdback_sec = 0.0);

	void set_holdback_sec(double holdback_sec);
	void reset();
	void push(double time_epoch, std::string line);

	template<class Fn>
	void flush_ready(Fn &&fn) {
		if(!m_seen_any) {
			return;
		}

		const double watermark_time = m_latest_seen_time - m_holdback_sec;
		while(!m_buffer.empty()) {
			auto it = m_buffer.begin();
			if(it->first.time_epoch > watermark_time) {
				break;
			}

			std::string line = std::move(it->second);
			m_buffer.erase(it);
			fn(std::string_view(line));
		}
	}

	template<class Fn>
	void flush_all(Fn &&fn) {
		while(!m_buffer.empty()) {
			auto it = m_buffer.begin();
			std::string line = std::move(it->second);
			m_buffer.erase(it);
			fn(std::string_view(line));
		}
	}

private:
	struct key {
		double time_epoch{0.0};
		std::uint64_t seq{0};

		bool operator<(const key &rhs) const {
			if(time_epoch < rhs.time_epoch) {
				return true;
			}
			if(time_epoch > rhs.time_epoch) {
				return false;
			}
			return seq < rhs.seq;
		}
	};

	double m_holdback_sec{0.0};
	std::map<key, std::string> m_buffer;
	double m_latest_seen_time{0.0};
	bool m_seen_any{false};
	std::uint64_t m_seq{0};
};

#endif /* PACKET_REORDER_BUFFER_H */
