	ok &= require_index(c.h, "srt.hs.sid", c.i.srt.hs_sid);

	c.i.http.uri = optional_index(c.h, "http.request.uri");
	if(c.i.http.uri < 0) c.i.http.uri = optional_index(c.h, "http.uri");
	c.i.http.host = optional_index(c.h, "http.host");
