int optional_index(const field_map_t &fields, std::string_view name) {
	auto it = fields.find(std::string(name));
	if(it == fields.end()) {
		return -1;
	}
	return static_cast<int>(it->second);
}

bool require_index(const field_map_t &fields, std::string_view name, int &out) {
	out = optional_index(fields, name);
	if(out < 0) {
		trace(0, "error: missing required tshark field: %s", std::string(name).c_str());
		return false;
	}
	return true;
}

bool check_duplicate_fields(const std::string &header) {
	std::unordered_map<std::string, int> seen;
	tsv::row_t fields;
	tsv::split(header, fields);
	bool ok = true;
	for(const auto &field : fields) {
		std::string name(field);
		trim_field_name(name);
		if(name.empty()) {
			continue;
		}
		int &count = seen[name];
		++count;
		if(count == 2) {
			trace(0, "error: duplicate tshark field: %s", name.c_str());
			ok = false;
		}
	}
	return ok;
}

} // namespace

bool init_ctx(ctx &c, const std::string &header) {
	if(!check_duplicate_fields(header)) {
		return false;
	}

	c.h = tsv::make_field_map(header);
	bool ok = true;

	ok &= require_index(c.h, "frame.interface_id", c.i.com.interface_id);
	ok &= require_index(c.h, "frame.interface_name", c.i.com.interface_name);
	ok &= require_index(c.h, "frame.len", c.i.com.frame_len);
	ok &= require_index(c.h, "frame.time_epoch", c.i.com.time_epoch);
	ok &= require_index(c.h, "_ws.col.protocol", c.i.com.proto);
	ok &= require_index(c.h, "ip.proto", c.i.com.ip_proto);
	ok &= require_index(c.h, "ipv6.nxt", c.i.com.ipv6_nxt);
	ok &= require_index(c.h, "ip.src", c.i.com.ip_src);
	ok &= require_index(c.h, "ipv6.src", c.i.com.ipv6_src);
	ok &= require_index(c.h, "ip.dst", c.i.com.ip_dst);
	ok &= require_index(c.h, "ipv6.dst", c.i.com.ipv6_dst);
	ok &= require_index(c.h, "udp.srcport", c.i.com.udp_srcport);
	ok &= require_index(c.h, "udp.dstport", c.i.com.udp_dstport);
	c.i.com.tcp_srcport = optional_index(c.h, "tcp.srcport");
	c.i.com.tcp_dstport = optional_index(c.h, "tcp.dstport");
	c.i.com.tcp_stream = optional_index(c.h, "tcp.stream");
	c.i.com.tcp_len = optional_index(c.h, "tcp.len");
	c.i.com.vlan_id = optional_index(c.h, "vlan.id");
	c.i.com.vlan_priority = optional_index(c.h, "vlan.priority");
	c.i.com.vlan_dei = optional_index(c.h, "vlan.dei");
	ok &= require_index(c.h, "_ws.col.info", c.i.com.info);

	ok &= require_index(c.h, "rtp.ssrc", c.i.rtp.ssrc);
	ok &= require_index(c.h, "rtp.p_type", c.i.rtp.p_type);
	ok &= require_index(c.h, "rtp.seq", c.i.rtp.seq);
	ok &= require_index(c.h, "rtp.timestamp", c.i.rtp.timestamp);

	ok &= require_index(c.h, "srt.iscontrol", c.i.srt.iscontrol);
	ok &= require_index(c.h, "srt.type", c.i.srt.type);
	ok &= require_index(c.h, "srt.seqno", c.i.srt.seqno);
	ok &= require_index(c.h, "srt.msg.rexmit", c.i.srt.msg_rexmit);
	ok &= require_index(c.h, "srt.msg.order", c.i.srt.msg_order);
	ok &= require_index(c.h, "srt.nak_seqno", c.i.srt.nak_seqno);
	ok &= require_index(c.h, "srt.rtt", c.i.srt.rtt);
	ok &= require_index(c.h, "srt.rttvar", c.i.srt.rttvar);
	ok &= require_index(c.h, "srt.rate", c.i.srt.rate);
	ok &= require_index(c.h, "srt.rcvrate", c.i.srt.rcvrate);
	ok &= require_index(c.h, "srt.bw", c.i.srt.bw);
	ok &= require_index(c.h, "srt.timestamp", c.i.srt.timestamp);
	ok &= require_index(c.h, "srt.hs.sid", c.i.srt.hs_sid);

	c.i.http.uri = optional_index(c.h, "http.request.uri");
	if(c.i.http.uri < 0) c.i.http.uri = optional_index(c.h, "http.uri");
	c.i.http.host = optional_index(c.h, "http.host");
	c.i.http.method = optional_index(c.h, "http.request.method");
	if(c.i.http.method < 0) c.i.http.method = optional_index(c.h, "http.method");
	c.i.http.status_code = optional_index(c.h, "http.response.code");
	if(c.i.http.status_code < 0) c.i.http.status_code = optional_index(c.h, "http.status_code");
	c.i.http.content_length = optional_index(c.h, "http.content_length_header");
	if(c.i.http.content_length < 0) c.i.http.content_length = optional_index(c.h, "http.content_length");

	c.i.tls.server_name = optional_index(c.h, "tls.handshake.extensions_server_name");
	if(c.i.tls.server_name < 0) c.i.tls.server_name = optional_index(c.h, "ssl.handshake.extensions_server_name");

	// RTMP currently reuses RTP-like fields in the parser.
	c.i.rtmp.ssrc = c.i.rtp.ssrc;
	c.i.rtmp.p_type = c.i.rtp.p_type;
	c.i.rtmp.seq = c.i.rtp.seq;
	c.i.rtmp.timestamp = c.i.rtp.timestamp;

	return ok;
}

