class bitrate {
public:
    struct result {
        bool updated{false};
        double bps{0.0};
        double elapsed{0.0};
    };

    struct snapshot {
        double bps{0.0};
        value_stats stats{};
    };

public:
    void reset_window() {
        current_time_ = -1.0;
        rec_bytes_ = 0;
        bitrate_bps_ = 0.0;
    }

    void clear_stats() {
        stats_.clear();
    }

    void reset_all() {
        reset_window();
        clear_stats();
    }

    result update(double time_epoch, std::uint64_t frame_len) {
        result r{};

        if (current_time_ < 0.0) {
            current_time_ = time_epoch;
        }

        if (time_epoch < current_time_) {
            return r;
        }
        const std::int64_t now_sec = static_cast<std::int64_t>(time_epoch);
        const std::int64_t cur_sec = static_cast<std::int64_t>(current_time_);

        if (now_sec > cur_sec) {
            const double elapsed = time_epoch - current_time_;

            if (elapsed > 0.0) {
                bitrate_bps_ = static_cast<double>(rec_bytes_) * 8.0 / elapsed;
                stats_.add(bitrate_bps_);

                r.updated = true;
                r.bps = bitrate_bps_;
                r.elapsed = elapsed;
            }

            current_time_ = time_epoch;
            rec_bytes_ = 0;
        }

        rec_bytes_ += frame_len;
        return r;
    }

    snapshot snapshot_at(double now) const {
        snapshot s{
            .bps = bitrate_bps_,
            .stats = stats_,
        };

        if(s.stats.count == 0 &&
           current_time_ >= 0.0 &&
           rec_bytes_ > 0 &&
           now > current_time_) {
            const double elapsed = now - current_time_;
            const double bps = static_cast<double>(rec_bytes_) * 8.0 / elapsed;

            s.bps = bps;
            s.stats.add(bps);
        }

        return s;
    }

    double value() const { return bitrate_bps_; }
    const value_stats& stats() const { return stats_; }

private:
    double current_time_{-1.0};
    std::uint64_t rec_bytes_{0};
    double bitrate_bps_{0.0};
    value_stats stats_{};
};

