            ? bitrate_modulation.value_at(next)
            : static_cast<double>(opt.bitrate_bps);
        const auto interval = std::chrono::duration_cast<clock_type::duration>(
            std::chrono::duration<double>(static_cast<double>(opt.payload_size * 8) / bitrate));
        const std::uint32_t ts_step = static_cast<std::uint32_t>(std::max(1.0, std::round(
            static_cast<double>(opt.clock_rate) * std::chrono::duration<double>(interval).count())));
        ++media.seq;
