   196	void alert_evaluator::evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces) {
   197		auto evaluate_entries = [this, now](const json::array_t &entries, bool is_interface) {
   198			for(const auto &entry : entries) {
   199				if(!entry.is_object()) continue;
   200				std::map<std::string, const rule *> resolved;
   201				for(const auto &r : m_rules) {
   202					if(!r.enabled || !matches_target(r, entry, is_interface)) continue;
   203					auto it = resolved.find(r.id);
   204					if(it == resolved.end() || it->second->scope_priority < r.scope_priority) resolved[r.id] = &r;
   205				}
   206				for(const auto &[id, r] : resolved) evaluate_entry(now, *r, entry, is_interface);
   207			}
   208		};
   209		evaluate_entries(metrics, false);
   210		evaluate_entries(interfaces, true);
   211	}
