   216			if(!s.active) {
   217				continue;
   218			}
   219			json entry = s.source.is_object() ? s.source : json::object();
   220			if(s.detail.is_object()) {
   221				for(const auto &[key, value] : s.detail.items()) {
   222					if(!entry.contains(key)) {
   223						entry[key] = value;
   224					}
   225				}
   226			}
   227			entry["state_key"] = state_key;
   228			entry["state"] = "active";
   229			entry["last_value"] = s.last_value;
   230			entry["last_error_time"] = s.last_error_time;
   231			entry["last_seen_time"] = s.last_seen_time;
   232			out.push_back(std::move(entry));
   233		}
   234		return out;
   235	}
