   261	        clock_rate_ = clock_rate;
   262	    }
   263	
   264	    result update(double arrival_sec, std::uint64_t ext_rtp_ts) {
   265	        result r{};
   266	
   267	        if (clock_rate_ == 0) {
   268	            return r;
   269	        }
   270	
   271	        if (!initialized_) {
   272	            initialized_ = true;
   273	            base_arrival_sec_ = arrival_sec;
   274	            base_ext_ts_ = ext_rtp_ts;
   275	            return r;
   276	        }
   277	
   278	        elapsed_sec_ = arrival_sec - base_arrival_sec_;
   279	        if (elapsed_sec_ <= 0.0) {
   280	            return r;
   281	        }
   282	
   283	        const std::uint64_t elapsed_ts_u64 = ext_rtp_ts - base_ext_ts_;
