   228	class clock_skew {
   229	public:
   230	    struct result {
   231	        bool updated{false};
   232	        double elapsed_sec{0.0};
   233	        double observed_rate{0.0};
   234	        double skew_ppm{0.0};
   235	        double skew_ratio{0.0};
   236	    };
   237	
   238	public:
   239	    explicit clock_skew(std::uint32_t clock_rate = 90000)
   240	        : clock_rate_(clock_rate) {}
   241	
   242	    void reset_window() {
   243	        initialized_ = false;
   244	        base_arrival_sec_ = 0.0;
   245	        base_ext_ts_ = 0;
   246	        observed_rate_ = 0.0;
   247	        skew_ppm_ = 0.0;
   248	        skew_ratio_ = 0.0;
   249	    }
   250	
   251	    void clear_stats() {
   252	        stats_.clear();
   253	    }
   254	
   255	    void reset_all() {
   256	        reset_window();
   257	        clear_stats();
   258	    }
   259	
   260	    void set_clock_rate(std::uint32_t clock_rate) {
   261	        clock_rate_ = clock_rate;
   262	    }
   263	
   264	    result update(double arrival_sec, std::uint64_t ext_rtp_ts) {
   265	        result r{};
   266	
   267	        if (clock_rate_ == 0) {
   268	            return r;
   269	        }
   270	
   271	        if (!initialized_) {
   272	            initialized_ = true;
   273	            base_arrival_sec_ = arrival_sec;
   274	            base_ext_ts_ = ext_rtp_ts;
   275	            return r;
   276	        }
   277	
   278	        elapsed_sec_ = arrival_sec - base_arrival_sec_;
   279	        if (elapsed_sec_ <= 0.0) {
   280	            return r;
   281	        }
   282	
   283	        const std::uint64_t elapsed_ts_u64 = ext_rtp_ts - base_ext_ts_;
   284	        const double elapsed_ts = static_cast<double>(elapsed_ts_u64);
   285	
   286	        observed_rate_ = elapsed_ts / elapsed_sec_;
   287	        skew_ratio_ = observed_rate_ / static_cast<double>(clock_rate_) - 1.0;
   288	        skew_ppm_ = skew_ratio_ * 1.0e6;
   289	
   290	        stats_.add(skew_ppm_);
   291	
   292	        r.updated = true;
   293	        r.elapsed_sec = elapsed_sec_;
   294	        r.observed_rate = observed_rate_;
   295	        r.skew_ppm = skew_ppm_;
   296	        r.skew_ratio = skew_ratio_;
   297	        return r;
   298	    }
   299	
   300	    double observed_rate() const { return observed_rate_; }
   301	    double skew_ppm() const { return skew_ppm_; }
   302	    double skew_ratio() const { return skew_ratio_; }
   303	    double elapsed_sec() const { return elapsed_sec_; }
   304	
   305	    const value_stats& stats() const {
   306	        return stats_;
   307	    }
   308	
   309	private:
   310	    std::uint32_t clock_rate_{90000};
   311	    bool initialized_{false};
   312	    double base_arrival_sec_{0.0};
   313	    std::uint64_t base_ext_ts_{0};
   314	    double observed_rate_{0.0};
   315	    double skew_ppm_{0.0};
   316	    double skew_ratio_{0.0};
   317	    double elapsed_sec_{0.0};
   318	    value_stats stats_{};
   319	};
