#!/usr/bin/env python3

from __future__ import print_function

import argparse
import codecs
import copy
import glob
import itertools
import json
import logging
import os
import pprint
import shlex
import signal
import socket
import subprocess
import sys
import tempfile
import time
import traceback

import yaml

_VERSION = '1.7'
_UDSOCK = 'plumber'
_USER_TEE = '_USER_TEE'

_CONFIG_KEYS = {
    'command': [str, list],
    'depends': [list],
    'delay': [int],
    'input': [str],
    'output': [str],
    'stdin': [str],
    'stdout': [str],
    'stderr': [str],
    'options': [list, str],
    'pre': [str, list],
    'pri_start': [int],
    'pri_stop': [int],
}

_CONFIG_TEE = {
    'command': '/usr/bin/tee',
}

_LOGLEVEL = {
    None: logging.WARNING,
    'error': logging.ERROR,
    'info': logging.INFO,
    'debug': logging.DEBUG
}

_FD_NULL = open(os.devnull, 'w')


def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)


def to_argv(v):
    """
    Convert config value to argv list.

    - list: each element is one argument. Spaces inside an element are preserved.
    - str : parsed by shlex.split(), so quoted strings are kept as one argument.
    - None/empty string: no arguments.
    """
    if v is None:
        return []

    if isinstance(v, list):
        return [str(x) for x in v]

    if isinstance(v, str):
        if v == '':
            return []
        return shlex.split(v)

    return [str(v)]


def apply_environ(env_src, env_dst):
    def apply(env_src, env_dst):
        if '$' in env_dst:
            s = env_dst.replace('{','').replace('}','')
            key = s.split('$')[-1].split(' ')[0]
            if key in env_src:
                return s.replace('$' + key, env_src[key])
            else:
                eprint('error: unknown environment variable \'${%s}\'.' % key)
                raise Exception
        return env_dst

    def parse_obj(env_dst, k):
        if isinstance(env_dst[k], dict):
            parse_dict(env_dst[k])
        elif isinstance(env_dst[k], list):
            parse_list(env_dst[k])
    def __init__(self, sockfile, name, config, debuglevel):
        logging.basicConfig(level = _LOGLEVEL[debuglevel],
                            format = '%(asctime)s.%(msecs)03d' + time.strftime('%z') + ',PLUMBER[' + name + '],%(levelname)s,%(message)s',
                            datefmt = '%Y-%m-%dT%H:%M:%S')
        self.name = name
        self.sockfile = sockfile

        self.ongoing = True
        self.configfile = None
        self.config = None
        self.procs = {}
        self.connection = {}
        self.environ = {}

        if not os.path.exists(config):
            eprint('error: \'%s\' not found' % config)
            exit()

        self.signal = sighandler()
        self.__configure(config)

    def __del__(self):
        logging.info('terminate all processes.')
        if len(self.procs) > 0:
            for p in sorted(self.procs.items(), key=lambda x:x[1].pri_stop, reverse=True):
                p[1].stop()

        logging.info('plumber finished.')

    def __load_config(self, file):
        def load(config, file):
            with codecs.open(file, 'r', encoding='utf8') as f:
                try:
                    c = yaml.load(f, Loader = yaml.SafeLoader)
                    for inc in c.get('include', []):
                        load(config, inc)
                    config.update(c)
                except Exception as e:
                    eprint('error: invalid YAML.')
                    raise e

        def update(config):
            for k, v in config.items():
                if 'input' in v:
                    v['stdin'] = v.pop('input')
                    # eprint('warning: use of the \'input\' keyword is deprecated. use \'stdin\' instead.')

                if 'output' in v:
                    v['stdout'] = v.pop('output')
                    # eprint('warning: use of the \'output\' keyword is deprecated. use \'stdout\' instead.')

        config = {}
        try:
           load(config, file)
           update(config)
        except Exception as e:
            logging.error('error: failed to load %s', file)

        return config

    def __configure(self, file):
        self.configfile = file
        self.config = self.__load_config(self.configfile)
        self.environ = self.__build_environ(self.config)
        apply_environ(self.environ, self.config)

        for k, v in self.config.items():
            if 'command' in v:
                dut = set(v.keys())
                ref = set(_CONFIG_KEYS.keys())
                if not dut.issubset(ref):
                    eprint('error: unknown keywords \'%s\' in %s' % (dut.difference(ref), k))
                    raise Exception

        for k, v in self.config.items():
            if 'command' in v:
                for ki, vi in v.items():
                    if type(vi) not in _CONFIG_KEYS[ki]:
                        eprint('error: \'%s\' must be %s. (but %s, %s)' % (ki, _CONFIG_KEYS[ki], vi, type(vi)))
                        raise Exception

