{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://example.local/stm/protocol_map.schema.json",
  "title": "STM protocol_map configuration",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "observe_mode": {
      "type": "string",
      "enum": [
        "all",
        "configured_only",
        "configured_plus_other"
      ],
      "default": "all",
      "description": "Controls whether stream/flow observation is limited by protocol rules. Omitted means all."
    },
    "protocols": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/protocolRule"
      },
      "default": []
    }
  },
  "required": [
    "protocols"
  ],
  "$defs": {
    "endpoint": {
      "type": "string",
      "description": "IP endpoint in host:port form for IPv4 or [addr]:port form for IPv6.",
      "examples": [
        "239.1.1.1:5000",
        "127.0.0.1:4201",
        "[2001:db8::1]:5000"
      ]
    },
    "host": {
      "type": "string",
      "description": "HTTP Host or TLS SNI host name. Exact case-insensitive match is used; leading wildcard such as *.example.com is allowed.",
      "examples": [
        "example.com",
        "*.example.com",
        "test-streams.mux.dev"
      ]
    },
    "vlan": {
      "description": "Omitted means any VLAN, null means untagged only, number/string means VLAN ID match.",
      "oneOf": [
        {
          "type": "null"
        },
        {
          "type": "integer",
          "minimum": 0,
          "maximum": 4094
        },
        {
          "type": "string",
          "pattern": "^[0-9]+$"
        }
      ]
    },
    "protocolRule": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128,
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*$",
          "description": "Optional stable Monitoring Target identifier. It is referenced by alert assignments."
        },
        "target_type": {
          "type": "string",
          "enum": ["single", "group"],
          "default": "single",
          "description": "single is one logical target; group applies shared alert profiles to multiple matches."
        },
        "proto": {
          "type": "string",
          "description": "Protocol name used for decode-as generation and observation matching.",
          "examples": [
