              "$ref": "#/$defs/endpoint"
            },
            {
              "type": "array",
              "items": {
                "$ref": "#/$defs/endpoint"
              }
            }
          ],
          "default": []
        },
        "hosts": {
          "oneOf": [
            {
              "$ref": "#/$defs/host"
            },
            {
              "type": "array",
              "items": {
                "$ref": "#/$defs/host"
