        "127.0.0.1:4201",
        "[2001:db8::1]:5000"
      ]
    },
    "host": {
      "type": "string",
      "description": "HTTP Host or TLS SNI host name. Exact case-insensitive match is used; leading wildcard such as *.example.com is allowed.",
