      "type": "string",
      "description": "IP endpoint in host:port form for IPv4 or [addr]:port form for IPv6.",
      "examples": [
        "239.1.1.1:5000",
        "127.0.0.1:4201",
        "[2001:db8::1]:5000"
      ]
    },
    "host": {
      "type": "string",
      "description": "HTTP Host or TLS SNI host name. Exact case-insensitive match is used; leading wildcard such as *.example.com is allowed.",
      "examples": [
        "example.com",
        "*.example.com",
        "test-streams.mux.dev"
      ]
    },
    "vlan": {
      "description": "Omitted means any VLAN, null means untagged only, number/string means VLAN ID match.",
      "oneOf": [
        {
          "type": "null"
        },
        {
          "type": "integer",
          "minimum": 0,
          "maximum": 4094
        },
        {
          "type": "string",
          "pattern": "^[0-9]+$"
        }
      ]
    },
    "protocolRule": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128,
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*$",
          "description": "Optional stable Monitoring Target identifier. It is referenced by alert assignments."
        },
        "target_type": {
          "type": "string",
          "enum": ["single", "group"],
          "default": "single",
          "description": "single is one logical target; group applies shared alert profiles to multiple matches."
        },
        "proto": {
          "type": "string",
          "description": "Protocol name used for decode-as generation and observation matching.",
          "examples": [
            "RTP",
            "SRT",
            "RTMP",
            "HTTP",
            "HLS"
          ]
        },
        "enabled": {
          "type": "boolean",
          "default": true,
          "description": "False preserves this rule in the file but excludes it from decode-as, FEC, name mapping, and observation matching."
        },
        "target_name": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128,
          "description": "Optional operator-assigned name for this Monitoring Target; it does not change the stream display name."
        },
        "stream_name": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128,
          "description": "Optional operator-assigned display name for a matching stream."
        },
        "endpoints": {
          "oneOf": [
            {
              "$ref": "#/$defs/endpoint"
            },
            {
              "type": "array",
              "items": {
                "$ref": "#/$defs/endpoint"
              }
            }
          ],
          "default": []
        },
        "hosts": {
          "oneOf": [
            {
              "$ref": "#/$defs/host"
            },
            {
              "type": "array",
              "items": {
                "$ref": "#/$defs/host"
              }
            }
          ],
          "default": [],
          "description": "HTTP Host / TLS SNI based observation match."
        },
        "domains": {
          "oneOf": [
            {
              "$ref": "#/$defs/host"
            },
            {
              "type": "array",
              "items": {
                "$ref": "#/$defs/host"
              }
            }
          ],
          "default": [],
          "description": "Alias of hosts."
        },
        "decode_as": {
          "oneOf": [
            {
              "type": "string"
            },
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          ],
          "description": "Explicit tshark -d decode-as rule(s). If omitted, STM auto-generates known protocol rules from endpoints."
        },
        "fec": {
          "type": "boolean",
          "default": false,
          "description": "For RTP, expands decode-as and observation matching to base/base+2/base+4."
        },
        "observe": {
          "type": "boolean",
          "default": true,
          "description": "False keeps decode-as/FEC settings but excludes this rule from observation allow-list matching."
        },
        "vlan": {
          "$ref": "#/$defs/vlan"
        }
      },
      "required": [
        "proto"
      ]
    }
  }
}
