class packet_rate {
public:
    struct result {
        bool updated{false};
        double pps{0.0};
        double elapsed{0.0};
    };

    struct snapshot {
        double pps{0.0};
        value_stats stats{};
        bool available{false};
    };

public:
    void reset_window() {
        current_time_ = -1.0;
        rec_packets_ = 0;
        packet_rate_pps_ = 0.0;
        has_sample_ = false;
    }

    void clear_stats() {
        stats_.clear();
    }

    void reset_all() {
        reset_window();
        clear_stats();
    }

    result update(double time_epoch) {
        result r{};

        if (current_time_ < 0.0) {
            current_time_ = time_epoch;
        }

        if (time_epoch < current_time_) {
            return r;
        }
        const double elapsed = time_epoch - current_time_;
        if (elapsed >= minimum_window_sec_) {
            packet_rate_pps_ = static_cast<double>(rec_packets_) / elapsed;
            stats_.add(packet_rate_pps_);
            has_sample_ = true;

            r.updated = true;
            r.pps = packet_rate_pps_;
            r.elapsed = elapsed;

            current_time_ = time_epoch;
            rec_packets_ = 0;
        }

        ++rec_packets_;
        return r;
    }

    snapshot snapshot_at(double /*now*/) const {
        snapshot s{
            .pps = packet_rate_pps_,
            .stats = stats_,
            .available = has_sample_,
        };
        if (s.available && s.stats.count == 0) {
            s.stats.add(s.pps);
        }
        return s;
    }

    double value() const { return packet_rate_pps_; }
    const value_stats& stats() const { return stats_; }

private:
    double current_time_{-1.0};
    std::uint64_t rec_packets_{0};
    double packet_rate_pps_{0.0};
    bool has_sample_{false};

