#include "stream_srt.h"

#include <cstdio>
#include <iostream>
#include <utility>

#include "json.h"
#include "trace.h"
#include "stream_json.h"
#include "tsv_util.h"

namespace srt {

flow::flow(const stream_id& sid, const flow_id fid, std::string interface_name, event_sink &events)
	: m_fid(std::move(fid))
	, m_interface_name(std::move(interface_name))
	, m_events(events) {
	m_identity = flow_identity_cache{
		.stream_key = make_stream_key(sid),
		.flow_key = make_flow_key(sid, m_fid),
	};
	m_text.src = to_string(m_fid.src);
	m_text.dst = to_string(m_fid.dst);
	m_event.source = stream_json::make_flow_event_source("SRT",
	                                                        m_fid.interface_id,
	                                                        m_interface_name,
	                                                        m_identity.stream_key,
	                                                        m_identity.flow_key,
	                                                        m_fid.vlan);
}

bool flow::update_role(const info &i) {
	const flow_role observed = (i.iscontrol != 0) ? flow_role::control : flow_role::data;
	const flow_role previous = m_role;

	if(m_role == flow_role::unknown) {
		m_role = observed;
	}
	else if(m_role != observed && m_role != flow_role::mixed) {
		m_role = flow_role::mixed;
	}

	m_text.role = to_string(m_role);
	m_role_changed = m_role != previous;
	return m_role_changed;
}

int flow::process(const info &i) {
	touch(i.time_epoch);
	update_role(i);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.interval.update(i.time_epoch);
	m_metrics.packet_rate.update(i.time_epoch);
	m_metrics.packet_count.inc();
	m_metrics.packet_counts.update(i.iscontrol != 0, i.msg_rexmit != 0);

	if(i.iscontrol != 0) {
		m_metrics.control_types.update(i.type);
		if(i.type == 0x0003) {
			m_metrics.nak_seq_stats.add(static_cast<double>(i.nak_seqno));
		}
	}
	else {
		if(i.msg_rexmit == 0) {
			const auto data_interval = m_metrics.data_interval.update(i.time_epoch);
			if(data_interval.updated) {
				m_metrics.jitter.update(data_interval.seconds);
			}
		}

		auto seq_update = m_metrics.seq_stats.update(i.seqno);
		m_event.packet.loss_gap_count += seq_update.gap_added;
		if(seq_update.duplicate) {
			++m_event.packet.duplicate_count;
		}
		if(seq_update.reordered) {
			++m_event.packet.reorder_count;
		}
	}

	if(i.has_rtt)     m_metrics.rtt.update(static_cast<double>(i.rtt));
	if(i.has_rttvar)  m_metrics.rttvar.update(static_cast<double>(i.rttvar));
	if(i.has_rate)    m_metrics.rate.update(static_cast<double>(i.rate));
	if(i.has_rcvrate) m_metrics.rcvrate.update(static_cast<double>(i.rcvrate));
	if(i.has_bw)      m_metrics.bw.update(static_cast<double>(i.bw));

	return 0;
}

void flow::emit_detected(double now) {
	m_events.emit(make_event(now, "flow_detected", json{
		{"interface_id", m_fid.interface_id},
		{"role", m_text.role},
		{"endpoint", {
			{"src", m_text.src},
			{"dst", m_text.dst},
		}},
		{"vlan", m_fid.vlan.empty() ? json(nullptr) : tsv::to_json(m_fid.vlan)},
	}));
}

void flow::emit_role_updated(double now) {
	m_events.emit(make_event(now, "flow_role_updated", json{
		{"interface_id", m_fid.interface_id},
		{"role", m_text.role},
		{"endpoint", {
			{"src", m_text.src},
			{"dst", m_text.dst},
		}},
	}));
}

void flow::emit_lost(double now) {
	m_events.emit(make_event(now, "flow_lost", json{
		{"interface_id", m_fid.interface_id},
		{"role", m_text.role},
		{"endpoint", {
			{"src", m_text.src},
			{"dst", m_text.dst},
		}},
		{"last_seen", last_seen()},
	}));
}

json flow::to_list_json(double now) const {
	(void)now;
	json j = stream_json::make_flow_list_base(m_identity.flow_key,
	                                               m_fid.interface_id,
	                                               m_interface_name,
	                                               m_fid.vlan);
	j["role"] = m_text.role;
	j["endpoint"] = {
		{"src", m_text.src},
		{"dst", m_text.dst},
	};
	j["last_seen"] = last_seen();
	return j;
}

int flow::append_metrics(double now, json::array_t &out) {
	flow_metrics &m = m_metrics;
	const auto bitrate = m.bitrate.snapshot_at(now);
	const auto packet_rate = m.packet_rate.snapshot_at(now);

	json j = stream_json::make_flow_metrics_base("SRT",
	                                               m_fid.interface_id,
	                                               m_interface_name,
	                                               m_identity.stream_key,
	                                               m_identity.flow_key,
	                                               m_fid.vlan);
	j["role"] = m_text.role;
	j["endpoint"] = {
		{"src", m_text.src},
		{"dst", m_text.dst},
	};
	j.update(json{
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"packet_rate", {
			{"pps", packet_rate.pps},
			{"count", packet_rate.stats.count},
			{"min", packet_rate.stats.min},
			{"max", packet_rate.stats.max},
			{"avg", packet_rate.stats.avg()},
		}},
		{"packet_count", {
			{"window", m.packet_count.count()},
			{"total", m.packet_count.total()},
		}},
		{"interval", {
			{"seconds", m.interval.value()},
			{"count", m.interval.stats().count},
			{"min", m.interval.stats().min},
			{"max", m.interval.stats().max},
			{"avg", m.interval.stats().avg()},
		}},
		{"jitter", {
			{"seconds", m.jitter.value()},
			{"count", m.jitter.stats().count},
			{"min", m.jitter.stats().min},
			{"max", m.jitter.stats().max},
			{"avg", m.jitter.stats().avg()},
		}},
		{"packet_breakdown", {
			{"total", {
				{"window", m.packet_counts.total().count()},
				{"total", m.packet_counts.total().total()},
			}},
			{"data", {
				{"window", m.packet_counts.data().count()},
				{"total", m.packet_counts.data().total()},
			}},
			{"control", {
				{"window", m.packet_counts.control().count()},
				{"total", m.packet_counts.control().total()},
			}},
			{"retransmit", {
				{"window", m.packet_counts.retransmit().count()},
				{"total", m.packet_counts.retransmit().total()},
			}},
		}},
		{"control_type_count", {
			{"total", {
				{"window", m.control_types.total().count()},
				{"total", m.control_types.total().total()},
			}},
			{"handshake", {
				{"window", m.control_types.handshake().count()},
				{"total", m.control_types.handshake().total()},
			}},
			{"keepalive", {
				{"window", m.control_types.keepalive().count()},
				{"total", m.control_types.keepalive().total()},
			}},
			{"ack", {
				{"window", m.control_types.ack().count()},
				{"total", m.control_types.ack().total()},
			}},
			{"nak", {
				{"window", m.control_types.nak().count()},
				{"total", m.control_types.nak().total()},
			}},
			{"shutdown", {
				{"window", m.control_types.shutdown().count()},
		if(!cur->is_object() || !cur->contains(part)) {
			return std::nullopt;
		}
		cur = &(*cur)[part];
	}
	if(cur->is_number()) {
		return cur->get<double>();
	}
	return std::nullopt;
}

bool alert_evaluator::compare(double lhs, compare_op op, double rhs) {
	switch(op) {
	case compare_op::gt: return lhs > rhs;
	case compare_op::ge: return lhs >= rhs;
	case compare_op::lt: return lhs < rhs;
	case compare_op::le: return lhs <= rhs;
	case compare_op::eq: return lhs == rhs;
	case compare_op::ne: return lhs != rhs;
	}
	return false;
}

std::string alert_evaluator::compare_operator(compare_op op) {
	switch(op) {
	case compare_op::gt: return ">";
	case compare_op::ge: return ">=";
	case compare_op::lt: return "<";
	case compare_op::le: return "<=";
	case compare_op::eq: return "==";
	case compare_op::ne: return "!=";
	}
	return "?";
}

bool alert_evaluator::matches_target(const rule &r, const json &entry, bool is_interface) {
	if(r.target == "interface") {
		return is_interface;
	}
	if(is_interface) {
		return r.target == "any";
	}
	if(r.target == "flow" && !entry.contains("flow_key")) {
		return false;
	}
	if(r.target == "stream" && entry.contains("flow_key")) {
		return false;
	}
	if(!r.proto.empty()) {
		const auto proto = json_string_or_empty(entry, "proto");
		if(proto != r.proto) {
			return false;
		}
	}
	if(!r.flow_roles.empty()) {
		const auto role = json_string_or_empty(entry, "role");
		if(std::find(r.flow_roles.begin(), r.flow_roles.end(), role) == r.flow_roles.end()) {
			return false;
		}
	}
	return true;
}

std::string alert_evaluator::make_state_key(const rule &r, const json &entry, bool is_interface) {
	std::ostringstream ss;
	ss << r.id;
	if(is_interface) {
		ss << "|interface=" << json_string_or_empty(entry, "interface_id")
		   << "|name=" << json_string_or_empty(entry, "name");
		return ss.str();
	}
	ss << "|proto=" << json_string_or_empty(entry, "proto")
	   << "|stream=" << json_string_or_empty(entry, "stream_key");
	const auto flow_key = json_string_or_empty(entry, "flow_key");
	if(!flow_key.empty()) {
		ss << "|flow=" << flow_key;
	}
	return ss.str();
}

json alert_evaluator::make_target_source(const rule &r, const json &entry, bool is_interface) {
	json source{
		{"alert_id", r.id},
		{"severity", r.severity},
		{"indicator_category", r.indicator_category},
		{"target", is_interface ? "interface" : (entry.contains("flow_key") ? "flow" : "stream")},
	};
	for(const auto &key : {"proto", "stream_key", "flow_key", "interface_id", "name"}) {
		if(entry.contains(key)) {
			source[key] = entry[key];
		}
	}
	if(!r.monitoring_target_id.empty()) source["monitoring_target_id"] = r.monitoring_target_id;
	return source;
}

alert_evaluator::rule_type alert_evaluator::parse_rule_type(const std::string &value) {
	if(value == "threshold") return rule_type::threshold;
	if(value == "counter_delta") return rule_type::counter_delta;
	throw std::runtime_error("unknown alert rule type: " + value);
}

alert_evaluator::compare_op alert_evaluator::parse_compare_op(const std::string &value) {
	if(value == ">") return compare_op::gt;
	if(value == ">=") return compare_op::ge;
	if(value == "<") return compare_op::lt;
	if(value == "<=") return compare_op::le;
	if(value == "==") return compare_op::eq;
	if(value == "!=") return compare_op::ne;
	throw std::runtime_error("unknown alert operator: " + value);
}
