std::uint32_t modulation_seed(const options& opt, const std::optional<modulation>& setting, std::uint32_t salt) {
    if (setting && setting->seed) return *setting->seed ^ salt;
    return opt.seed ? (*opt.seed ^ salt) : std::random_device{}();
}

class modulation_driver {
public:
    modulation_driver(std::optional<modulation> setting, std::uint32_t seed)
        : setting_(std::move(setting)), seed_(seed) {}

    bool enabled() const { return setting_.has_value(); }

    double value_at(clock_type::time_point now) {
        if (!setting_) return 0.0;
        if (!started_) started_ = now;
        const auto& setting = *setting_;
        const double period = std::chrono::duration<double>(setting.period).count();
        const double phase = std::chrono::duration<double>(setting.phase).count();
        double position = std::fmod(std::chrono::duration<double>(now - *started_).count() + phase, period);
        if (position < 0.0) position += period;
        const double fraction = position / period;
        double normalized = 0.0;
        switch (setting.curve) {
        case modulation_curve::sine:
            normalized = 0.5 - 0.5 * std::cos(2.0 * std::acos(-1.0) * fraction);
            break;
        case modulation_curve::triangle:
            normalized = fraction < 0.5 ? fraction * 2.0 : (1.0 - fraction) * 2.0;
            break;
        case modulation_curve::step:
            normalized = fraction < 0.5 ? 0.0 : 1.0;
            break;
        case modulation_curve::random: {
            const auto update = std::chrono::duration<double>(setting.update).count();
            const std::uint64_t slot = static_cast<std::uint64_t>(std::floor(position / update));
            std::uint32_t value = seed_ ^ static_cast<std::uint32_t>(slot) ^ static_cast<std::uint32_t>(slot >> 32);
            value ^= value >> 16;
            value *= 0x7feb352dU;
            value ^= value >> 15;
            value *= 0x846ca68bU;
            value ^= value >> 16;
            normalized = static_cast<double>(value) / static_cast<double>(UINT32_MAX);
            break;
        }
        }
        return setting.min_value + (setting.max_value - setting.min_value) * normalized;
    }

private:
    std::optional<modulation> setting_;
    std::uint32_t seed_{0};
    std::optional<clock_type::time_point> started_;
};

class packet_scheduler {
public:
    packet_scheduler(
        const options& opt,
        packet_submitter send,
        jitter_target_protocol target_protocol)
        : jitter_ms_(opt.jitter.max_ms)
        , jitter_target_ms_(opt.jitter.target_ms)
        , jitter_modulation_(opt.jitter_modulation, modulation_seed(opt, opt.jitter_modulation, 0x9e3779b9U))
        , target_reorder_(jitter_target_reorders(opt))
        , target_protocol_(target_protocol)
        , send_(std::move(send))
        , rng_(opt.seed ? (*opt.seed ^ 0x9e3779b9U) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , worker_([this] { run(); }) {}

    ~packet_scheduler() {
        stop();
    }

    packet_scheduler(const packet_scheduler&) = delete;
    packet_scheduler& operator=(const packet_scheduler&) = delete;

    void set_base_time(clock_type::time_point value) {
        base_time_ = value;
    }

    void submit(packet value) {
        const auto base = base_time_.value_or(clock_type::now());
        auto due = base;
        const double target_ms = jitter_modulation_.enabled()
            ? jitter_modulation_.value_at(base) : jitter_target_ms_;
        if (target_ms > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms(target_ms)));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (!target_reorder_ && last_due_ && due < *last_due_) due = *last_due_;
        last_due_ = due;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stopping_) return;
            scheduled_.emplace(std::make_pair(due, next_sequence_++), std::move(value));
        }
        wake_.notify_one();
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (stopping_) return;
            stopping_ = true;
            scheduled_.clear();
        }
        wake_.notify_one();
        if (worker_.joinable()) worker_.join();
    }

private:
    using schedule_key = std::pair<clock_type::time_point, std::uint64_t>;

    void run() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (!stopping_) {
            if (scheduled_.empty()) {
                wake_.wait(lock);
                continue;
            }
            const auto due = scheduled_.begin()->first.first;
            if (clock_type::now() < due) {
                wake_.wait_until(lock, due);
                continue;
            }
            packet value = std::move(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
            lock.unlock();
            send_(std::move(value));
            lock.lock();
        }
    }

    double next_target_offset_ms(double target_ms) {
        const double offset_ms = jitter_target_offset_ms(target_protocol_, target_ms, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    double jitter_ms_{0.0};
    double jitter_target_ms_{0.0};
    modulation_driver jitter_modulation_;
    bool target_reorder_{false};
    jitter_target_protocol target_protocol_{jitter_target_protocol::rtp};
    packet_submitter send_;
    std::mt19937 rng_;
    std::uniform_real_distribution<double> jitter_distribution_;
    bool target_high_phase_{false};
