: proto === "RTP-FEC" }); }}><option value="RTP">RTP</option><option value="RTP-FEC">RTP-FEC</option><option value="SRT">SRT</option><option value="HLS">HLS</option></select></td><td><select value={row.target} disabled={locked || state === "saving" || row.proto !== "HLS"} onChange={(event) => updateRow(index, { target: event.target.value as Row["target"], value: "", port: "" })}><option value="endpoint">Endpoint</option><option value="host">Host</option></select></td><td><input value={row.value} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { value: event.target.value })} placeholder={row.target === "host" ? "media.example.com" : "239.1.1.1"} /></td><td>{row.target === "endpoint" && <input type="number" min="1" max="65535" value={row.port} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { port: event.target.value })} />}</td><td><select value={row.vlanMode} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanMode: event.target.value as Row["vlanMode"] })}><option value="any">Any</option><option value="untagged">Untagged</option><option value="id">ID</option></select>{row.vlanMode === "id" && <input type="number" min="0" max="4094" value={row.vlanId} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanId: event.target.value })} />}</td><td><input value={row.stream_name ?? ""} placeholder="Camera 1" disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { stream_name: event.target.value })} /></td><td><button type="button" className="maintenance-secondary-button protocol-map-profile-button" disabled={locked || state === "saving" || !profiles.length} title={profiles.length ? "Choose one or more alert profiles." : "Create profiles in Alert policies first."} onClick={() => setProfileTargetId(row.id ?? null)}>{profileSummary(assignedProfiles(row.id ?? ""), profiles)}</button>{!profiles.length && <span className="protocol-map-