import { useEffect, useMemo, useRef, useState } from "react";
import uPlot from "uplot";
import type { AlertRule, MetricPoint, TimeSeriesMetric } from "../types/api";
import { formatFixedNumber, formatMetricAxisValue, formatMetricValue, metricDisplayScale, niceLinearRange, type MetricDisplayScale } from "./format";

type MetricChartProps = {
  title: string;
  metric?: TimeSeriesMetric;
  height?: number;
  color?: string;
  compact?: boolean;
  fillHeight?: boolean;
  alertContext?: ChartAlertContext;
  yScale?: ChartYScale;
  scalePreference?: import("./format").MetricScalePreference;
  renderMode?: "line" | "bar";
};

export type ChartYScale = {
  mode: "auto" | "zero" | "fixed";
  min?: number;
  max?: number;
};

export type ChartAlertContext = {
  rules: AlertRule[];
  target: "flow" | "interface";
  proto?: string;
};

type ChartThreshold = {
  id: string;
  metric: string;
  label: string;
  value: number;
  severity: string;
  recovery: boolean;
  operator: string;
};

type DrawThresholdLabel = ChartThreshold & { color: string };

const syncKey = "stream-detail";
const chartMetricValueFields = new Set(["value", "bps", "pps", "seconds", "avg", "min", "max", "window", "total"]);

export function MetricChart({ title, metric, height = 190, color = "var(--chart-accent)", compact = false, fillHeight = false, alertContext, yScale, scalePreference, renderMode: requestedRenderMode }: MetricChartProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<uPlot | null>(null);
  const hostVisibleRef = useRef(false);
  const chartStateRef = useRef<{
    metric?: TimeSeriesMetric;
    yRange: { min: number; max: number; splits: number[] };
    displayScale: MetricDisplayScale;
    displayThresholds: ChartThreshold[];
    axisDigits: number;
  } | null>(null);
  const [cursorPoint, setCursorPoint] = useState<MetricPoint | null>(null);
  const hasData = Boolean(metric && metric.points.length > 0);
  const renderMode = requestedRenderMode ?? (metric?.points.some((point) => point.interval) || isIntervalCounterMetric(metric?.key) ? "bar" : "line");
  const barValueLabel = isIntervalCounterMetric(metric?.key) ? "count" : "value";
  const thresholds = useMemo(() => thresholdsForMetric(metric, alertContext), [metric, alertContext]);
  const rawValues = useMemo(() => chartValues(metric, thresholds, renderMode), [metric, thresholds, renderMode]);
  const displayScale = useMemo(() => metricDisplayScale(metric?.key, metric?.unit, rawValues, scalePreference),  [metric?.key, metric?.unit, rawValues, scalePreference]);
  const yRange = useMemo(() => {
    const values = rawValues.map((value) => value / displayScale.divisor);
  proto
}: {
  flow: StreamState["flows"][number];
  metrics?: FlowMetricsResponse;
  charts: Array<{ key: string; label: string; metric: TimeSeriesMetric }>;
  alertRules: AlertRule[];
  proto: string;
}) {
  const accent = flowAccent(flow.role);
  const bitrate = metrics?.metrics.bitrate?.points.at(-1)?.avg
    ?? metrics?.metrics.bitrate?.points.at(-1)?.value
    ?? flow.metrics.bitrate?.value
    ?? flow.metrics.bitrate?.avg;

  return (
    <section className="graph-flow-card" style={{ borderTopColor: accent }}>
      <div className="graph-flow-card-header">
        <div>
          <strong>{flow.role}</strong>
          <p>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</p>
        </div>
        <span className="graph-flow-rate">{formatBitrate(bitrate)}</span>
      </div>
      <div className={`graph-card-grid ${charts.length === 1 ? "single" : ""}`}>
        {charts.map((chart) => (
          <MetricChart
            key={`${flow.flowKey}:${chart.key}`}
            title={chart.label}
            metric={chart.metric}
            height={chart.key === "bitrate" ? 64 : 52}
            compact
            fillHeight
            color={chart.key === "bitrate" ? accent : colorForMetric(chart.key)}
            alertContext={{ rules: alertRules, target: "flow", proto }}
          />
        ))}
      </div>
    </section>
  );
}

function FlowMetricGroup({ descriptor, metrics, compact = false, alertRules, proto }: { descriptor: MetricDescriptor; metrics: StreamMetricsResponse | null; compact?: boolean; alertRules: AlertRule[]; proto: string }) {
  const flowMetrics = metrics?.flows
    .map((flow) => ({ flow, metric: flow.metrics[descriptor.key] }))
    .filter((item): item is { flow: NonNullable<typeof metrics>["flows"][number]; metric: TimeSeriesMetric } => Boolean(item.metric));

  if (!flowMetrics || flowMetrics.length === 0) return null;

  return (
    <section className={compact ? "metric-group compact" : "metric-group"}>
      <h3>{descriptor.label}</h3>
      <div className="chart-stack">
        {flowMetrics.map(({ flow, metric }) => (
          <MetricChart key={`${flow.flowKey}:${descriptor.key}`} title={flow.label} metric={metric} height={compact ? 130 : 170} color={colorForMetric(descriptor.key)} alertContext={{ rules: alertRules, target: "flow", proto }} />
        ))}
      </div>
    </section>
  );
}

function StatsSection({ descriptors, metrics }: { descriptors: MetricDescriptor[]; metrics: StreamMetricsResponse | null }) {
  const values = metrics?.flows.flatMap((flow) =>
    descriptors.flatMap((descriptor) => {
      const latest = flow.metrics[descriptor.key]?.points.at(-1);
      const value = latest?.value ?? latest?.avg;
      return value === undefined ? [] : [{ key: `${flow.flowKey}:${descriptor.key}`, label: `${flow.role} ${descriptor.label}`, value }];
    })
  ) ?? [];

  if (values.length === 0) return null;
  return (
  options?: Array<{ value: number; label: string }>;
  apply: "live" | "next-input" | "restart" | "manual";
};

export type MaintenanceSettingsResponse = {
  revision: number;
  sections: Array<{ id: string; label: string; description?: string; settings: MaintenanceSetting[] }>;
  values: AppConfig;
};

export type ProtocolRule = { enabled?: boolean; observe?: boolean; proto: "RTP" | "SRT" | "HLS"; endpoints?: string | string[]; hosts?: string | string[]; domains?: string | string[]; decode_as?: string | string[]; fec?: boolean; vlan?: number | string | null; stream_name?: string; target_name?: string; id?: string; target_type?: "single" | "group"; };
export type ProtocolMapDocument = { observe_mode?: "all" | "configured_only" | "configured_plus_other"; protocols: ProtocolRule[]; };
export type ProtocolMapResponse = { revision: string; path: string; document: ProtocolMapDocument; apply: "restart_required"; };

export type AlertTarget = "any" | "flow" | "stream" | "interface";
export type AlertRuleType = "threshold" | "counter_delta";
export type AlertOperator = ">" | ">=" | "<" | "<=" | "==" | "!=";
export type AlertIndicatorCategory = "quality" | "other";
export type AlertRule = { id: string; enabled?: boolean; target?: AlertTarget; proto?: string; flow_roles?: string[]; indicator_category?: AlertIndicatorCategory; metric: string; type?: AlertRuleType; operator?: AlertOperator; error_threshold?: number; recover_threshold?: number; delta_threshold?: number; trigger_after_sec?: number; recover_after_sec?: number; missing_after_sec?: number; severity?: string; };
export type AlertProfile = { id: string; title?: string; rule_ids: string[]; };
export type AlertAssignmentScope = { kind: "protocol"; proto?: string; target?: AlertTarget; } | { kind: "managed_target"; target_id: string; target_type?: "single" | "group"; };
export type AlertAssignment = { scope: AlertAssignmentScope; profile_ids: string[]; overrides?: Record<string, Partial<AlertRule>>; };
export type AlertsDocument = { _note?: string; alerts?: AlertRule[]; rules?: AlertRule[]; profiles?: AlertProfile[]; assignments?: AlertAssignment[]; };
export type MonitoringTargetDefinition = { id: string; target_type: "single" | "group"; proto: string; title?: string; };
export type AlertMetricDefinition = { key: string; description?: string; unit?: string; preview: boolean; };
export type AlertsResponse = { revision: string; path: string; document: AlertsDocument; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; apply: "restart_required"; monitoringTargets: MonitoringTargetDefinition[]; };

export type BootstrapResponse = {
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  timeline: TimelineRow[];
  summary: Summary;
  events: EventLogItem[];
};

