    return index < 0 ? [...current, next] : current.map((assignment, itemIndex) => itemIndex === index ? { ...assignment, ...next } : assignment);
  });

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving"); setMessage("");
    const document: ProtocolMapDocument = { observe_mode: mode, protocols: rows.map(fromRow) };
    const alertDocument = alertSettings ? alertsDocument(alertSettings.document, assignments) : null;
    const saveAlerts = alertSettings && alertDocument && JSON.stringify(alertSettings.document.assignments ?? []) !== JSON.stringify(assignments)
      ? saveAlertsSettings(alertSettings.revision, alertDocument).then(setAlertSettings)
      : Promise.resolve();
    void saveAlerts.then(() => saveProtocolMapSettings(settings.revision, path, document)).then((next) => {
      setSettings(next); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setState("saved"); setMessage("Saved. Restart STM to apply the new Monitoring targets and alert assignments.");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to apply Monitoring targets"); });
  };

  return <PaneFrame className="maintenance-frame protocol-map-frame maintenance-floating-actions-frame" header={<PaneHeader title="Monitoring targets" icon="protocolMap" meta="STM classification, display names, and alert profile assignment" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form maintenance-form-with-floating-actions" onSubmit={submit}><div className="maintenance-form-content">
      <div className="maintenance-intro">Target name identifies this monitoring setting. Stream name is the label shown for a matched stream. Alert profiles can be assigned here; leaving it empty uses the protocol default. STM restart is required before changes take effect.</div>
      <section className="maintenance-section"><div className="maintenance-section-copy"><h2>Protocol map file</h2><p>Path relative to the STM unified config file.</p></div><div className="protocol-map-controls"><label>Path<input value={path} disabled={state === "saving"} onChange={(event) => setPath(event.target.value)} /></label><label>Observe mode<select value={mode} disabled={state === "saving"} onChange={(event) => setMode(event.target.value as ProtocolMapDocument["observe_mode"])}>{modes.map((item) => <option key={item} value={item}>{item}</option>)}</select></label></div></section>
      {locked && <div className="protocol-map-notice">all observes every classified stream. Saved rules remain available but cannot be edited in this mode.</div>}
      <section className="maintenance-section"><div className="maintenance-table-wrap"><table className="maintenance-table protocol-map-table"><colgroup><col className="protocol-map-col-index" /><col className="protocol-map-col-enabled" /><col className="protocol-map-col-target-name" /><col className="protocol-map-col-type" /><col className="protocol-map-col-protocol" /><col className="protocol-map-col-target" /><col className="protocol-map-col-address" /><col className="protocol-map-col-port" /><col className="protocol-map-col-vlan" /><col className="protocol-map-col-stream-name" /><col className="protocol-map-col-profiles" /><col className="protocol-map-col-delete" /></colgroup><thead><tr><th>#</th><th>Enabled</th><th>Target name</th><th>Type</th><th>Protocol</th><th>Target</th><th>Address / domain</th><th>Port</th><th>VLAN</th><th>Stream name</th><th>Alert profiles</th><th /></tr></thead><tbody>{rows.map((row, index) => <tr key={row.id ?? index}><td>{index + 1}</td><td><button type="button" role="switch" aria-checked={row.enabled !== false} className={`maintenance-switch ${row.enabled !== false ? "is-on" : "is-off"}`} disabled={locked || state === "saving"} onClick={() => updateRow(index, { enabled: row.enabled === false })}>{row.enabled === false ? "Off" : "On"}</button></td><td><input value={row.target_name ?? ""} placeholder="Studio A source" disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { target_name: event.target.value })} /></td><td><select value={row.target_type ?? "single"} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { target_type: event.target.value as ProtocolRule["target_type"] })}><option value="single">Single</option><option value="group">Group</option></select></td><td><select value={row.proto} disabled={locked || state === "saving"} onChange={(event) => { const proto = event.target.value as Row["proto"]; updateRow(index, { proto, target: proto === "HLS" ? row.target : "endpoint", fec: proto === "RTP-FEC" }); }}><option value="RTP">RTP</option><option value="RTP-FEC">RTP-FEC</option><option value="SRT">SRT</option><option value="HLS">HLS</option></select></td><td><select value={row.target} disabled={locked || state === "saving" || row.proto !== "HLS"} onChange={(event) => updateRow(index, { target: event.target.value as Row["target"], value: "", port: "" })}><option value="endpoint">Endpoint</option><option value="host">Host</option></select></td><td><input value={row.value} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { value: event.target.value })} placeholder={row.target === "host" ? "media.example.com" : "239.1.1.1"} /></td><td>{row.target === "endpoint" && <input type="number" min="1" max="65535" value={row.port} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { port: event.target.value })} />}</td><td><select value={row.vlanMode} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanMode: event.target.value as Row["vlanMode"] })}><option value="any">Any</option><option value="untagged">Untagged</option><option value="id">ID</option></select>{row.vlanMode === "id" && <input type="number" min="0" max="4094" value={row.vlanId} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanId: event.target.value })} />}</td><td><input value={row.stream_name ?? ""} placeholder="Camera 1" disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { stream_name: event.target.value })} /></td><td><button type="button" className="maintenance-secondary-button protocol-map-profile-button" disabled={locked || state === "saving" || !profiles.length} title={profiles.length ? "Choose one or more alert profiles." : "Create profiles in Alert policies first."} onClick={() => setProfileTargetId(row.id ?? null)}>{profileSummary(assignedProfiles(row.id ?? ""), profiles)}</button>{!profiles.length && <span className="protocol-map-