}

function ruleOverview(rule: AlertRule) { if (rule.type === "counter_delta") return rule.metric + " " + (rule.operator ?? ">") + " Δ" + String(rule.delta_threshold ?? "—") + " / " + String(rule.recover_after_sec ?? 3) + "s"; return rule.metric + " " + (rule.operator ?? ">") + " " + String(rule.error_threshold ?? "—") + " (recover " + String(rule.recover_threshold ?? "—") + ")"; }
