class bitrate {
public:
    struct result {
        bool updated{false};
        double bps{0.0};
        double elapsed{0.0};
    };

    struct snapshot {
        double bps{0.0};
        value_stats stats{};
        bool available{false};
    };

public:
    void reset_window() {
        current_time_ = -1.0;
        rec_bytes_ = 0;
        bitrate_bps_ = 0.0;
        has_sample_ = false;
    }

    void clear_stats() {
        stats_.clear();
    }

    void reset_all() {
        reset_window();
        clear_stats();
    }

    result update(double time_epoch, std::uint64_t frame_len) {
        result r{};

        if (current_time_ < 0.0) {
            current_time_ = time_epoch;
        }

        if (time_epoch < current_time_) {
            return r;
        }
        const double elapsed = time_epoch - current_time_;
        if (elapsed >= minimum_window_sec_) {
            bitrate_bps_ = static_cast<double>(rec_bytes_) * 8.0 / elapsed;
            stats_.add(bitrate_bps_);
            has_sample_ = true;

            r.updated = true;
            r.bps = bitrate_bps_;
            r.elapsed = elapsed;

            current_time_ = time_epoch;
            rec_bytes_ = 0;
        }

        rec_bytes_ += frame_len;
        return r;
    }

    snapshot snapshot_at(double /*now*/) const {
        snapshot s{
            .bps = bitrate_bps_,
            .stats = stats_,
            .available = has_sample_,
        };
        if (s.available && s.stats.count == 0) {
            s.stats.add(s.bps);
        }
        return s;
    }

    double value() const { return bitrate_bps_; }
    const value_stats& stats() const { return stats_; }

private:
    double current_time_{-1.0};
    std::uint64_t rec_bytes_{0};
    double bitrate_bps_{0.0};
    bool has_sample_{false};
    value_stats stats_{};
    static constexpr double minimum_window_sec_{1.0};
};

