import { createHash } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export type AlertTarget = "any" | "flow" | "stream" | "interface";
export type AlertRuleType = "threshold" | "counter_delta";
export type AlertOperator = ">" | ">=" | "<" | "<=" | "==" | "!=";
export type AlertIndicatorCategory = "quality" | "other";

export type AlertRule = {
  id: string;
  enabled?: boolean;
  target?: AlertTarget;
  proto?: string;
  flow_roles?: string[];
  indicator_category?: AlertIndicatorCategory;
  metric: string;
  type?: AlertRuleType;
  operator?: AlertOperator;
  error_threshold?: number;
  recover_threshold?: number;
  delta_threshold?: number;
  trigger_after_sec?: number;
  recover_after_sec?: number;
  missing_after_sec?: number;
  severity?: string;
};

export type AlertProfile = { id: string; title?: string; rule_ids: string[] };
export type AlertAssignmentScope = { kind: "protocol"; proto?: string; target?: AlertTarget } | { kind: "managed_target"; target_id: string; target_type?: "single" | "group" };
export type AlertAssignment = { scope: AlertAssignmentScope; profile_ids: string[]; overrides?: Record<string, Partial<AlertRule>> };
export type AlertsDocument = { _note?: string; alerts?: AlertRule[]; rules?: AlertRule[]; profiles?: AlertProfile[]; assignments?: AlertAssignment[] };
export type MonitoringTargetDefinition = { id: string; target_type: "single" | "group"; proto: string; title?: string };
export type AlertMetricDefinition = { key: string; description?: string; unit?: string; preview: boolean };
export type AlertsResponse = {
  revision: string;
  path: string;
  document: AlertsDocument;
  metrics: AlertMetricDefinition[];
  protocols: string[];
  flowRoles: Record<string, string[]>;
  apply: "restart_required";
  monitoringTargets: MonitoringTargetDefinition[];
};

export const supportedFlowRoles: Record<string, string[]> = { RTP: ["media", "fec_col", "fec_row"], SRT: ["data", "control", "mixed"] };

export class AlertsConflictError extends Error {}
export class AlertsValidationError extends Error {}

export class AlertsSettings {
  constructor(private readonly stmConfigFile: string) {}

  async get(): Promise<AlertsResponse> {
    const configured = await this.readConfiguredAlerts();
    const schemaText = await readFile(this.schemaFile(), "utf8");
    const document = validateDocument(parseJson(configured.alertsText, "alerts config"));
    const schema = parseSchema(parseJson(schemaText, "alerts schema"));
    const monitoring = await this.readMonitoringTargets(configured.stmConfigText);
    return {
      revision: revisionOf(configured.stmConfigText, configured.alertsText, schemaText, monitoring.sourceText),
      path: configured.relativePath,
      document,
      metrics: schema.metrics,
      protocols: schema.protocols,
      flowRoles: supportedFlowRoles,
      apply: "restart_required",
      monitoringTargets: monitoring.targets
    };
  }

  async update(input: { revision: unknown; document: unknown }): Promise<AlertsResponse> {
    const current = await this.get();
    if (typeof input.revision !== "string" || input.revision !== current.revision) {
      throw new AlertsConflictError("alerts config changed on the server; reload before applying");
    }
    const document = validateDocument(input.document, current.metrics, current.protocols);
    const configured = await this.readConfiguredAlerts();
    await atomicWrite(configured.alertsFile, JSON.stringify(document, null, 2) + "\n");
    return this.get();
  }

  private async readConfiguredAlerts() {
    const stmConfigText = await readFile(this.stmConfigFile, "utf8");
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs)
      ? stmConfig.configs as Record<string, unknown> : undefined;
    const configuredPath = configs?.alerts ?? configs?.alert_config;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) {
      throw new AlertsValidationError("configs.alerts must be a non-empty relative path");
    }
    const relativePath = validateRelativePath(configuredPath);
    const alertsFile = path.resolve(path.dirname(this.stmConfigFile), relativePath);
    const alertsText = await readFile(alertsFile, "utf8");
    return { stmConfigText, relativePath, alertsFile, alertsText };
  }

  private async readMonitoringTargets(stmConfigText: string): Promise<{ targets: MonitoringTargetDefinition[]; sourceText: string }> {
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs) ? stmConfig.configs as Record<string, unknown> : undefined;
    const configuredPath = configs?.protocol_map;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) return { targets: [], sourceText: "" };
    const sourceText = await readFile(path.resolve(path.dirname(this.stmConfigFile), validateRelativePath(configuredPath)), "utf8");
    const map = parseObject(sourceText, "protocol map");
    const protocols = Array.isArray(map.protocols) ? map.protocols : [];
    const targets = protocols.flatMap((item): MonitoringTargetDefinition[] => {
      if (!item || typeof item !== "object" || Array.isArray(item)) return [];
      const rule = item as Record<string, unknown>;
      if (typeof rule.id !== "string" || !rule.id.trim() || typeof rule.proto !== "string") return [];
      return [{ id: rule.id, proto: rule.proto, target_type: rule.target_type === "group" ? "group" : "single", ...(typeof rule.target_name === "string" ? { title: rule.target_name } : typeof rule.stream_name === "string" ? { title: rule.stream_name } : {}) }];
    });
    return { targets, sourceText };
  }

  private schemaFile() { return path.resolve(path.dirname(this.stmConfigFile), "alerts_config.schema.json"); }
}

function parseJson(text: string, label: string): unknown {
  try { return JSON.parse(text) as unknown; }
  catch (error) { throw new AlertsValidationError("invalid " + label + ": " + String(error)); }
}

function parseObject(text: string, label: string): Record<string, unknown> {
  const value = parseJson(text, label);
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError("invalid " + label + ": must be an object");
  return value as Record<string, unknown>;
}

function validateRelativePath(value: unknown) {
  if (typeof value !== "string" || !value.trim()) throw new AlertsValidationError("alerts config path is required");
  const normalized = path.posix.normalize(value.trim());
  if (path.isAbsolute(normalized) || normalized === ".." || normalized.startsWith("../")) {
    throw new AlertsValidationError("alerts config path must remain under the STM config directory");
  }
  return normalized;
}

function validateDocument(value: unknown, metrics?: AlertMetricDefinition[], protocols?: string[]): AlertsDocument {
  const root = Array.isArray(value) ? { alerts: value } : value;
  if (!root || typeof root !== "object" || Array.isArray(root)) throw new AlertsValidationError("alerts config must be an object or array");
  const record = root as Record<string, unknown>;
  if (record._note !== undefined && typeof record._note !== "string") throw new AlertsValidationError("_note must be a string");
  const note = typeof record._note === "string" ? { _note: record._note } : {};
  if (Array.isArray(record.alerts) && record.rules === undefined) {
    const alerts = record.alerts.map((rule, index) => validateRule(rule, index, metrics, protocols));
    ensureUniqueIds(alerts, "alert rule");
    return { ...note, alerts };
  }
  if (!Array.isArray(record.rules) || !Array.isArray(record.profiles) || !Array.isArray(record.assignments)) throw new AlertsValidationError("profile format requires rules, profiles, and assignments arrays");
  const rules = record.rules.map((rule, index) => validateRule(rule, index, metrics, protocols));
  ensureUniqueIds(rules, "rule");
  const ruleIds = new Set(rules.map((rule) => rule.id));
  const profiles = record.profiles.map((profile, index) => validateProfile(profile, index, ruleIds));
  ensureUniqueIds(profiles, "profile");
  const profileIds = new Set(profiles.map((profile) => profile.id));
  const assignments = record.assignments.map((assignment, index) => validateAssignment(assignment, index, profileIds, ruleIds, protocols));
  return { ...note, rules, profiles, assignments };
}

function ensureUniqueIds(items: Array<{ id: string }>, label: string) { const ids = new Set<string>(); for (const item of items) { if (ids.has(item.id)) throw new AlertsValidationError(label + " ids must be unique: " + item.id); ids.add(item.id); } }
function validateProfile(value: unknown, index: number, ruleIds: Set<string>): AlertProfile { const prefix = "profile " + (index + 1); if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError(prefix + " must be an object"); const profile = value as Record<string, unknown>; if (typeof profile.id !== "string" || !profile.id.trim()) throw new AlertsValidationError(prefix + ": id is required"); if (profile.title !== undefined && typeof profile.title !== "string") throw new AlertsValidationError(prefix + ": title must be a string"); if (!Array.isArray(profile.rule_ids) || profile.rule_ids.some((id) => typeof id !== "string" || !ruleIds.has(id))) throw new AlertsValidationError(prefix + ": rule_ids must refer to defined rules"); return { id: profile.id, ...(typeof profile.title === "string" ? { title: profile.title } : {}), rule_ids: profile.rule_ids as string[] }; }
