export type MonitoringTargetDefinition = { id: string; target_type: "single" | "group"; proto: string; title?: string; };
export type AlertMetricDefinition = { key: string; description?: string; unit?: string; preview: boolean; };
export type AlertsResponse = { revision: string; path: string; document: AlertsDocument; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; apply: "restart_required"; monitoringTargets: MonitoringTargetDefinition[]; };

export type BootstrapResponse = {
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  timeline: TimelineRow[];
  summary: Summary;
  events: EventLogItem[];
};

