		const auto pos = path.find('.', start);
		const auto end = (pos == std::string::npos) ? path.size() : pos;
		if(end > start) {
			out.emplace_back(path.substr(start, end - start));
		}
		if(pos == std::string::npos) {
			break;
		}
		start = pos + 1;
	}
	return out;
}

std::string json_string_or_empty(const json &j, const char *key) {
	if(!j.is_object() || !j.contains(key) || j[key].is_null()) {
		return {};
	}
	if(j[key].is_string()) {
		return j[key].get<std::string>();
	}
	if(j[key].is_number_integer()) {
		return std::to_string(j[key].get<long long>());
	}
	if(j[key].is_number_unsigned()) {
		return std::to_string(j[key].get<unsigned long long>());
	}
	if(j[key].is_number_float()) {
		return std::to_string(j[key].get<double>());
	}
	return {};
}

bool read_bool(const json &j, const char *key, bool fallback) {
	if(!j.contains(key) || !j[key].is_boolean()) {
		return fallback;
	}
	return j[key].get<bool>();
}

} // namespace

alert_evaluator::alert_evaluator(event_sink &events)
	: m_events(events) {
}

int alert_evaluator::load(const std::filesystem::path &path) {
	m_rules.clear();
	m_states.clear();

	if(path.empty()) {
		return 0;
	}

	std::ifstream in(path);
	if(!in) {
		std::cerr << "alert_evaluator: failed to open " << path << std::endl;
		return -1;
	}

	json root;
	try {
		in >> root;
	}
	catch(const std::exception &e) {
		std::cerr << "alert_evaluator: failed to parse " << path << ": " << e.what() << std::endl;
		return -1;
	}

	const json *rules_json = nullptr;
	const bool profile_format = root.is_object() && root.contains("rules");
	if(profile_format) {
		if(!root["rules"].is_array() || !root.contains("profiles") || !root["profiles"].is_array() || !root.contains("assignments") || !root["assignments"].is_array()) {
			std::cerr << "alert_evaluator: rules format requires rules, profiles, and assignments arrays" << std::endl; return -1;
		}
		rules_json = &root["rules"];
	}
	else if(root.is_object() && root.contains("alerts") && root["alerts"].is_array()) {
		rules_json = &root["alerts"];
	}
	else if(root.is_array()) {
		rules_json = &root;
	}
	else {
		std::cerr << "alert_evaluator: root.alerts must be an array" << std::endl;
		return -1;
	}

	for(const auto &entry : *rules_json) {
		try {
		if(!entry.is_object()) {
			std::cerr << "alert_evaluator: alert entry must be an object" << std::endl;
			return -1;
		}
		if(!entry.contains("id") || !entry["id"].is_string()) {
			std::cerr << "alert_evaluator: alert entry requires string id" << std::endl;
			return -1;
		}
		if(!entry.contains("metric") || !entry["metric"].is_string()) {
			std::cerr << "alert_evaluator: alert " << entry["id"] << " requires string metric" << std::endl;
			return -1;
		}

		rule r;
		r.id = entry["id"].get<std::string>();
		r.metric = entry["metric"].get<std::string>();
		if(entry.contains("target") && entry["target"].is_string()) r.target = entry["target"].get<std::string>();
		if(entry.contains("proto") && entry["proto"].is_string()) r.proto = entry["proto"].get<std::string>();
		if(entry.contains("flow_roles")) {
			if(!entry["flow_roles"].is_array() || r.target != "flow") throw std::runtime_error("flow_roles requires flow target");
			for(const auto &role : entry["flow_roles"]) {
				if(!role.is_string() || role.get<std::string>().empty()) throw std::runtime_error("flow_roles must contain non-empty strings");
				if(std::find(r.flow_roles.begin(), r.flow_roles.end(), role.get<std::string>()) != r.flow_roles.end()) throw std::runtime_error("flow_roles must not contain duplicates");
				r.flow_roles.push_back(role.get<std::string>());
			}
		}
		if(entry.contains("indicator_category")) {
			if(!entry["indicator_category"].is_string() || (entry["indicator_category"] != "quality" && entry["indicator_category"] != "other")) throw std::runtime_error("indicator_category must be quality or other");
			r.indicator_category = entry["indicator_category"].get<std::string>();
		}
		if(entry.contains("type") && entry["type"].is_string()) r.type = parse_rule_type(entry["type"].get<std::string>());
		if(entry.contains("operator") && entry["operator"].is_string()) r.op = parse_compare_op(entry["operator"].get<std::string>());
		if(entry.contains("error_threshold")) r.error_threshold = entry["error_threshold"].get<double>();
		if(entry.contains("recover_threshold")) r.recover_threshold = entry["recover_threshold"].get<double>();
		else r.recover_threshold = r.error_threshold;
		if(entry.contains("delta_threshold")) r.delta_threshold = entry["delta_threshold"].get<double>();
		if(entry.contains("trigger_after_sec")) r.trigger_after_sec = entry["trigger_after_sec"].get<double>();
		if(entry.contains("recover_after_sec")) r.recover_after_sec = entry["recover_after_sec"].get<double>();
		else r.recover_after_sec = r.type == rule_type::counter_delta ? 3.0 : 0.0;
		if(entry.contains("missing_after_sec")) r.missing_after_sec = entry["missing_after_sec"].get<double>();
		if(r.trigger_after_sec < 0.0 || r.recover_after_sec < 0.0 || r.missing_after_sec < 0.0) throw std::runtime_error("alert durations must be non-negative");
		if(entry.contains("severity") && entry["severity"].is_string()) r.severity = entry["severity"].get<std::string>();
		r.enabled = read_bool(entry, "enabled", true);

		m_rules.push_back(std::move(r));
		}
		catch(const std::exception &e) {
			std::cerr << "alert_evaluator: invalid alert entry: " << e.what() << std::endl;
			return -1;
		}
	}

	if(profile_format) {
		const auto library = m_rules;
		std::map<std::string, rule> rules_by_id;
		for(const auto &r : library) { if(!rules_by_id.emplace(r.id, r).second) { std::cerr << "alert_evaluator: duplicate rule id " << r.id << std::endl; return -1; } }
		std::map<std::string, std::vector<std::string>> profiles;
		for(const auto &profile : root["profiles"]) {
			if(!profile.is_object() || !profile.contains("id") || !profile["id"].is_string() || !profile.contains("rule_ids") || !profile["rule_ids"].is_array()) { std::cerr << "alert_evaluator: invalid profile" << std::endl; return -1; }
			const auto id = profile["id"].get<std::string>();
			if(id.empty() || profiles.contains(id)) { std::cerr << "alert_evaluator: duplicate or empty profile id" << std::endl; return -1; }
			auto &ids = profiles[id];
			for(const auto &rule_id : profile["rule_ids"]) { if(!rule_id.is_string() || !rules_by_id.contains(rule_id.get<std::string>())) { std::cerr << "alert_evaluator: unknown profile rule id" << std::endl; return -1; } ids.push_back(rule_id.get<std::string>()); }
		}
		m_rules.clear();
		std::set<std::string> assigned;
		for(const auto &assignment : root["assignments"]) {
			if(!assignment.is_object() || !assignment.contains("scope") || !assignment["scope"].is_object() || !assignment.contains("profile_ids") || !assignment["profile_ids"].is_array()) { std::cerr << "alert_evaluator: invalid assignment" << std::endl; return -1; }
			const auto &scope = assignment["scope"];
			if(!scope.contains("kind") || !scope["kind"].is_string()) { std::cerr << "alert_evaluator: assignment scope requires kind" << std::endl; return -1; }
			const auto kind = scope["kind"].get<std::string>();
			std::string target_id; int priority = 0; std::string scoped_proto; std::string scoped_target;
			if(kind == "protocol") { if(scope.contains("proto")) { if(!scope["proto"].is_string()) { std::cerr << "alert_evaluator: protocol scope proto must be string" << std::endl; return -1; } scoped_proto = scope["proto"].get<std::string>(); } if(scope.contains("target")) { if(!scope["target"].is_string()) { std::cerr << "alert_evaluator: protocol scope target must be string" << std::endl; return -1; } scoped_target = scope["target"].get<std::string>(); } }
			else if(kind == "managed_target") { if(!scope.contains("target_id") || !scope["target_id"].is_string() || scope["target_id"].get<std::string>().empty()) { std::cerr << "alert_evaluator: managed_target scope requires target_id" << std::endl; return -1; } target_id = scope["target_id"].get<std::string>(); priority = scope.contains("target_type") && scope["target_type"] == "group" ? 1 : 2; }
			else { std::cerr << "alert_evaluator: unknown assignment scope kind" << std::endl; return -1; }
			for(const auto &profile_id : assignment["profile_ids"]) {
				if(!profile_id.is_string() || !profiles.contains(profile_id.get<std::string>())) { std::cerr << "alert_evaluator: unknown assignment profile" << std::endl; return -1; }
				for(const auto &rule_id : profiles[profile_id.get<std::string>()]) {
					rule r = rules_by_id.at(rule_id); r.monitoring_target_id = target_id; r.scope_priority = priority; if(!scoped_proto.empty()) r.proto = scoped_proto; if(!scoped_target.empty()) r.target = scoped_target; if(!r.flow_roles.empty() && r.target != "flow") { std::cerr << "alert_evaluator: flow_roles requires flow target after assignment" << std::endl; return -1; }
					if(assignment.contains("overrides") && assignment["overrides"].is_object() && assignment["overrides"].contains(rule_id)) { const auto &o = assignment["overrides"][rule_id]; if(!o.is_object()) { std::cerr << "alert_evaluator: rule override must be object" << std::endl; return -1; } if(o.contains("enabled")) r.enabled = o["enabled"].get<bool>(); if(o.contains("severity")) r.severity = o["severity"].get<std::string>(); if(o.contains("error_threshold")) r.error_threshold = o["error_threshold"].get<double>(); if(o.contains("recover_threshold")) r.recover_threshold = o["recover_threshold"].get<double>(); if(o.contains("delta_threshold")) r.delta_threshold = o["delta_threshold"].get<double>(); if(o.contains("trigger_after_sec")) r.trigger_after_sec = o["trigger_after_sec"].get<double>(); if(o.contains("recover_after_sec")) r.recover_after_sec = o["recover_after_sec"].get<double>(); if(o.contains("missing_after_sec")) r.missing_after_sec = o["missing_after_sec"].get<double>(); }
					const auto key = r.id + "|" + target_id + "|" + std::to_string(priority); if(!assigned.insert(key).second) { std::cerr << "alert_evaluator: conflicting assignment for " << r.id << std::endl; return -1; } m_rules.push_back(std::move(r));
				}
			}
		}
	}

	return 0;
}

void alert_evaluator::evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces) {
	auto evaluate_entries = [this, now](const json::array_t &entries, bool is_interface) {
		for(const auto &entry : entries) {
			if(!entry.is_object()) continue;
			std::map<std::string, const rule *> resolved;
			for(const auto &r : m_rules) {
				if(!r.enabled || !matches_target(r, entry, is_interface)) continue;
				auto it = resolved.find(r.id);
				if(it == resolved.end() || it->second->scope_priority < r.scope_priority) resolved[r.id] = &r;
			}
			for(const auto &[id, r] : resolved) evaluate_entry(now, *r, entry, is_interface);
		}
	};
	evaluate_entries(metrics, false);
	evaluate_entries(interfaces, true);
}

json::array_t alert_evaluator::active_alerts() const {
	json::array_t out;
	for(const auto &[state_key, s] : m_states) {
		if(!s.active) {
			continue;
		}
		json entry = s.source.is_object() ? s.source : json::object();
		if(s.detail.is_object()) {
			for(const auto &[key, value] : s.detail.items()) {
				if(!entry.contains(key)) {
					entry[key] = value;
				}
			}
		}
		entry["state_key"] = state_key;
		entry["state"] = "active";
		entry["last_value"] = s.last_value;
		entry["last_error_time"] = s.last_error_time;
		entry["last_seen_time"] = s.last_seen_time;
		out.push_back(std::move(entry));
	}
	return out;
}

void alert_evaluator::evaluate_entry(double now, const rule &r, const json &entry, bool is_interface) {
	if(!matches_target(r, entry, is_interface)) return;

	const auto state_key = make_state_key(r, entry, is_interface);
	auto &s = m_states[state_key];
	auto value = metric_value(entry, r.metric);
	const bool available = value.has_value() && std::isfinite(*value);
	update_metric_availability(now, r, entry, is_interface, state_key, s, available);
	if(!available) return;

	s.last_seen_time = now;
	s.metric_available = true;
	s.metric_missing = false;
	switch(r.type) {
	case rule_type::threshold:
		evaluate_threshold(now, r, entry, is_interface, state_key, s, *value);
		break;
	case rule_type::counter_delta:
		evaluate_counter_delta(now, r, entry, is_interface, state_key, s, *value);
		break;
	}
}

void alert_evaluator::update_metric_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, bool available) {
	if(available) {
		if(s.metric_missing) emit_data_availability(now, r, entry, is_interface, state_key, true);
		s.metric_available = true;
		s.metric_missing = false;
		return;
	}
	if(!s.metric_available || r.missing_after_sec <= 0.0 || s.metric_missing || now - s.last_seen_time < r.missing_after_sec) return;
	s.metric_missing = true;
	emit_data_availability(now, r, entry, is_interface, state_key, false);
}

void alert_evaluator::evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
	if(!s.active) {
		if(!compare(value, r.op, r.error_threshold)) {
			s.error_pending_since = 0.0;
			return;
		}
		if(s.error_pending_since <= 0.0) s.error_pending_since = now;
		if(now - s.error_pending_since < r.trigger_after_sec) return;
		s.active = true;
		s.error_pending_since = 0.0;
		s.recovery_pending_since = 0.0;
		s.last_error_time = now;
		json detail{{"metric", r.metric}, {"value", value}, {"threshold", r.error_threshold}, {"operator", "error"}};
		update_active_state(now, r, entry, is_interface, s, value, detail);
		emit_alert(now, r, entry, is_interface, "detected", value, std::move(detail));
		return;
	}

	if(compare(value, r.op, r.recover_threshold)) {
		s.recovery_pending_since = 0.0;
		update_active_state(now, r, entry, is_interface, s, value, json{{"metric", r.metric}, {"value", value}, {"threshold", r.error_threshold}, {"operator", "error"}});
		return;
	}
	if(s.recovery_pending_since <= 0.0) s.recovery_pending_since = now;
	if(now - s.recovery_pending_since < r.recover_after_sec) return;
	s.active = false;
	s.recovery_pending_since = 0.0;
	emit_alert(now, r, entry, is_interface, "recovered", value, json{{"metric", r.metric}, {"value", value}, {"threshold", r.recover_threshold}, {"operator", "recover"}});
}

void alert_evaluator::evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
	if(!s.has_last_value) { s.has_last_value = true; s.last_value = value; return; }
	const double delta = value - s.last_value;
	s.last_value = value;
	if(compare(delta, r.op, r.delta_threshold)) {
		json detail{{"metric", r.metric}, {"value", value}, {"delta", delta}, {"threshold", r.delta_threshold}};
		if(!s.active) { s.active = true; emit_alert(now, r, entry, is_interface, "detected", value, detail); }
		s.last_error_time = now;
		update_active_state(now, r, entry, is_interface, s, value, std::move(detail));
		return;
	}
	if(s.active && now - s.last_error_time >= r.recover_after_sec) {
		s.active = false;
		emit_alert(now, r, entry, is_interface, "recovered", value, json{{"metric", r.metric}, {"value", value}, {"delta", delta}, {"recover_after_sec", r.recover_after_sec}});
	}
}

void alert_evaluator::emit_alert(double now, const rule &r, const json &entry, bool is_interface, std::string action, double value, json detail) {
	detail["alert_id"] = r.id;
	detail["state_key"] = make_state_key(r, entry, is_interface);
	detail["severity"] = r.severity;
	detail["indicator_category"] = r.indicator_category;
	detail["action"] = action;
	detail["value"] = value;
	detail["comparison_operator"] = compare_operator(r.op);
	detail["error_threshold"] = r.error_threshold;
	detail["recover_threshold"] = r.recover_threshold;
	detail["trigger_after_sec"] = r.trigger_after_sec;
	detail["recover_after_sec"] = r.recover_after_sec;
	detail["missing_after_sec"] = r.missing_after_sec;
	m_events.emit(event_record{.time_epoch = now, .type = action == "detected" ? "alert_detected" : "alert_recovered", .source = make_target_source(r, entry, is_interface), .detail = std::move(detail)});
}

void alert_evaluator::emit_data_availability(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, bool available) {
	json detail{{"alert_id", r.id}, {"state_key", state_key + "|data"}, {"severity", r.severity}, {"indicator_category", r.indicator_category}, {"metric", r.metric}, {"missing_after_sec", r.missing_after_sec}, {"action", available ? "available" : "unavailable"}};
	m_events.emit(event_record{.time_epoch = now, .type = available ? "alert_data_available" : "alert_data_unavailable", .source = make_target_source(r, entry, is_interface), .detail = std::move(detail)});
}

void alert_evaluator::update_active_state(double now, const rule &r, const json &entry, bool is_interface, state &s, double value, json detail) {
	detail["alert_id"] = r.id;
	detail["severity"] = r.severity;
	detail["indicator_category"] = r.indicator_category;
	detail["comparison_operator"] = compare_operator(r.op);
	detail["error_threshold"] = r.error_threshold;
	detail["recover_threshold"] = r.recover_threshold;
	detail["trigger_after_sec"] = r.trigger_after_sec;
	detail["recover_after_sec"] = r.recover_after_sec;
	detail["missing_after_sec"] = r.missing_after_sec;
	detail["value"] = value;
	s.source = make_target_source(r, entry, is_interface);
	s.detail = std::move(detail);
	s.last_value = value;
	s.last_seen_time = now;
}

std::optional<double> alert_evaluator::metric_value(const json &entry, const std::string &path) {
	const json *cur = &entry;
	for(const auto &part : split_path(path)) {
		if(!cur->is_object() || !cur->contains(part)) {
			return std::nullopt;
		}
		cur = &(*cur)[part];
	}
	if(cur->is_number()) {
		return cur->get<double>();
	}
	return std::nullopt;
}

bool alert_evaluator::compare(double lhs, compare_op op, double rhs) {
	switch(op) {
	case compare_op::gt: return lhs > rhs;
	case compare_op::ge: return lhs >= rhs;
	case compare_op::lt: return lhs < rhs;
	case compare_op::le: return lhs <= rhs;
	case compare_op::eq: return lhs == rhs;
	case compare_op::ne: return lhs != rhs;
	}
	return false;
}

std::string alert_evaluator::compare_operator(compare_op op) {
	switch(op) {
	case compare_op::gt: return ">";
	case compare_op::ge: return ">=";
	case compare_op::lt: return "<";
	case compare_op::le: return "<=";
	case compare_op::eq: return "==";
	case compare_op::ne: return "!=";
	}
	return "?";
}

bool alert_evaluator::matches_target(const rule &r, const json &entry, bool is_interface) {
	if(r.target == "interface") {
		return is_interface;
	}
	if(is_interface) {
		return r.target == "any";
	}
	if(r.target == "flow" && !entry.contains("flow_key")) {
		return false;
	}
	if(r.target == "stream" && entry.contains("flow_key")) {
		return false;
	}
	if(!r.proto.empty()) {
		const auto proto = json_string_or_empty(entry, "proto");
		if(proto != r.proto) {
			return false;
		}
	}
	if(!r.flow_roles.empty()) {
		const auto role = json_string_or_empty(entry, "role");
		if(std::find(r.flow_roles.begin(), r.flow_roles.end(), role) == r.flow_roles.end()) {
			return false;
		}
	}
	if(!r.monitoring_target_id.empty()) {
		if(!entry.contains("monitoring_target_ids") || !entry["monitoring_target_ids"].is_array()) {
			return false;
		}
		const auto &target_ids = entry["monitoring_target_ids"];
		if(std::none_of(target_ids.begin(), target_ids.end(), [&r](const json &id) {
			return id.is_string() && id.get<std::string>() == r.monitoring_target_id;
		})) {
			return false;
		}
	}
	return true;
}

std::string alert_evaluator::make_state_key(const rule &r, const json &entry, bool is_interface) {
	std::ostringstream ss;
	ss << r.id;
	if(is_interface) {
		ss << "|interface=" << json_string_or_empty(entry, "interface_id")
		   << "|name=" << json_string_or_empty(entry, "name");
		return ss.str();
	}
	ss << "|proto=" << json_string_or_empty(entry, "proto")
	   << "|stream=" << json_string_or_empty(entry, "stream_key");
	const auto flow_key = json_string_or_empty(entry, "flow_key");
	if(!flow_key.empty()) {
		ss << "|flow=" << flow_key;
	}
	return ss.str();
}

json alert_evaluator::make_target_source(const rule &r, const json &entry, bool is_interface) {
	json source{
		{"alert_id", r.id},
		{"severity", r.severity},
		{"indicator_category", r.indicator_category},
		{"target", is_interface ? "interface" : (entry.contains("flow_key") ? "flow" : "stream")},
	};
	for(const auto &key : {"proto", "stream_key", "flow_key", "interface_id", "name"}) {
		if(entry.contains(key)) {
			source[key] = entry[key];
		}
	}
	if(!r.monitoring_target_id.empty()) source["monitoring_target_id"] = r.monitoring_target_id;
	return source;
}

alert_evaluator::rule_type alert_evaluator::parse_rule_type(const std::string &value) {
	if(value == "threshold") return rule_type::threshold;
	if(value == "counter_delta") return rule_type::counter_delta;
	throw std::runtime_error("unknown alert rule type: " + value);
}

alert_evaluator::compare_op alert_evaluator::parse_compare_op(const std::string &value) {
	if(value == ">") return compare_op::gt;
	if(value == ">=") return compare_op::ge;
	if(value == "<") return compare_op::lt;
	if(value == "<=") return compare_op::le;
	if(value == "==") return compare_op::eq;
	if(value == "!=") return compare_op::ne;
	throw std::runtime_error("unknown alert operator: " + value);
}
#ifndef ALERT_EVALUATOR_H
