  // series data. Recreate the chart when either the threshold coordinates or
  // their display scale changes so the two cannot temporarily diverge.
  const thresholdSeriesSignature = displayThresholds.map((threshold) => [threshold.id, threshold.metric, threshold.value, threshold.severity, threshold.recovery, threshold.operator].join(":" )).join("|");
  const theme = document.documentElement.dataset.theme ?? "light";
  const initialAxisWidth = chartAxisWidth(Math.max(1, hostRef.current?.clientWidth || 640));
  const axisDigits = chartAxisFractionDigits(yRange.splits, displayScale, initialAxisWidth);
  chartStateRef.current = { metric, yRange, displayScale, displayThresholds, axisDigits };

  useEffect(() => {
    if (!hostRef.current || !metric || metric.points.length === 0) return;

    const host = hostRef.current;
    hostVisibleRef.current = isVisibleInViewport(host);
    const styles = getComputedStyle(hostRef.current);
    const lineColor = resolveColor(hostRef.current, color, cssVar(styles, "--chart-accent", cssVar(styles, "--accent", "currentColor")));
    const axisColor = cssVar(styles, "--chart-axis", cssVar(styles, "--muted", "currentColor"));
    const gridColor = cssVar(styles, "--chart-grid", "transparent");
