function thresholdsForMetric(metric: TimeSeriesMetric | undefined, context: ChartAlertContext | undefined): ChartThreshold[] {
  if (!metric || !context) return [];
  return context.rules.flatMap((rule) => {
    if (rule.enabled === false || (rule.type ?? "threshold") !== "threshold") return [];
    const target = rule.target ?? "any";
    if (target !== "any" && target !== context.target) return [];
    if (context.proto && rule.proto && rule.proto !== context.proto) return [];
    if (metricKeyForAlert(rule.metric) !== metric.key || !Number.isFinite(rule.error_threshold)) return [];
    const severity = rule.severity ?? "warning";
    const operator = rule.operator ?? ">";
    const result: ChartThreshold[] = [{ id: rule.id, metric: rule.metric, operator, label: `${rule.id} trigger`, value: rule.error_threshold!, severity, recovery: false }];
    if (Number.isFinite(rule.recover_threshold) && Math.abs(rule.recover_threshold! - rule.error_threshold!) > Number.EPSILON) {
      result.push({ id: rule.id + ":recovery", metric: rule.metric, operator, label: `${rule.id} recovery`, value: rule.recover_threshold!, severity, recovery: true });
    }
    return result;
  });
}

function metricKeyForAlert(key: string) {
  const parts = key.split(".");
  return chartMetricValueFields.has(parts.at(-1) ?? "") ? parts.slice(0, -1).join(".") : key;
}

function thresholdColor(severity: string) {
  if (severity === "critical" || severity === "error") return "var(--error)";
  if (severity === "warning") return "var(--warning)";
  return "var(--accent)";
}

function drawThresholdLabels(chart: uPlot, thresholds: DrawThresholdLabel[], unit: string | undefined, background: string, compact: boolean) {
  if (thresholds.length === 0) return;
  const ratio = uPlot.pxRatio;
  const fontSize = (compact ? 9 : 10) * ratio;
  const labelHeight = (compact ? 13 : 16) * ratio;
  const gap = 3 * ratio;
  const padding = 4 * ratio;
  const { left, top, width, height } = chart.bbox;
  const entries = thresholds
    .map((threshold) => ({
      threshold,
      text: threshold.metric + " " + (threshold.recovery ? "recovery" : threshold.operator) + " " + formatFixedNumber(threshold.value) + (unit ? " " + unit : ""),
      y: chart.valToPos(threshold.value, "y", true)
    }))
    .filter((entry) => entry.y >= top && entry.y <= top + height)
    .sort((a, b) => a.y - b.y);
  if (entries.length === 0) return;

  const minY = top + labelHeight / 2;
  const maxY = top + height - labelHeight / 2;
  let previousY = minY - labelHeight - gap;
  const placed = entries.map((entry) => {
    const y = Math.max(minY, entry.y, previousY + labelHeight + gap);
    previousY = y;
    return { ...entry, y };
  });
  const overflow = placed[placed.length - 1].y - maxY;
  if (overflow > 0) placed.forEach((entry) => { entry.y -= overflow; });

  const context = chart.ctx;
  context.save();
  context.font = fontSize + "px system-ui, -apple-system, BlinkMacSystemFont, sans-serif";
  context.textAlign = "right";
  context.textBaseline = "middle";
  for (const entry of placed) {
    const textWidth = context.measureText(entry.text).width;
    const x = left + width - padding;
    context.fillStyle = background;
    context.fillRect(x - textWidth - padding, entry.y - labelHeight / 2, textWidth + padding * 2, labelHeight);
import type { AlertRule, FlowMetricsResponse, MetricDescriptor, StreamMetricsResponse, StreamState, TimeSeriesMetric } from "../types/api";
import { formatBitrate, formatNumber, formatRelativeTime } from "./format";
import { MetricChart } from "./MetricChart";
import { Icon } from "./ui/Icon";
import { useI18n } from "../i18n";
import type { ResourceLoadState } from "../hooks/useResourceLoadState";
import { PaneLoadingOverlay } from "./ui/PaneLoadingOverlay";

type DetailPaneProps = {
  stream: StreamState | null;
  metrics: StreamMetricsResponse | null;
  selectedFlowKey?: string | null;
  metricsRange: string;
  onChangeMetricsRange: (range: string) => void;
  alertRules: AlertRule[];
  mode: "overview" | "detail";
  onChangeMode: (mode: "overview" | "detail") => void;
  onMinimizeWidth: () => void;
  onRestoreWidth: () => void;
  onMaximizeWidth: () => void;
  isWidthMinimized: boolean;
  isWidthRestored: boolean;
  isWidthMaximized: boolean;
  showWidthControls: boolean;
  embedded?: boolean;
  onOpenTargetPicker?: () => void;
  loadState?: ResourceLoadState;
};

const FLOW_ROLE_ACCENTS: Record<string, string> = {
  media: "var(--chart-flow-media)",
  fec_row: "var(--chart-flow-fec-row)",
  fec_col: "var(--chart-flow-fec-col)",
  control: "var(--chart-flow-control)",
  mixed: "var(--chart-flow-mixed)",
  default: "var(--chart-flow-default)"
};

export function DetailPane({
  stream,
  metrics,
  selectedFlowKey,
  metricsRange,
  onChangeMetricsRange,
  alertRules,
  mode,
  onChangeMode,
  onMinimizeWidth,
  onRestoreWidth,
  onMaximizeWidth,
  isWidthMinimized,
  isWidthRestored,
  isWidthMaximized,
  showWidthControls,
  embedded = false,
  onOpenTargetPicker,
  loadState
}: DetailPaneProps) {
  const { t } = useI18n();
  if (!stream) {
    return <aside className="detail-pane empty-state">
      <div>
        <p>Select a stream to inspect bitrate and flow metrics.</p>
        {onOpenTargetPicker && <button type="button" className="button-with-icon dashboard-detail-target inspector-target-select" onClick={onOpenTargetPicker}><Icon name="targetFollow" size={15} />{t("dashboard.selectTargetButton")}</button>}
      </div>
    </aside>;
  }

  const selectedFlow = selectedFlowKey ? stream.flows.find((flow) => flow.flowKey === selectedFlowKey) : undefined;
  const headerTargetLabel = selectedFlow
    ? stream.proto + " " + (selectedFlow.endpointSrc || "-") + " → " + (selectedFlow.endpointDst || "-")
    : stream.displayName ?? stream.label;
  const descriptors = metrics?.descriptors ?? [];
  const visibleFlows = selectedFlowKey ? stream.flows.filter((flow) => flow.flowKey === selectedFlowKey) : stream.flows;
  const visibleMetrics = metrics && selectedFlowKey
    ? { ...metrics, flows: metrics.flows.filter((flow) => flow.flowKey === selectedFlowKey) }
    : metrics;
  const primary = descriptors.filter((descriptor) => descriptor.category === "primary");
  const secondary = descriptors.filter((descriptor) => descriptor.category === "secondary");
  const stats = descriptors.filter((descriptor) => descriptor.category === "stat");

  return (
    <aside className={["detail-pane", "pane-loading-host", mode === "overview" ? "graph-mode" : "", embedded ? "detail-pane-embedded" : ""].filter(Boolean).join(" ")}>
      {!embedded && <header className="pane-header detail-header detail-header-with-mode">
        <div className="detail-heading">
          <Icon className="pane-header-icon" name="detail" size={14} />
          <h2>{headerTargetLabel}</h2>
          <p>{selectedFlowKey ? "Filtered to one flow" : `${stream.flowCount} flow${stream.flowCount === 1 ? "" : "s"}`} / last seen {formatRelativeTime(stream.lastSeen)}</p>
        </div>
        <div className="detail-header-actions">
          {onOpenTargetPicker && <button type="button" className="button-with-icon dashboard-detail-target inspector-target-select" onClick={onOpenTargetPicker}><Icon name="targetFollow" size={15} />{t("dashboard.selectTargetButton")}</button>}
          <label className="detail-range-select">
