function thresholdsForMetric(metric: TimeSeriesMetric | undefined, context: ChartAlertContext | undefined): ChartThreshold[] {
  if (!metric || !context) return [];
  return context.rules.flatMap((rule) => {
    if (rule.enabled === false || (rule.type ?? "threshold") !== "threshold") return [];
    const target = rule.target ?? "any";
    if (target !== "any" && target !== context.target) return [];
    if (context.proto && rule.proto && rule.proto !== context.proto) return [];
    if (metricKeyForAlert(rule.metric) !== metric.key || !Number.isFinite(rule.error_threshold)) return [];
    const severity = rule.severity ?? "warning";
    const operator = rule.operator ?? ">";
    const result: ChartThreshold[] = [{ id: rule.id, metric: rule.metric, operator, label: `${rule.id} trigger`, value: rule.error_threshold!, severity, recovery: false }];
    if (Number.isFinite(rule.recover_threshold) && Math.abs(rule.recover_threshold! - rule.error_threshold!) > Number.EPSILON) {
      result.push({ id: rule.id + ":recovery", metric: rule.metric, operator, label: `${rule.id} recovery`, value: rule.recover_threshold!, severity, recovery: true });
    }
    return result;
  });
}

