type RangedMetrics = { stream?: StreamMetricsResponse; interface?: InterfaceMetricsResponse };
const rangeCache = new Map<string, { time: number; value?: RangedMetrics; pending?: Promise<RangedMetrics> }>();

function useCellMetrics(cell: InspectorCell, stream: StreamState | null, interfaceItem: InterfaceListItem | null, fallbackStream: StreamMetricsResponse | null, fallbackInterface: InterfaceMetricsResponse | null) {
  const range = text(cell, "xRange") || "inherit";
  const [value, setValue] = useState<RangedMetrics>({});
  useEffect(() => {
    if (range === "inherit" || !needsSeries(cell)) { setValue({}); return; }
    let active = true;
    const load = () => cachedRangeMetrics(range, stream, interfaceItem).then((next) => { if (active) setValue(next); }).catch(() => { if (active) setValue({}); });
    void load();
    const timer = window.setInterval(() => void load(), 5000);
    return () => { active = false; window.clearInterval(timer); };
  }, [cell.id, range, stream?.streamKey, interfaceItem?.key]);
  return range === "inherit" ? { stream: fallbackStream ?? undefined, interface: fallbackInterface ?? undefined } : value;
}

