  const setScope = (next: AlertAssignment["scope"]) => onDraft({ ...draft, scope: next });
  const toggleProfile = (id: string) => onDraft({ ...draft, profile_ids: draft.profile_ids.includes(id) ? draft.profile_ids.filter((currentId) => currentId !== id) : [...draft.profile_ids, id] });
  return <aside className="alerts-profile-detail alerts-assignment-detail"><header><div><h3>{editing ? "Edit assignment" : assignmentSummary(assignment, targets)}</h3><p>{editing ? "Changes stay local until Save assignment." : selectedProfiles.length + " assigned profiles"}</p></div>{editing ? <span className="alerts-detail-actions"><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onDelete}>Delete</button><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onCancel}>Cancel</button><button type="button" className="maintenance-save-button" disabled={busy} onClick={onSave}>Save assignment</button></span> : <button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onEdit}>Edit</button>}</header>{editing ? <div className="alerts-profile-fields"><label>Scope<select value={draft.scope.kind} disabled={busy} onChange={(event) => setScope(event.target.value === "managed_target" ? { kind: "managed_target", target_id: "", target_type: "single" } : { kind: "protocol", proto: "RTP", target: "flow" })}><option value="protocol">Protocol default</option><option value="managed_target">Monitoring target</option></select></label>{draft.scope.kind === "managed_target" ? <><label>Monitoring target<TargetPicker value={draft.scope.target_id} targets={targets} busy={busy} onChange={(target_id, target_type) => setScope({ ...draft.scope, target_id, target_type } as AlertAssignment["scope"])} /></label><label>Target type<input value={draft.scope.target_type ?? "single"} readOnly /></label></> : <label>Protocol<select value={draft.scope.proto ?? ""} disabled={busy} onChange={(event) => setScope({ ...draft.scope, proto: event.target.value } as AlertAssignment["scope"])}><option value="">All protocols</option><option value="RTP">RTP</option><option value="SRT">SRT</option><option value="RTMP">RTMP</option><option value="HLS">HLS</option></select></label>}</div> : <dl className="alerts-profile-meta"><div><dt>Scope</dt><dd>{scope.kind === "managed_target" ? "Monitoring target" : "Protocol default"}</dd></div><div><dt>{scope.kind === "managed_target" ? "Monitoring target" : "Protocol"}</dt><dd>{scope.kind === "managed_target" ? targetLabelById(scope.target_id, targets) : scope.proto || "All protocols"}</dd></div>{scope.kind === "managed_target" && <div><dt>Target type</dt><dd>{scope.target_type ?? "single"}</dd></div>}</dl>}{editing && <label className="alerts-selection-search">Find profiles<input type="search" value={profileQuery} onChange={(event) => setProfileQuery(event.target.value)} placeholder="Profile ID or title…" /></label>}<h4>{editing ? "Select profiles" : "Assigned profiles"}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-profile-rules"><thead><tr>{editing && <th /> }<th>Profile ID</th><th>Title</th><th>Rules</th></tr></thead><tbody>{shownProfiles.map((profile) => <tr key={profile.id}>{editing && <td><input type="checkbox" checked={draft.profile_ids.includes(profile.id)} disabled={busy} onChange={() => toggleProfile(profile.id)} aria-label={"Assign " + profile.id} /></td>}<td>{profile.id}</td><td>{profile.title || "—"}</td><td>{profile.rule_ids.length}</td></tr>)}{shownProfiles.length === 0 && <tr><td colSpan={editing ? 4 : 3} className="alerts-empty">No profiles selected.</td></tr>}</tbody></table></div></aside>;
}
function nextProfileId(profiles: AlertProfile[]) { let n = 1; while (profiles.some((profile) => profile.id === "profile_" + n)) n += 1; return "profile_" + n; }

type AlertNumberInputProps = { value: number | undefined; unit?: string; busy: boolean; min?: number; ariaLabel: string; onValue: (value: number | undefined) => void };
function AlertNumberInput({ value, unit, busy, min, ariaLabel, onValue }: AlertNumberInputProps) {
  const [text, setText] = useState(compactInputValue(value, unit));
  const [focused, setFocused] = useState(false);
  useEffect(() => { if (!focused) setText(compactInputValue(value, unit)); }, [value, unit, focused]);
  const parsed = parseEngineeringValue(text, unit);
  const invalid = text.trim() !== "" && parsed === undefined;
  return <span className="alerts-number-field"><input type="text" inputMode="decimal" value={text} min={min} disabled={busy} aria-label={ariaLabel} aria-invalid={invalid || undefined} title={invalid ? "Use a number or k, M, G, T suffix." : undefined} onFocus={() => setFocused(true)} onChange={(event) => { const next = event.target.value; setText(next); const nextValue = parseEngineeringValue(next, unit); if (next === "" || nextValue !== undefined) onValue(next === "" ? undefined : nextValue); }} onBlur={() => { setFocused(false); setText(compactInputValue(invalid ? value : parsed, unit)); }} />{unit && <span className="alerts-input-unit" title={value === undefined ? unit : rawValue(value, unit)}>{unit}</span>}</span>;
}

function ValueHint({ value, unit }: { value: number | undefined; unit?: string }) { if (value === undefined) return null; return <span className="alerts-value-hint" title={rawValue(value, unit)}>{formatMetricValue(value, unit)}</span>; }
function RuleCondition({ rule, metric }: { rule: AlertRule; metric?: AlertMetricDefinition }) { const unit = metric?.unit; if (rule.type === "counter_delta") return <>{rule.metric} {(rule.operator ?? ">")}Δ <ValueHint value={rule.delta_threshold} unit={unit} /> / <ValueHint value={rule.recover_after_sec ?? 3} unit="s" /></>; return <>{rule.metric} {rule.operator ?? ">"} <ValueHint value={rule.error_threshold} unit={unit} /> (recover <ValueHint value={rule.recover_threshold} unit={unit} />)</>; }
function ruleConditionText(rule: AlertRule, metric?: AlertMetricDefinition) { const unit = metric?.unit; if (rule.type === "counter_delta") return rule.metric + " " + (rule.operator ?? ">") + " Δ" + formatMetricValue(rule.delta_threshold, unit) + " / " + formatMetricValue(rule.recover_after_sec ?? 3, "s"); return rule.metric + " " + (rule.operator ?? ">") + " " + formatMetricValue(rule.error_threshold, unit) + " (recover " + formatMetricValue(rule.recover_threshold, unit) + ")"; }

type AlertRowProps = { index: number; row: AlertRule; metrics: AlertMetricDefinition[]; flowRoles: Record<string, string[]>; busy: boolean; onUpdate: (index: number, patch: Partial<AlertRule>) => void; onRemove: (index: number) => void };
function AlertRow({ index, row, metrics, flowRoles, busy, onUpdate, onRemove }: AlertRowProps) {
  const availableRoles = (row.target ?? "any") === "flow" && row.proto ? flowRoles[row.proto] ?? [] : [];
  const target = row.target ?? "any";
  const type = row.type ?? "threshold";
  const candidates = metrics.filter((metric) => supportsMetric(metric, target, row.proto));
  const selected = metrics.find((metric) => metric.key === row.metric);
  const unit = selected?.unit;
  const listId = "alert-metrics-" + index;
  const changeType = (nextType: AlertRule["type"]) => {
    if (nextType === "counter_delta") onUpdate(index, { type: nextType, delta_threshold: row.delta_threshold ?? 0, recover_after_sec: row.recover_after_sec ?? 3, error_threshold: undefined, recover_threshold: undefined, trigger_after_sec: undefined });
    else onUpdate(index, { type: "threshold", operator: row.operator ?? ">", error_threshold: row.error_threshold ?? 0, recover_threshold: row.recover_threshold ?? 0, delta_threshold: undefined, recover_after_sec: row.recover_after_sec ?? 0 });
  };
  return <tr>
    <td>{index + 1}</td>
    <td><button type="button" role="switch" aria-checked={row.enabled !== false} className={"maintenance-switch " + (row.enabled !== false ? "is-on" : "is-off")} disabled={busy} onClick={() => onUpdate(index, { enabled: row.enabled === false })}>{row.enabled === false ? "Off" : "On"}</button></td>
    <td><input className="alerts-id-input" value={row.id} disabled={busy} onChange={(event) => onUpdate(index, { id: event.target.value })} /></td>
    <td><select value={target} disabled={busy || row.proto === "RTP" || row.proto === "RTMP" || row.proto === "SRT"} onChange={(event) => onUpdate(index, { target: event.target.value as AlertRule["target"], metric: "" })}><option value="flow">Flow</option><option value="stream">Stream</option><option value="interface">Interface</option><option value="any">Any</option></select></td>
    <td>{availableRoles.length > 0 ? <RolePicker roles={availableRoles} value={row.flow_roles ?? []} disabled={busy} onChange={(flow_roles) => onUpdate(index, { flow_roles })} /> : "—"}</td>
    <td><select value={row.indicator_category ?? "other"} disabled={busy} aria-label="Indicator category" onChange={(event) => onUpdate(index, { indicator_category: event.target.value as AlertRule["indicator_category"] })}><option value="other">Other</option><option value="quality">Quality</option></select></td>
    <td><input className="alerts-metric-input" list={listId} value={row.metric} disabled={busy} onChange={(event) => onUpdate(index, { metric: event.target.value })} placeholder="Search metric" title={selected?.description ? metricTooltip(selected) : undefined} aria-label={selected?.description ? "Metric: " + metricTooltip(selected) : "Metric"} /><datalist id={listId}>{candidates.map((metric) => <option key={metric.key} value={metric.key} label={metric.description ?? metric.key} />)}</datalist>{selected?.preview && <span className="alerts-preview">Preview</span>}</td>
    <td><span className="alerts-rule-controls"><select value={type} disabled={busy} onChange={(event) => changeType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option></select>{type === "threshold" && <select className="alerts-operator" value={row.operator ?? ">"} disabled={busy} onChange={(event) => onUpdate(index, { operator: event.target.value as AlertRule["operator"]})}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</span></td>
    <td><AlertNumberInput value={type === "counter_delta" ? row.delta_threshold : row.error_threshold} unit={unit} busy={busy} ariaLabel="Trigger value" onValue={(value) => onUpdate(index, type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} /></td>
    <td>{type === "counter_delta" ? <AlertNumberInput value={row.recover_after_sec} unit="s" min={0} busy={busy} ariaLabel="Recovery duration" onValue={(value) => onUpdate(index, { recover_after_sec: value })} /> : <AlertNumberInput value={row.recover_threshold} unit={unit} busy={busy} ariaLabel="Recovery value" onValue={(value) => onUpdate(index, { recover_threshold: value })} />}</td>
    <td><TimingPicker row={row} type={type} busy={busy} onUpdate={(patch) => onUpdate(index, patch)} /></td>
    <td><select value={row.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate(index, { severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td>
    <td><button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={() => onRemove(index)} aria-label="Delete alert rule" title="Delete alert rule"><Icon name="delete" size={16} /></button></td>
  </tr>;
}

type RolePickerProps = { roles: string[]; value: string[]; disabled: boolean; onChange: (value: string[] | undefined) => void };
function TimingPicker({ row, type, busy, onUpdate }: { row: AlertRule; type: AlertRule["type"]; busy: boolean; onUpdate: (patch: Partial<AlertRule>) => void }) {
  const parts = [type === "threshold" ? "On " + secondsLabel(row.trigger_after_sec) : "", type === "threshold" ? "Off " + secondsLabel(row.recover_after_sec) : "", "Missing " + secondsLabel(row.missing_after_sec)].filter(Boolean);
  return <details className={"alerts-timing-picker" + (busy ? " is-disabled" : "")}><summary aria-label="Alert timing" title={parts.join(" · ")} onClick={(event) => { if (busy) event.preventDefault(); }}><span>{parts.join(" · ")}</span></summary><div className="alerts-timing-picker-menu">{type === "threshold" && <label title="Continuous threshold breach before detection">On<AlertNumberInput value={row.trigger_after_sec} unit="s" min={0} busy={busy} ariaLabel="Trigger delay" onValue={(value) => onUpdate({ trigger_after_sec: value })} /></label>}{type === "threshold" && <label title="Continuous recovery condition before recovery">Off<AlertNumberInput value={row.recover_after_sec} unit="s" min={0} busy={busy} ariaLabel="Recovery delay" onValue={(value) => onUpdate({ recover_after_sec: value })} /></label>}<label title="Continuous missing metric time before data-unavailable alert">Missing<AlertNumberInput value={row.missing_after_sec} unit="s" min={0} busy={busy} ariaLabel="Missing metric delay" onValue={(value) => onUpdate({ missing_after_sec: value })} /></label></div></details>;
}
function secondsLabel(value: number | undefined) { return value === undefined ? "—" : formatMetricValue(value, "s"); }

function RolePicker({ roles, value, disabled, onChange }: RolePickerProps) {
  const selected = value.length ? new Set(value) : new Set(roles);
  const selectedRoles = roles.filter((role) => selected.has(role));
  const label = selectedRoles.length === roles.length ? "All roles" : selectedRoles.length === 1 ? selectedRoles[0] : selectedRoles[0] + " +" + (selectedRoles.length - 1);
  const toggle = (role: string, checked: boolean) => {
    const next = roles.filter((item) => item === role ? checked : selected.has(item));
    onChange(next.length === roles.length ? undefined : next);
  };
  return <details className={"alerts-role-picker" + (disabled ? " is-disabled" : "")}><summary aria-label="Flow roles" title={selectedRoles.join(", ")} onClick={(event) => { if (disabled) event.preventDefault(); }}>{label}</summary><div className="alerts-role-picker-menu">{roles.map((role) => <label key={role}><input type="checkbox" checked={selected.has(role)} disabled={disabled} onChange={(event) => toggle(role, event.currentTarget.checked)} />{role}</label>)}</div></details>;
}

function newRule(tab: Exclude<Tab, "all">, rows: AlertRule[]): AlertRule {
  const prefix = tab === "general" ? "general" : tab.toLowerCase();
  const id = nextId(prefix + "_rule", rows);
  if (tab === "interface") return { id, enabled: true, target: "interface", metric: "rx.errors.window", type: "counter_delta", delta_threshold: 0, recover_after_sec: 3, severity: "warning" };
import { useEffect, useMemo, useState, type FormEvent } from "react";
import { getAlertsSettings, saveAlertsSettings } from "../api/client";
import type { AlertAssignment, AlertMetricDefinition, AlertProfile, AlertRule, AlertsDocument, AlertsResponse, MonitoringTargetDefinition } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type Tab = "all" | "general" | "interface" | "RTP" | "RTMP" | "SRT" | "HLS";
type PolicyTab = "rules" | "profiles" | "assignments";
type PaneState = "loading" | "idle" | "saving" | "saved" | "error";
type AlertsPaneProps = { onSaved: (rules: AlertRule[]) => void; onOpenMonitoringTargets: () => void };

const tabs: Array<{ key: Tab; label: string }> = [
  { key: "all", label: "All" },
  { key: "general", label: "General" },
  { key: "interface", label: "Interface" },
  { key: "RTP", label: "RTP" },
  { key: "RTMP", label: "RTMP" },
  { key: "SRT", label: "SRT" },
  { key: "HLS", label: "HLS" }
];
const operators = [">", ">=", "<", "<=", "==", "!="] as const;
const severities = ["info", "warning", "error", "critical"];

export function AlertsPane({ onSaved, onOpenMonitoringTargets }: AlertsPaneProps) {
  const [settings, setSettings] = useState<AlertsResponse | null>(null);
  const [rows, setRows] = useState<AlertRule[]>([]);
  const [profiles, setProfiles] = useState<AlertProfile[]>([]);
  const [assignments, setAssignments] = useState<AlertAssignment[]>([]);
  const [profileFormat, setProfileFormat] = useState(false);
  const [policyTab, setPolicyTab] = useState<PolicyTab>("rules");
  const [tab, setTab] = useState<Tab>("all");
  const [metricQuery, setMetricQuery] = useState("");
  const [state, setState] = useState<PaneState>("loading");
  const [message, setMessage] = useState("");

  const load = () => {
    setState("loading");
    void getAlertsSettings().then((next) => {
      setSettings(next);
      setRows(next.document.alerts ?? next.document.rules ?? []);
      setProfiles(next.document.profiles ?? []);
      setAssignments(next.document.assignments ?? []);
      setProfileFormat(Boolean(next.document.rules));
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load alerts settings");
    });
  };
  useEffect(load, []);

  const visibleRows = useMemo(() => rows.map((row, index) => ({ row, index })).filter(({ row }) => (tab === "all" || ruleTab(row) === tab) && matchesRuleMetric(row, settings?.metrics ?? [], metricQuery)), [rows, settings, tab, metricQuery]);
  const updateRow = (index: number, patch: Partial<AlertRule>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
  const addRow = () => { if (tab !== "all") setRows((current) => [...current, newRule(tab, current)]); };
  const startProfiles = () => { setProfileFormat(true); setProfiles([{ id: "default", title: "Default", rule_ids: [] }]); setAssignments([]); setPolicyTab("profiles"); };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving");
    setMessage("");
    const document: AlertsDocument = profileFormat ? { ...(settings.document._note ? { _note: settings.document._note } : {}), rules: rows, profiles, assignments } : { ...(settings.document._note ? { _note: settings.document._note } : {}), alerts: rows };
    void saveAlertsSettings(settings.revision, document).then((next) => {
      setSettings(next);
      setRows(next.document.alerts ?? next.document.rules ?? []);
      setProfiles(next.document.profiles ?? []);
      setAssignments(next.document.assignments ?? []);
      setProfileFormat(Boolean(next.document.rules));
      onSaved(next.document.alerts ?? next.document.rules ?? []);
      setState("saved");
      setMessage("Saved. Restart STM to apply the new alert rules.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to apply alerts settings");
    });
  };

  return <PaneFrame className="maintenance-frame alerts-frame maintenance-floating-actions-frame" header={<PaneHeader title="Alert policies" icon="alertRules" meta="Rules, profiles, and monitoring target assignments" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form maintenance-form-with-floating-actions" onSubmit={submit}><div className="maintenance-form-content">
      <div className="maintenance-intro">Rules define alert conditions, profiles combine rules, and assignments apply profiles to protocol defaults or Monitoring targets. Apply writes <code>{settings?.path ?? "the configured alerts file"}</code>. Restart STM before the changes take effect.</div>
      <section className="maintenance-section alerts-policy-navigation">
        <div className="alerts-tabs" role="tablist" aria-label="Alert policy section">
          {([ ["rules", "Rules", rows.length], ["profiles", "Profiles", profiles.length], ["assignments", "Assignments", assignments.length] ] as const).map(([key, label, count]) => <button key={key} type="button" role="tab" aria-selected={policyTab === key} className={"alerts-tab" + (policyTab === key ? " is-active" : "")} onClick={() => setPolicyTab(key)}>{label}<span>{count}</span></button>)}
        </div>
        <div className="alerts-policy-flow" aria-label="Alert policy relationship"><span>Rules</span><b>→</b><span>Profiles</span><b>→</b><span>Assignments</span><b>→</b><button type="button" onClick={onOpenMonitoringTargets}>Monitoring targets</button></div>
      {policyTab === "rules" && <section className="maintenance-section alerts-policy-rules">
        <div className="alerts-toolbar">
        <div className="alerts-tabs" role="tablist" aria-label="Alert rule protocol">
          {tabs.map((item) => <button key={item.key} type="button" role="tab" aria-selected={tab === item.key} className={"alerts-tab" + (tab === item.key ? " is-active" : "")} onClick={() => setTab(item.key)}>{item.label}<span>{item.key === "all" ? rows.length : rows.filter((row) => ruleTab(row) === item.key).length}</span></button>)}
        </div>
        <input type="search" value={metricQuery} onChange={(event) => setMetricQuery(event.target.value)} placeholder="Rule ID, metric, bitrate…" />
        </div>
      {tab === "HLS" && <div className="protocol-map-notice">HLS candidates are preview-only. They are shown to confirm the future UI and are not emitted or evaluated by STM yet.</div>}
      <div className="alerts-rules-table-section"><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table"><colgroup><col className="alerts-col-index" /><col className="alerts-col-enabled" /><col className="alerts-col-id" /><col className="alerts-col-target" /><col className="alerts-col-role" /><col className="alerts-col-category" /><col className="alerts-col-metric" /><col className="alerts-col-rule" /><col className="alerts-col-trigger" /><col className="alerts-col-recovery" /><col className="alerts-col-timing" /><col className="alerts-col-severity" /><col className="alerts-col-delete" /></colgroup><thead><tr><th>#</th><th>Enabled</th><th>Rule ID</th><th>Target</th><th>Roles</th><th>Indicator</th><th>Metric</th><th>Rule</th><th>Trigger</th><th>Recovery</th><th>Timing</th><th>Severity</th><th /></tr></thead><tbody>
        {visibleRows.map(({ row, index }) => <AlertRow key={index} index={index} row={row} metrics={settings?.metrics ?? []} flowRoles={settings?.flowRoles ?? {}} busy={state === "saving"} onUpdate={updateRow} onRemove={removeRow} />)}
        {visibleRows.length === 0 && <tr><td colSpan={13} className="alerts-empty">{metricQuery.trim() ? "No matching alert rules in this tab." : <>No {tab === "all" ? "alert" : tab} rules.{tab === "all" ? " Choose a protocol tab to add one." : " Add a rule to begin."}</>}</td></tr>}
      </tbody></table></div><div className="protocol-map-row-actions">{tab !== "all" && <button type="button" className="maintenance-secondary-button button-with-icon" disabled={!settings || state === "saving"} onClick={addRow}><Icon name="add" size={16} />Add {tab === "general" ? "general" : tab} rule</button>}</div></div>
      </section>}
      {policyTab !== "rules" && !profileFormat && <section className="maintenance-section alerts-profile-migration"><div><h2>Use profiles and assignments</h2><p>Convert this alert policy to the profile format before assigning rules to Monitoring targets.</p></div><button type="button" className="maintenance-secondary-button" disabled={state === "saving"} onClick={startProfiles}>Enable profiles</button></section>}
      {policyTab === "profiles" && profileFormat && <ProfilesPane profiles={profiles} assignments={assignments} targets={settings?.monitoringTargets ?? []} rules={rows} metrics={settings?.metrics ?? []} busy={state === "saving"} onProfiles={setProfiles} onAssignments={setAssignments} />}
      {policyTab === "assignments" && profileFormat && <AssignmentsPane assignments={assignments} targets={settings?.monitoringTargets ?? []} profiles={profiles} busy={state === "saving"} onAssignments={setAssignments} />}
      </section>
      </div><footer className="maintenance-actions maintenance-actions-floating"><span className={"maintenance-message maintenance-message-" + state} role="status">{state === "loading" ? "Loading alert rules…" : message}</span><button type="submit" className="maintenance-save-button button-with-icon" disabled={!settings || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Applying…" : "Apply"}</button></footer>
    </form>
  </PaneFrame>;
}

function copyProfile(profile: AlertProfile): AlertProfile { return { ...profile, rule_ids: [...profile.rule_ids] }; }
function profileIsEqual(left: AlertProfile, right: AlertProfile) { return left.id === right.id && left.title === right.title && left.rule_ids.length === right.rule_ids.length && left.rule_ids.every((id, index) => id === right.rule_ids[index]); }
function ruleCondition(rule: AlertRule) { if (rule.type === "counter_delta") return rule.metric + " " + (rule.operator ?? ">") + " Δ" + String(rule.delta_threshold ?? "—") + " / " + String(rule.recover_after_sec ?? 3) + "s"; return rule.metric + " " + (rule.operator ?? ">") + " " + String(rule.error_threshold ?? "—") + " (recover " + String(rule.recover_threshold ?? "—") + ")"; }

type TargetPickerProps = { value: string; targets: MonitoringTargetDefinition[]; busy: boolean; onChange: (id: string, targetType: "single" | "group") => void };
function targetLabel(target: MonitoringTargetDefinition) { return (target.title || "Unnamed target") + " · " + target.proto + " · " + target.target_type; }
  const rules = record.rules.map((rule, index) => validateRule(rule, index, metrics, protocols));
  ensureUniqueIds(rules, "rule");
  const ruleIds = new Set(rules.map((rule) => rule.id));
  const profiles = record.profiles.map((profile, index) => validateProfile(profile, index, ruleIds));
  ensureUniqueIds(profiles, "profile");
  const profileIds = new Set(profiles.map((profile) => profile.id));
  const assignments = record.assignments.map((assignment, index) => validateAssignment(assignment, index, profileIds, ruleIds, protocols));
  return { ...note, rules, profiles, assignments };
