function mergeFlows(existing: FlowState[], incoming: FlowState[], lostSinceWall: Map<string, number>, observedAtWall?: number) {
  const byKey = new Map(existing.map((flow) => [flow.flowKey, flow]));
  const seen = new Set<string>();
  const merged = incoming.map((flow) => {
    seen.add(flow.flowKey);
    lostSinceWall.delete(flow.flowKey);
    const previous = byKey.get(flow.flowKey);
    return {
      ...previous,
      ...flow,
      lastSeen: Math.max(previous?.lastSeen ?? Number.NEGATIVE_INFINITY, flow.lastSeen),
      metrics: previous?.metrics ?? flow.metrics
    };
  });

  if (observedAtWall !== undefined) {
    for (const flow of existing) {
      if (seen.has(flow.flowKey)) continue;
      if (!lostSinceWall.has(flow.flowKey)) {
        lostSinceWall.set(flow.flowKey, observedAtWall);
      }
      merged.push({
        ...flow,
        active: false
      });
    }
  }

  return merged;
}

function streamSortScore(stream: StreamState) {
  const bitrate = stream.bitrate.value ?? stream.bitrate.avg ?? 0;
  if (!Number.isFinite(bitrate)) return 0;
  if (bitrate <= 0) return 0;
  return Math.round(bitrate / 1000) * 1000;
}

function compareStreamsStable(a: StreamState, b: StreamState, previousOrder: Map<string, number>) {
  const aScore = streamSortScore(a);
  const bScore = streamSortScore(b);
  const diff = Math.abs(aScore - bScore);
  const limit = Math.max(50000, Math.max(aScore, bScore) * 0.05);

  if (diff <= limit) {
    const aOrder = previousOrder.get(a.streamKey) ?? Number.MAX_SAFE_INTEGER;
    const bOrder = previousOrder.get(b.streamKey) ?? Number.MAX_SAFE_INTEGER;
    return aOrder - bOrder || bScore - aScore || a.streamKey.localeCompare(b.streamKey);
  }

  return bScore - aScore || a.streamKey.localeCompare(b.streamKey);
}

function buildMetrics(history: FlowMetricPoint[], keys: Set<string>): Record<string, TimeSeriesMetric> {
  const byMetric: Record<string, TimeSeriesMetric> = {};
  for (const point of history) {
    for (const [key, stat] of Object.entries(point.metrics)) {
      keys.add(key);
      const descriptor = descriptorForMetric(key);
      byMetric[key] ??= { key, label: descriptor.label, unit: descriptor.unit, points: [] };
      byMetric[key].points.push({ time: point.time, ...stat });
    }
  }
  for (const metric of Object.values(byMetric)) {
    metric.points.sort((a, b) => a.time - b.time);
  }
  return byMetric;
}

function nearestMetric(history: FlowMetricPoint[], time: number, key: string) {
  return history.find((point) => point.time === time)?.metrics[key];

