import { matchesSearch } from "./components/search";
import { Icon, type IconName } from "./components/ui/Icon";
import { useI18n } from "./i18n";

type ExpandLevel = "interface" | "proto" | "stream" | "flow";
type DetailMode = "overview" | "detail";
type DashboardSelection = { streamKey: string; flowKey: string | null } | null;
type DashboardTargetPicker = { cellId: string; mode: "follow" | "pinned" } | null;
type MainTab = "dashboard" | "streams" | "detail" | "timeline" | "topology" | "events" | "preferences" | "maintenance" | "alerts" | "protocol-map" | "help" | "information";
type MenuPlacement = "top" | "center" | "bottom";
type MenuItem = {
  type: "item";
  key: MainTab;
  icon: IconName;
  label: string;
  hint: string;
  placement: MenuPlacement;
};
type MenuSeparator = { type: "separator"; key: string; placement: MenuPlacement };
type MenuEntry = MenuItem | MenuSeparator;
type StandaloneView = "streams" | "timeline" | "events" | "detail" | "inspector-cell" | null;

const MENU_PLACEMENTS: MenuPlacement[] = ["top", "center", "bottom"];
const MENU_ITEMS: MenuEntry[] = [
    window.localStorage.setItem("stm-theme", theme);
  }, [theme]);

  useEffect(() => {
    void getAppConfig()
      .then((config) => setAppConfig(config))
      .catch(() => undefined)
      .finally(() => setAppConfigLoaded(true));
  }, []);

  useEffect(() => {
    void getAlertsSettings().then((settings) => setAlertDocument(settings.document)).catch(() => undefined);
  }, []);

  useEffect(() => {
    void getDashboardLayouts()
    && !filterStreams(streams, query).some((stream) => stream.streamKey === selection.streamKey);
}

function filterStreams(streams: StreamListItem[], query: string) {
  if (!query.trim()) return streams;
  return streams.filter((stream) =>
    matchesSearch([stream.kind, stream.displayName, stream.label, stream.streamKey, stream.interfaceName, stream.flowRoles.join(" "), ...stream.flows.map((flow) => flow.interfaceName)], query)
  );
}

function expandLevelFromParam(value: string | null): ExpandLevel {
  return value === "interface" || value === "proto" || value === "flow" || value === "stream" ? value : "stream";
}

function detailModeFromParam(value: string | null): DetailMode {
  return value === "detail" ? "detail" : "overview";
}

function rangeFromParam(value: string | null, fallback: string) {
  return value && RANGE_OPTIONS.includes(value) ? value : fallback;
}

function timelineRangeWindowSec(range: string) {
  switch (range) {
    case "24h":
      return 24 * 3600;
    case "12h":
      return 12 * 3600;
    case "6h":
      return 6 * 3600;
    case "3h":
      return 3 * 3600;
    case "1h":
      return 3600;
    case "30m":
      return 1800;
    case "10m":
      return 600;
    case "1m":
      return 60;
    case "5m":
    default:
      return 300;
  }
}

