    else onUpdate\(index, \{ type: "threshold", operator: row\.operator \?\? ">", error_threshold: row\.error_threshold \?\? 0, recover_threshold: row\.recover_threshold \?\? 0, delta_threshold: undefined, recover_after_sec: row\.recover_after_sec \?\? 0 \}\);/if (nextType === "counter_delta") onUpdate(index, { type: nextType, delta_threshold: row.delta_threshold ?? 0, recover_after_sec: row.recover_after_sec ?? 3, error_threshold: undefined, recover_threshold: undefined, trigger_after_sec: undefined, inactive_after_sec: undefined });
    else if (nextType === "availability") onUpdate(index, { type: nextType, operator: undefined, error_threshold: undefined, recover_threshold: undefined, delta_threshold: undefined, trigger_after_sec: undefined, recover_after_sec: undefined, missing_after_sec: undefined, inactive_after_sec: row.inactive_after_sec ?? 5 });
    else onUpdate(index, { type: "threshold", operator: row.operator ?? ">", error_threshold: row.error_threshold ?? 0, recover_threshold: row.recover_threshold ?? 0, delta_threshold: undefined, recover_after_sec: row.recover_after_sec ?? 0, inactive_after_sec: undefined });/; s#<option value="counter_delta">Counter delta</option>#<option value="counter_delta">Counter delta</option><option value="availability">Availability</option>#; s#<td><AlertNumberInput value=\{type === "counter_delta" \? row\.delta_threshold : row\.error_threshold\} unit=\{unit\} busy=\{busy\} ariaLabel="Trigger value" onValue=\{\(value\) => onUpdate\(index, type === "counter_delta" \? \{ delta_threshold: value \} : \{ error_threshold: value \}\)\} /></td>#<td>{type === "availability" ? <AlertNumberInput value={row.inactive_after_sec} unit="s" min={0.001} busy={busy} ariaLabel="Inactive after" onValue={(value) => onUpdate(index, { inactive_after_sec: value })} /> : <AlertNumberInput value={type === "counter_delta" ? row.delta_threshold : row.error_threshold} unit={unit} busy={busy} ariaLabel="Trigger value" onValue={(value) => onUpdate(index, type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} />}</td>#; s#<td>\{type === "counter_delta" \? <AlertNumberInput value=\{row\.recover_after_sec\} unit="s" min=\{0\} busy=\{busy\} ariaLabel="Recovery duration" onValue=\{\(value\) => onUpdate\(index, \{ recover_after_sec: value \}\)\} /> : <AlertNumberInput value=\{row\.recover_threshold\} unit=\{unit\} busy=\{busy\} ariaLabel="Recovery value" onValue=\{\(value\) => onUpdate\(index, \{ recover_threshold: value \}\)\} />\}</td>#<td>{type === "availability" ? "Packet received" : type === "counter_delta" ? <AlertNumberInput value={row.recover_after_sec} unit="s" min={0} busy={busy} ariaLabel="Recovery duration" onValue={(value) => onUpdate(index, { recover_after_sec: value })} /> : <AlertNumberInput value={row.recover_threshold} unit={unit} busy={busy} ariaLabel="Recovery value" onValue={(value) => onUpdate(index, { recover_threshold: value })} />}</td>#; s/<th>Trigger</th>/<th>Template trigger</th>/' fe/client/src/components/AlertsPane.tsx
