meta"><div><dt>Scope</dt><dd>{scope.kind === "managed_target" ? "Monitoring target" : "Protocol default"}</dd></div><div><dt>{scope.kind === "managed_target" ? "Monitoring target" : "Protocol"}</dt><dd>{scope.kind === "managed_target" ? targetLabelById(scope.target_id, targets) : scope.proto || "All protocols"}</dd></div>{scope.kind === "managed_target" && <div><dt>Target type</dt><dd>{scope.target_type ?? "single"}</dd></div>}</dl>}{editing && <label className="alerts-selection-search">Find profiles<input type="search" value={profileQuery} onChange={(event) => setProfileQuery(event.target.value)} placeholder="Profile ID or title…" /></label>}<h4>{editing ? "Select profiles" : "Assigned profiles"}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-profile-rules"><thead><tr>{editing && <th /> }<th>Profile ID</th><th>Title</th><th>Rules</th></tr></thead><tbody>{shownProfiles.map((profile) => <tr key={profile.id}>{editing && <td><input type="checkbox" checked={draft.profile_ids.includes(profile.id)} disabled={busy} onChange={() => toggleProfile(profile.id)} aria-label={"Assign " + profile.id} /></td>}<td>{profile.id}</td><td>{profile.title || "—"}</td><td>{profile.rule_ids.length}</td></tr>)}{shownProfiles.length === 0 && <tr><td colSpan={editing ? 4 : 3} className="alerts-empty">No profiles selected.</td></tr>}</tbody></table></div></aside>;
}
