function FlowMetricGroup({ descriptor, metrics, flows, compact = false, alertRules, proto }: { descriptor: MetricDescriptor; metrics: StreamMetricsResponse | null; flows: StreamState["flows"]; compact?: boolean; alertRules: AlertRule[]; proto: string }) {
  const flowMetrics = metrics?.flows
    .map((flow) => ({ flow, metric: flow.metrics[descriptor.key] }))
    .filter((item): item is { flow: NonNullable<typeof metrics>["flows"][number]; metric: TimeSeriesMetric } => Boolean(item.metric));

  if (!flowMetrics || flowMetrics.length === 0) return null;

  return (
    <section className={compact ? "metric-group compact" : "metric-group"}>
      <h3>{descriptor.label}</h3>
      <div className="chart-stack">
        {flowMetrics.map(({ flow, metric }) => (
          <MetricChart key={`${flow.flowKey}:${descriptor.key}`} title={flow.label} metric={metric} height={compact ? 130 : 170} color={colorForMetric(descriptor.key)} alertContext={{ rules: alertRules, target: "flow", proto, flowRole: flows.find((item) => item.flowKey === flow.flowKey)?.role, monitoringTargetIds: flows.find((item) => item.flowKey === flow.flowKey)?.monitoringTargetIds }} />
        ))}
      </div>
    </section>
  );

