function effectiveRules(context: ChartAlertContext): AlertRule[] {
  const document = context.document ?? (context.rules as (AlertRule[] & { document?: AlertsDocument }) | undefined)?.document;
  if (!document?.rules || !document.profiles || !document.assignments) return context.rules ?? document?.alerts ?? [];
