		trace(0, "error: pcap input source is not initialized");
		return 1;
	}
	m_second_boundary.reset();
	m_reorder.reset();
	m_reorder_tsv_ctx.reset();

	const int rc = m_pcap_source->run();
	flush_reorder_all();
	return rc;
}

