meta"><div><dt>Scope</dt><dd>{scope.kind === "managed_target" ? "Monitoring target" : "Protocol default"}</dd></div><div><dt>{scope.kind === "managed_target" ? "Monitoring target" : "Protocol"}</dt><dd>{scope.kind === "managed_target" ? targetLabelById(scope.target_id, targets) : scope.proto || "All protocols"}</dd></div>{scope.kind === "managed_target" && <div><dt>Target type</dt><dd>{scope.target_type ?? "single"}</dd></div>}</dl>}{editing && <label className="alerts-selection-search">Find profiles<input type="search" value={profileQuery} onChange={(event) => setProfileQuery(event.target.value)} placeholder="Profile ID or title…" /></label>}<h4>{editing ? "Select profiles" : "Assigned profiles"}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-profile-rules"><thead><tr>{editing && <th /> }<th>Profile ID</th><th>Title</th><th>Rules</th></tr></thead><tbody>{shownProfiles.map((profile) => <tr key={profile.id}>{editing && <td><input type="checkbox" checked={draft.profile_ids.includes(profile.id)} disabled={busy} onChange={() => toggleProfile(profile.id)} aria-label={"Assign " + profile.id} /></td>}<td>{profile.id}</td><td>{profile.title || "—"}</td><td>{profile.rule_ids.length}</td></tr>)}{shownProfiles.length === 0 && <tr><td colSpan={editing ? 4 : 3} className="alerts-empty">No profiles selected.</td></tr>}</tbody></table></div>{!editing && <><h4>Effective rules</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-profile-rules"><thead><tr><th>Rule</th><th>Template</th><th>Override</th><th>Effective</th></tr></thead><tbody>{effective.map(({ rule, override }) => <tr key={rule.id}><td>{rule.id}</td><td>{ruleCondition(rule)}</td><td>{override ? "Yes" : "—"}</td><td>{ruleCondition({ ...rule, ...(override ?? {}) })}</td></tr>)}{effective.length === 0 && <tr><td colSpan={4} className="alerts-empty">No rules are selected by this assignment.</td></tr>}</tbody></table></div></>}</aside>;
}
function effectiveAssignmentRules(assignment: AlertAssignment, profiles: AlertProfile[], rules: AlertRule[]) {
  const byId = new Map(rules.map((rule) => [rule.id, rule]));
  const seen = new Set<string>();
  return assignment.profile_ids.flatMap((profileId) => profiles.find((profile) => profile.id === profileId)?.rule_ids ?? []).flatMap((ruleId) => {
    if (seen.has(ruleId)) return [];
    seen.add(ruleId);
    const rule = byId.get(ruleId);
    return rule ? [{ rule, override: assignment.overrides?.[ruleId] }] : [];
  });
}

function nextProfileId(profiles: AlertProfile[]) { let n = 1; while (profiles.some((profile) => profile.id === "profile_" + n)) n += 1; return "profile_" + n; }
