      chartRef.current = null;
    };
  }, [metric?.key, hasData, height, color, compact, fillHeight, thresholdSeriesSignature, displayScale.divisor, renderMode, theme]);

  useEffect(() => {
    if (!chartRef.current || !metric || metric.points.length === 0) return;
