  getStream(streamKey: string) {
    return this.streams.get(streamKey);
  }

  getMetrics(streamKey: string, windowSec = this.historyWindowSec): StreamMetricsResponse | undefined {
    const stream = this.streams.get(streamKey);
    if (!stream) return undefined;

    const since = (this.latestUpdate ?? Date.now() / 1000) - windowSec;
    const metricKeys = new Set<string>();
    const flows = stream.flows.map((flow) => {
      const history = (this.flowHistory.get(flow.flowKey) ?? []).filter((point) => point.time >= since);
      const metrics = buildMetrics(history, metricKeys);
      return {
        flowKey: flow.flowKey,
        role: flow.role,
        label: flow.label,
        endpointSrc: flow.endpointSrc,
        endpointDst: flow.endpointDst,
        metrics
      };
    });

    const streamBitrate = this.buildStreamBitrate(stream, since);
    metricKeys.add("bitrate");

    const descriptors = [...metricKeys]
      .map(descriptorForMetric)
      .sort((a, b) => a.priority - b.priority || a.label.localeCompare(b.label));

    return {
      streamKey,
      windowSec,
      streamBitrate,
      flows,

  for (const file of listSampleFiles("1s", from, options.time)) {
    await readSampleRange(file, from, options.time, (sample) => {
      if (sample.metric) {
        const value = sparklineValue(sample.metric.metrics.bitrate);
        if (value !== undefined) {
          const destinations = new Set(flowToStreams.get(sample.metric.flowKey));
          if (streamKeys.has(sample.metric.streamKey)) destinations.add(sample.metric.streamKey);
          if (flowToStreams.has(sample.metric.flowKey)) addSparklineValue(flowValues, sample.metric.flowKey, sample.time, value);
          for (const streamKey of destinations) addSparklineValue(streamValues, streamKey, sample.time, value);
        }
      }
      if (sample.interface && sample.interface.hasMetrics && interfaceKeys.has(sample.interface.key)) {
        const rx = sparklineValue(sample.interface.rxBitrate);
        const tx = sparklineValue(sample.interface.txBitrate);
        if (rx === undefined && tx === undefined) return;
        const values = interfaceValues.get(sample.interface.key) ?? { rx: new Map<number, number>(), tx: new Map<number, number>() };
        if (rx !== undefined) values.rx.set(sample.time, rx);
        if (tx !== undefined) values.tx.set(sample.time, tx);
        interfaceValues.set(sample.interface.key, values);
      }
    });
  }

  return {
    streams: new Map([...streamValues].map(([key, values]) => [key, trailingSparklineValues(values, options.samples)])),
    flows: new Map([...flowValues].map(([key, values]) => [key, trailingSparklineValues(values, options.samples)])),
    interfaces: new Map([...interfaceValues].map(([key, values]) => [key, { rx: trailingSparklineValues(values.rx, options.samples), tx: trailingSparklineValues(values.tx, options.samples) }]))
  };
}

function addSparklineValue(valuesByKey: Map<string, Map<number, number>>, key: string, time: number, value: number) {
  const values = valuesByKey.get(key) ?? new Map<number, number>();
  values.set(time, (values.get(time) ?? 0) + value);
  valuesByKey.set(key, values);
}

function sparklineValue(stat: NumericStat | undefined) {
  const value = stat?.value ?? stat?.avg;
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function trailingSparklineValues(values: Map<number, number>, samples: number) {
  return [...values.entries()]
    .sort(([left], [right]) => left - right)
    .slice(-samples)
    .map(([, value]) => value);
}

function normalizeHistoricalSparklineSamples(value: number) {
  return Number.isInteger(value) && value >= MIN_HISTORICAL_SPARKLINE_SAMPLES && value <= MAX_HISTORICAL_SPARKLINE_SAMPLES ? value : 60;
}

function interfaceMetrics(item: NormalizedInterfaceInput): Record<string, NumericStat> {
  const metrics: Record<string, NumericStat> = {
    "rx.bitrate": item.rxBitrate,
    "tx.bitrate": item.txBitrate,
    "rx.packets": item.rx.packets,
    "tx.packets": item.tx.packets,
    "rx.errors": item.rx.errors,
    "tx.errors": item.tx.errors,
    "rx.dropped": item.rx.dropped,
    "tx.dropped": item.tx.dropped
  };
  if (item.rxRate?.utilization !== undefined) metrics["rx.utilization"] = scalarMetric(item.rxRate.utilization);
  if (item.txRate?.utilization !== undefined) metrics["tx.utilization"] = scalarMetric(item.txRate.utilization);
  if (item.rxRate?.headroomBps !== undefined) metrics["rx.headroom"] = scalarMetric(item.rxRate.headroomBps);
  if (item.txRate?.headroomBps !== undefined) metrics["tx.headroom"] = scalarMetric(item.txRate.headroomBps);
  return metrics;
}

