import { useEffect, useState, type CSSProperties } from "react";
import { getInterfaceMetricsByKey, getStreamMetrics, type MetricsRangeQuery } from "../api/client";
import type { AlertRule, InspectorCell, InterfaceListItem, InterfaceMetricsResponse, MetricDescriptor, StreamMetricsResponse, StreamState, TimeSeriesMetric } from "../types/api";
import { formatBitrate, formatMetricValue, metricDisplayScale, type MetricScalePreference } from "./format";
import { MetricChart, type ChartAlertContext, type ChartYScale } from "./MetricChart";
import { BandwidthUsagePanel } from "./InterfaceDetailPane";

type Props = { cell: InspectorCell; stream: StreamState | null; metrics: StreamMetricsResponse | null; selectedFlowKey: string | null; interfaceItem: InterfaceListItem | null; interfaceMetrics: InterfaceMetricsResponse | null; alertRules: AlertRule[]; };

export function InspectorCellContent({ cell, stream, metrics, selectedFlowKey, interfaceItem, interfaceMetrics, alertRules }: Props) {
  const ranged = useCellMetrics(cell, stream, interfaceItem, metrics, interfaceMetrics);
  const sourceMetrics = ranged.stream ?? metrics;
  const sourceInterfaceMetrics = ranged.interface ?? interfaceMetrics;
  const flows = stream ? (selectedFlowKey ? stream.flows.filter((flow) => flow.flowKey === selectedFlowKey) : stream.flows) : [];
  const visibleMetrics = sourceMetrics && selectedFlowKey ? { ...sourceMetrics, flows: sourceMetrics.flows.filter((flow) => flow.flowKey === selectedFlowKey) } : sourceMetrics;
  const yScale = yScaleFor(cell);
  const scalePreference = scalePreferenceFor(cell);
  const flowContext = (flow: StreamState["flows"][number], metricFlow?: StreamMetricsResponse["flows"][number]): ChartAlertContext => ({
    rules: alertRules,
    target: "flow",
    proto: stream?.proto,
    flowRole: flow.role,
    monitoringTargetIds: flow.monitoringTargetIds?.length ? flow.monitoringTargetIds : metricFlow?.monitoringTargetIds
  });
  const interfaceContext: ChartAlertContext | undefined = interfaceItem ? { rules: alertRules, target: "interface" } : undefined;
  if (cell.type === "summary") {
    if (interfaceItem && !stream) return <Summary items={[["RX", formatBitrate(interfaceItem.rxBitrate.value ?? interfaceItem.rxBitrate.avg)], ["TX", formatBitrate(interfaceItem.txBitrate.value ?? interfaceItem.txBitrate.avg)], ["Link", interfaceItem.link?.speedMbps ? String(interfaceItem.link.speedMbps) + " Mbps" : "Unknown"], ["Streams", String(interfaceItem.streamCount)]]} size={textSize(cell)} />;
    if (!stream) return <Unavailable />;
    return <Summary items={[["Total Bitrate", formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)], ["Status", stream.active ? "Active" : "Stale"], ["Flows", String(flows.length)], ["Roles", selectedFlowKey ? (flows[0]?.role ?? "flow") : (stream.flowRoles.join(", ") || "default")]]} size={textSize(cell)} />;
  }
  if (cell.type === "stream-bitrate") return stream && !selectedFlowKey ? <MetricChart title="Stream Bitrate" metric={sourceMetrics?.streamBitrate} color="var(--chart-rx)" fillHeight yScale={yScale} scalePreference={scalePreference} /> : <Unavailable message="Available for a stream selection" />;
  if (cell.type === "selected-flow-summary") { const flow = flows[0]; return stream && selectedFlowKey && flow ? <Summary items={[["Role", flow.role], ["Source", flow.endpointSrc ?? "-"], ["Destination", flow.endpointDst ?? "-"], ["Bitrate", formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)]]} size={textSize(cell)} /> : <Unavailable message="Select a flow" />; }
  if (cell.type === "flows-table") return stream ? <div className="flow-table inspector-flow-table">{flows.map((flow) => <div className="flow-row" key={flow.flowKey}><strong>{flow.role}</strong><span>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</span><span>{formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)}</span></div>)}</div> : <Unavailable />;
  if (cell.type === "interface-bandwidth") return interfaceItem && !stream ? <BandwidthUsagePanel item={interfaceItem} compact /> : <Unavailable message="Available for an interface selection" />;
  if (cell.type === "metric-chart") {
    const chart = singleMetric(cell, visibleMetrics, sourceInterfaceMetrics, selectedFlowKey);
    const chartFlow = chart?.target === "flow" && chart.flowKey ? stream?.flows.find((flow) => flow.flowKey === chart.flowKey) : undefined;
    const chartMetricFlow = chart?.target === "flow" && chart.flowKey ? visibleMetrics?.flows.find((flow) => flow.flowKey === chart.flowKey) : undefined;
    return chart ? <MetricChart title={chart.metric.label} metric={chart.metric} color={chart.target === "interface" ? (chart.metric.key.startsWith("tx.") ? "var(--chart-tx)" : "var(--chart-rx)") : "var(--chart-metric-bitrate)"} fillHeight yScale={yScale} scalePreference={scalePreference} alertContext={chart.target === "interface" ? interfaceContext : chartFlow ? flowContext(chartFlow, chartMetricFlow) : undefined} /> : <Unavailable message="Choose a metric" />;
  }
  if (cell.type === "metric-group") { const category = categoryFor(cell); const descriptors = visibleMetrics?.descriptors.filter((descriptor) => descriptor.category === category).slice(0, 8) ?? []; return descriptors.length ? <div className="inspector-metric-group">{descriptors.map((descriptor) => <MetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics!} contextForFlow={(metricFlow) => { const flow = stream?.flows.find((item) => item.flowKey === metricFlow.flowKey); return flow ? flowContext(flow, metricFlow) : undefined; }} yScale={yScale} scalePreference={scalePreference} />)}</div> : <Unavailable />; }
  if (cell.type === "all-flow-chart-group") { const descriptors = (visibleMetrics?.descriptors ?? []).filter((descriptor) => descriptor.category !== "stat" && descriptor.key !== "bitrate").sort((a, b) => a.priority - b.priority).slice(0, 5); const byFlow = new Map((visibleMetrics?.flows ?? []).map((flow) => [flow.flowKey, flow])); return stream ? <div className="inspector-all-flow-grid">{flows.map((flow) => <FlowCharts key={flow.flowKey} flow={flow} metrics={byFlow.get(flow.flowKey)?.metrics ?? {}} descriptors={descriptors} context={flowContext(flow, byFlow.get(flow.flowKey))} yScale={yScale} scalePreference={scalePreference} />)}</div> : <Unavailable />; }
  return <Unavailable />;
}

function Summary({ items, size }: { items: Array<[string, string]>; size: string }) { return <div className="graph-summary-band inspector-summary-grid" style={{ "--inspector-value-size": size } as CSSProperties}>{items.map(([label, value]) => <div className="stat-card" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>; }
function MetricGroup({ descriptor, metrics, contextForFlow, yScale, scalePreference }: { descriptor: MetricDescriptor; metrics: StreamMetricsResponse; contextForFlow?: (flow: StreamMetricsResponse["flows"][number]) => ChartAlertContext | undefined; yScale?: ChartYScale; scalePreference?: MetricScalePreference }) { const entries = metrics.flows.map((flow) => ({ flow, metric: flow.metrics[descriptor.key] })).filter((entry): entry is { flow: StreamMetricsResponse["flows"][number]; metric: TimeSeriesMetric } => Boolean(entry.metric)); return entries.length ? <section className="metric-group inspector-group"><h3>{descriptor.label}</h3><div className="chart-stack">{entries.map(({ flow, metric }) => <MetricChart key={flow.flowKey} title={flow.label} metric={metric} height={150} color="var(--chart-metric-bitrate)" alertContext={contextForFlow?.(flow)} yScale={yScale} scalePreference={scalePreference} />)}</div></section> : null; }
function FlowCharts({ flow, metrics, descriptors, context, yScale, scalePreference }: { flow: StreamState["flows"][number]; metrics: Record<string, TimeSeriesMetric>; descriptors: MetricDescriptor[]; context?: ChartAlertContext; yScale?: ChartYScale; scalePreference?: MetricScalePreference }) { const charts = [metrics.bitrate ? { key: "bitrate", metric: metrics.bitrate } : null, ...descriptors.map((descriptor) => metrics[descriptor.key] ? { key: descriptor.key, metric: metrics[descriptor.key] } : null)].filter((chart): chart is { key: string; metric: TimeSeriesMetric } => Boolean(chart)); return <section className="graph-flow-card"><div className="graph-flow-card-header"><div><strong>{flow.role}</strong><p>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</p></div><span className="graph-flow-rate">{formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)}</span></div><div className="graph-card-grid">{charts.map((chart) => <MetricChart key={chart.key} title={chart.metric.label} metric={chart.metric} compact fillHeight height={64} color="var(--chart-metric-bitrate)" alertContext={context} yScale={yScale} scalePreference={scalePreference} />)}</div></section>; }
function singleMetric(cell: InspectorCell, streamMetrics: StreamMetricsResponse | null, interfaceMetrics: InterfaceMetricsResponse | null, selectedFlowKey: string | null) { const key = text(cell, "metricKey") || "bitrate"; if (interfaceMetrics?.metrics[key]) return { metric: interfaceMetrics.metrics[key], target: "interface" as const, flowKey: undefined }; if (key === "stream-bitrate" && streamMetrics?.streamBitrate) return { metric: streamMetrics.streamBitrate, target: "flow" as const, flowKey: undefined }; const flow = selectedFlowKey ? streamMetrics?.flows.find((item) => item.flowKey === selectedFlowKey) : preferredFlow(streamMetrics?.flows ?? []); return flow?.metrics[key] ? { metric: flow.metrics[key], target: "flow" as const, flowKey: flow.flowKey } : null; }
function preferredFlow(flows: StreamMetricsResponse["flows"]) { return flows.find((flow) => flow.role === "media") ?? flows.find((flow) => flow.role === "data" || flow.role === "mixed") ?? flows[0]; }
function categoryFor(cell: InspectorCell): "primary" | "secondary" | "stat" { const value = text(cell, "category"); return value === "secondary" || value === "stat" ? value : "primary"; }
function yScaleFor(cell: InspectorCell): ChartYScale | undefined { const mode = text(cell, "yScale"); if (mode === "zero") return { mode }; if (mode === "fixed") { const min = Number(text(cell, "yMin")); const max = Number(text(cell, "yMax")); return Number.isFinite(min) && Number.isFinite(max) ? { mode, min, max } : { mode: "auto" }; } return undefined; }
