{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://example.invalid/stm/alerts_config.schema.json",
  "title": "STM alerts_config.json",
  "description": "Schema for STM alert evaluator configuration. The normal file format is an object with an alerts array; stm also accepts a bare array for compatibility.",
  "oneOf": [
    {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "alerts"
      ],
      "properties": {
        "_note": {
          "type": "string"
        },
        "alerts": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/alertRule"
          },
          "default": []
        }
      }
    },
    {
      "type": "object",
      "additionalProperties": false,
      "required": ["rules", "profiles", "assignments"],
      "properties": {
        "_note": { "type": "string" },
        "rules": { "type": "array", "items": { "$ref": "#/$defs/alertRule" } },
        "profiles": { "type": "array", "items": { "$ref": "#/$defs/profile" } },
        "assignments": { "type": "array", "items": { "$ref": "#/$defs/assignment" } }
      }
    },
    {
      "type": "array",
      "items": {
        "$ref": "#/$defs/alertRule"
      }
    }
  ],
  "$defs": {
    "profile": {
      "type": "object", "additionalProperties": false, "required": ["id", "rule_ids"],
      "properties": { "id": { "type": "string", "minLength": 1 }, "title": { "type": "string" }, "rule_ids": { "type": "array", "items": { "type": "string", "minLength": 1 } } }
    },
    "assignment": {
      "type": "object", "additionalProperties": false, "required": ["scope", "profile_ids"],
      "properties": {
        "scope": { "type": "object", "additionalProperties": false, "required": ["kind"], "properties": { "kind": { "enum": ["protocol", "managed_target"] }, "proto": { "type": "string" }, "target": { "enum": ["any", "flow", "stream", "interface"] }, "target_id": { "type": "string" }, "target_type": { "enum": ["single", "group"] } } },
        "profile_ids": { "type": "array", "items": { "type": "string", "minLength": 1 } },
        "overrides": { "type": "object", "additionalProperties": { "type": "object" } }
      }
    },
    "alertRule": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "metric"
      ],
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1,
          "description": "Stable alert rule identifier. It is used as part of the alert state key."
        },
        "enabled": {
          "type": "boolean",
          "default": true,
          "description": "When false, the rule is loaded but not evaluated."
        },
        "target": {
          "type": "string",
          "enum": [
            "any",
            "flow",
            "stream",
            "interface"
          ],
          "default": "any",
          "description": "Evaluation target. flow requires flow_key; stream excludes flow entries; interface evaluates interface metrics."
        },
        "proto": {
          "type": "string",
          "enum": [
            "RTMP",
            "RTP",
            "SRT",
            "HLS"
          ],
          "description": "Optional protocol filter. Omit this field for protocol-independent rules such as OTHER-like or interface rules. HLS metrics marked x-ui-preview are frontend-only placeholders and are not emitted by the backend yet."
        },
        "flow_roles": {
          "type": "array",
          "uniqueItems": true,
          "items": { "type": "string", "minLength": 1 },
          "description": "Optional flow role filter. It applies only to flow target rules; omit to evaluate every role."
        },
        "metric": {
          "type": "string",
          "oneOf": [
            {
              "const": "bandwidth.avg",
              "description": "Average SRT bandwidth estimate decoder value. Unit follows the tshark SRT decoder output.",
              "x-unit": "decoder-unit"
            },
            {
