type AlertRowProps = { index: number; row: AlertRule; metrics: AlertMetricDefinition[]; flowRoles: Record<string, string[]>; busy: boolean; onUpdate: (index: number, patch: Partial<AlertRule>) => void; onRemove: (index: number) => void };
