    <td><input className="alerts-metric-input" list={listId} value={row.metric} disabled={busy} onChange={(event) => onUpdate(index, { metric: event.target.value })} placeholder="Search metric" title={selected?.description ? metricTooltip(selected) : undefined} aria-label={selected?.description ? "Metric: " + metricTooltip(selected) : "Metric"} /><datalist id={listId}>{candidates.map((metric) => <option key={metric.key} value={metric.key} label={metric.description ?? metric.key} />)}</datalist>{selected?.preview && <span className="alerts-preview">Preview</span>}</td>
    <td><span className="alerts-rule-controls"><select value={type} disabled={busy} onChange={(event) => changeType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option><option value="availability">Availability</option></select>{type === "threshold" && <select className="alerts-operator" value={row.operator ?? ">"} disabled={busy} onChange={(event) => onUpdate(index, { operator: event.target.value as AlertRule["operator"]})}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</span></td>
    <td>{type === "availability" ? <AlertNumberInput value={row.inactive_after_sec} unit="s" min={0.001} busy={busy} ariaLabel="Inactive after" onValue={(value) => onUpdate(index, { inactive_after_sec: value })} /> : <AlertNumberInput value={type === "counter_delta" ? row.delta_threshold : row.error_threshold} unit={unit} busy={busy} ariaLabel="Trigger value" onValue={(value) => onUpdate(index, type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} />}</td>
    <td>{type === "availability" ? "Packet received" : type === "counter_delta" ? <AlertNumberInput value={row.recover_after_sec} unit="s" min={0} busy={busy} ariaLabel="Recovery duration" onValue={(value) => onUpdate(index, { recover_after_sec: value })} /> : <AlertNumberInput value={row.recover_threshold} unit={unit} busy={busy} ariaLabel="Recovery value" onValue={(value) => onUpdate(index, { recover_threshold: value })} />}</td>
