std::optional<double> alert_evaluator::metric_value(const json &entry, const std::string &path) {
	const json *cur = &entry;
	for(const auto &part : split_path(path)) {
		if(!cur->is_object() || !cur->contains(part)) {
			return std::nullopt;
		}
		cur = &(*cur)[part];
	}
	if(cur->is_number()) {
		return cur->get<double>();
	}
	return std::nullopt;
}

bool alert_evaluator::compare(double lhs, compare_op op, double rhs) {
	switch(op) {
	case compare_op::gt: return lhs > rhs;
	case compare_op::ge: return lhs >= rhs;
	case compare_op::lt: return lhs < rhs;
	case compare_op::le: return lhs <= rhs;
	case compare_op::eq: return lhs == rhs;
	case compare_op::ne: return lhs != rhs;
	}
	return false;
}

std::string alert_evaluator::compare_operator(compare_op op) {
	switch(op) {
	case compare_op::gt: return ">";
	case compare_op::ge: return ">=";
	case compare_op::lt: return "<";
	case compare_op::le: return "<=";
	case compare_op::eq: return "==";
	case compare_op::ne: return "!=";
	}
	return "?";
}

bool alert_evaluator::matches_target(const rule &r, const json &entry, bool is_interface) {
	if(r.target == "interface") {
		return is_interface;
	}
	if(is_interface) {
		return r.target == "any";
