  flowKey: string;
  role: string;
  label: string;
  scope: NetworkScope;
  active: boolean;
  interfaceId?: number;
  interfaceName?: string;
  endpointSrc?: string;
  endpointDst?: string;
  monitoringTargetIds?: string[];
  lastSeen: number;
  bitrate: NumericStat;
  protocolDetails?: ProtocolDetail[];
  alert?: StreamAlertSummary;
  recentAlert?: StreamAlertSummary;
  sparkline: number[];
  overview: OverviewStats;
};

