function thresholdsForMetric(metric: TimeSeriesMetric | undefined, context: ChartAlertContext | undefined): ChartThreshold[] {
  if (!metric || !context) return [];
  return effectiveRules(context).flatMap((rule) => {
    if (rule.enabled === false || (rule.type ?? "threshold") !== "threshold") return [];
    const target = rule.target ?? "any";
    if (target !== "any" && target !== context.target) return [];
    if (context.proto && rule.proto && rule.proto !== context.proto) return [];
    if (context.flowRole && rule.flow_roles?.length && !rule.flow_roles.includes(context.flowRole)) return [];
    if (metricKeyForAlert(rule.metric) !== metric.key || !Number.isFinite(rule.error_threshold)) return [];
    const severity = rule.severity ?? "warning";
    const operator = rule.operator ?? ">";
    const result: ChartThreshold[] = [{ id: rule.id, metric: rule.metric, operator, label: `${rule.id} trigger`, value: rule.error_threshold!, severity, recovery: false }];
    if (Number.isFinite(rule.recover_threshold) && Math.abs(rule.recover_threshold! - rule.error_threshold!) > Number.EPSILON) {
      result.push({ id: rule.id + ":recovery", metric: rule.metric, operator, label: `${rule.id} recovery`, value: rule.recover_threshold!, severity, recovery: true });
    }
    return result;
  });
}

function effectiveRules(context: ChartAlertContext): AlertRule[] {
  const document = context.document ?? (context.rules as (AlertRule[] & { document?: AlertsDocument }) | undefined)?.document;
  if (!document?.rules || !document.profiles || !document.assignments) return context.rules ?? document?.alerts ?? [];
  const rulesById = new Map(document.rules.map((rule) => [rule.id, rule]));
  const profiles = new Map(document.profiles.map((profile) => [profile.id, profile]));
  const resolved = new Map<string, { priority: number; rule: AlertRule }>();
  for (const assignment of document.assignments) {
    const priority = assignmentPriority(assignment, context);
    if (priority < 0) continue;
    for (const profileId of assignment.profile_ids) {
      for (const ruleId of profiles.get(profileId)?.rule_ids ?? []) {
        const base = rulesById.get(ruleId);
        if (!base) continue;
        const candidate = { ...base, ...(assignment.overrides?.[ruleId] ?? {}) };
        const current = resolved.get(ruleId);
        if (!current || priority > current.priority) resolved.set(ruleId, { priority, rule: candidate });
      }
    }
  }
  return [...resolved.values()].map((entry) => entry.rule);
}

function assignmentPriority(assignment: AlertAssignment, context: ChartAlertContext) {
  const scope = assignment.scope;
  if (scope.kind === "protocol") {
    if (scope.proto && scope.proto !== context.proto) return -1;
    if (scope.target && scope.target !== "any" && scope.target !== context.target) return -1;
    return 0;
  }
  if (!context.monitoringTargetIds?.includes(scope.target_id)) return -1;
  return scope.target_type === "group" ? 1 : 2;
}

function metricKeyForAlert(key: string) {
  const parts = key.split(".");
  return chartMetricValueFields.has(parts.at(-1) ?? "") ? parts.slice(0, -1).join(".") : key;
}

function thresholdColor(severity: string) {
  if (severity === "critical" || severity === "error") return "var(--error)";
  if (severity === "warning") return "var(--warning)";
  return "var(--accent)";
}

function drawThresholdLabels(chart: uPlot, thresholds: DrawThresholdLabel[], unit: string | undefined, background: string, compact: boolean) {
  if (thresholds.length === 0) return;
  const ratio = uPlot.pxRatio;
  const fontSize = (compact ? 9 : 10) * ratio;
  const labelHeight = (compact ? 13 : 16) * ratio;
  const gap = 3 * ratio;
  const padding = 4 * ratio;
  const { left, top, width, height } = chart.bbox;
  const entries = thresholds
    .map((threshold) => ({
      threshold,
      text: threshold.metric + " " + (threshold.recovery ? "recovery" : threshold.operator) + " " + formatFixedNumber(threshold.value) + (unit ? " " + unit : ""),
      y: chart.valToPos(threshold.value, "y", true)
    }))
    .filter((entry) => entry.y >= top && entry.y <= top + height)
    .sort((a, b) => a.y - b.y);
  if (entries.length === 0) return;

  const minY = top + labelHeight / 2;
  const maxY = top + height - labelHeight / 2;
  let previousY = minY - labelHeight - gap;
  const placed = entries.map((entry) => {
    const y = Math.max(minY, entry.y, previousY + labelHeight + gap);
    previousY = y;
    return { ...entry, y };
  });
  const overflow = placed[placed.length - 1].y - maxY;
  if (overflow > 0) placed.forEach((entry) => { entry.y -= overflow; });

  const context = chart.ctx;
  context.save();
  for (const entry of entries) {
    context.beginPath();
    context.strokeStyle = entry.threshold.color;
    context.lineWidth = (entry.threshold.recovery ? 1 : 1.5) * ratio;
    context.setLineDash(entry.threshold.recovery ? [5 * ratio, 4 * ratio] : []);
    context.moveTo(left, entry.y);
    context.lineTo(left + width, entry.y);
    context.stroke();
  }
  context.setLineDash([]);
  context.font = fontSize + "px system-ui, -apple-system, BlinkMacSystemFont, sans-serif";
  context.textAlign = "right";
  context.textBaseline = "middle";
  for (const entry of placed) {
    const textWidth = context.measureText(entry.text).width;
    const x = left + width - padding;
    context.fillStyle = background;
    context.fillRect(x - textWidth - padding, entry.y - labelHeight / 2, textWidth + padding * 2, labelHeight);
    context.fillStyle = entry.threshold.color;
    context.fillText(entry.text, x, entry.y);
  }
  context.restore();
}

