import { useEffect, useMemo, useState, type FormEvent } from "react";
import { getAlertsSettings, saveAlertsSettings } from "../api/client";
import type { AlertAssignment, AlertMetricDefinition, AlertProfile, AlertRule, AlertsDocument, AlertsResponse, MonitoringTargetDefinition } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type Tab = "all" | "general" | "interface" | "RTP" | "RTMP" | "SRT" | "HLS";
type PolicyTab = "rules" | "profiles" | "assignments";
type PaneState = "loading" | "idle" | "saving" | "saved" | "error";
type AlertsPaneProps = { onSaved: (document: AlertsDocument) => void; onOpenMonitoringTargets: () => void };

const tabs: Array<{ key: Tab; label: string }> = [
  { key: "all", label: "All" },
  { key: "general", label: "General" },
  { key: "interface", label: "Interface" },
  { key: "RTP", label: "RTP" },
  { key: "RTMP", label: "RTMP" },
  { key: "SRT", label: "SRT" },
  { key: "HLS", label: "HLS" }
];
const operators = [">", ">=", "<", "<=", "==", "!="] as const;
const severities = ["info", "warning", "error", "critical"];

export function AlertsPane({ onSaved, onOpenMonitoringTargets }: AlertsPaneProps) {
  const [settings, setSettings] = useState<AlertsResponse | null>(null);
  const [rows, setRows] = useState<AlertRule[]>([]);
  const [profiles, setProfiles] = useState<AlertProfile[]>([]);
  const [assignments, setAssignments] = useState<AlertAssignment[]>([]);
  const [profileFormat, setProfileFormat] = useState(false);
  const [policyTab, setPolicyTab] = useState<PolicyTab>("rules");
  const [tab, setTab] = useState<Tab>("all");
  const [metricQuery, setMetricQuery] = useState("");
  const [state, setState] = useState<PaneState>("loading");
  const [message, setMessage] = useState("");

  const load = () => {
    setState("loading");
    void getAlertsSettings().then((next) => {
      setSettings(next);
      setRows(next.document.alerts ?? next.document.rules ?? []);
      setProfiles(next.document.profiles ?? []);
      setAssignments(next.document.assignments ?? []);
      setProfileFormat(Boolean(next.document.rules));
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load alerts settings");
    });
  };
  useEffect(load, []);

  const visibleRows = useMemo(() => rows.map((row, index) => ({ row, index })).filter(({ row }) => (tab === "all" || ruleTab(row) === tab) && matchesRuleMetric(row, settings?.metrics ?? [], metricQuery)), [rows, settings, tab, metricQuery]);
  const updateRow = (index: number, patch: Partial<AlertRule>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
  const addRow = () => { if (tab !== "all") setRows((current) => [...current, newRule(tab, current)]); };
  const startProfiles = () => { setProfileFormat(true); setProfiles([{ id: "default", title: "Default", rule_ids: [] }]); setAssignments([]); setPolicyTab("profiles"); };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving");
    setMessage("");
    const document: AlertsDocument = profileFormat ? { ...(settings.document._note ? { _note: settings.document._note } : {}), rules: rows, profiles, assignments } : { ...(settings.document._note ? { _note: settings.document._note } : {}), alerts: rows };
    void saveAlertsSettings(settings.revision, document).then((next) => {
      setSettings(next);
      setRows(next.document.alerts ?? next.document.rules ?? []);
      setProfiles(next.document.profiles ?? []);
      setAssignments(next.document.assignments ?? []);
      setProfileFormat(Boolean(next.document.rules));
      onSaved(next.document);
      setState("saved");
      setMessage("Saved. Restart STM to apply the new alert rules.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to apply alerts settings");
    });
  };

  return <PaneFrame className="maintenance-frame alerts-frame maintenance-floating-actions-frame" header={<PaneHeader title="Alert policies" icon="alertRules" meta="Rules, profiles, and monitoring target assignments" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form maintenance-form-with-floating-actions" onSubmit={submit}><div className="maintenance-form-content">
      <div className="maintenance-intro">Rules define alert conditions, profiles combine rules, and assignments apply profiles to protocol defaults or Monitoring targets. Apply writes <code>{settings?.path ?? "the configured alerts file"}</code>. Restart STM before the changes take effect.</div>
      <section className="maintenance-section alerts-policy-navigation">
        <div className="alerts-tabs" role="tablist" aria-label="Alert policy section">
          {([ ["rules", "Rules", rows.length], ["profiles", "Profiles", profiles.length], ["assignments", "Assignments", assignments.length] ] as const).map(([key, label, count]) => <button key={key} type="button" role="tab" aria-selected={policyTab === key} className={"alerts-tab" + (policyTab === key ? " is-active" : "")} onClick={() => setPolicyTab(key)}>{label}<span>{count}</span></button>)}
        </div>
        <div className="alerts-policy-flow" aria-label="Alert policy relationship"><span>Rules</span><b>→</b><span>Profiles</span><b>→</b><span>Assignments</span><b>→</b><button type="button" onClick={onOpenMonitoringTargets}>Monitoring targets</button></div>
      {policyTab === "rules" && <section className="maintenance-section alerts-policy-rules">
        <div className="alerts-toolbar">
        <div className="alerts-tabs" role="tablist" aria-label="Alert rule protocol">
          {tabs.map((item) => <button key={item.key} type="button" role="tab" aria-selected={tab === item.key} className={"alerts-tab" + (tab === item.key ? " is-active" : "")} onClick={() => setTab(item.key)}>{item.label}<span>{item.key === "all" ? rows.length : rows.filter((row) => ruleTab(row) === item.key).length}</span></button>)}
        </div>
        <input type="search" value={metricQuery} onChange={(event) => setMetricQuery(event.target.value)} placeholder="Rule ID, metric, bitrate…" />
        </div>
      {tab === "HLS" && <div className="protocol-map-notice">HLS candidates are preview-only. They are shown to confirm the future UI and are not emitted or evaluated by STM yet.</div>}
      <div className="alerts-rules-table-section"><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table"><colgroup><col className="alerts-col-index" /><col className="alerts-col-enabled" /><col className="alerts-col-id" /><col className="alerts-col-target" /><col className="alerts-col-role" /><col className="alerts-col-category" /><col className="alerts-col-metric" /><col className="alerts-col-rule" /><col className="alerts-col-trigger" /><col className="alerts-col-recovery" /><col className="alerts-col-timing" /><col className="alerts-col-severity" /><col className="alerts-col-delete" /></colgroup><thead><tr><th>#</th><th>Enabled</th><th>Rule ID</th><th>Target</th><th>Roles</th><th>Indicator</th><th>Metric</th><th>Rule</th><th>Template trigger</th><th>Recovery</th><th>Timing</th><th>Severity</th><th /></tr></thead><tbody>
        {visibleRows.map(({ row, index }) => <AlertRow key={index} index={index} row={row} metrics={settings?.metrics ?? []} flowRoles={settings?.flowRoles ?? {}} busy={state === "saving"} onUpdate={updateRow} onRemove={removeRow} />)}
        {visibleRows.length === 0 && <tr><td colSpan={13} className="alerts-empty">{metricQuery.trim() ? "No matching alert rules in this tab." : <>No {tab === "all" ? "alert" : tab} rules.{tab === "all" ? " Choose a protocol tab to add one." : " Add a rule to begin."}</>}</td></tr>}
      </tbody></table></div><div className="protocol-map-row-actions">{tab !== "all" && <button type="button" className="maintenance-secondary-button button-with-icon" disabled={!settings || state === "saving"} onClick={addRow}><Icon name="add" size={16} />Add {tab === "general" ? "general" : tab} rule</button>}</div></div>
      </section>}
      {policyTab !== "rules" && !profileFormat && <section className="maintenance-section alerts-profile-migration"><div><h2>Use profiles and assignments</h2><p>Convert this alert policy to the profile format before assigning rules to Monitoring targets.</p></div><button type="button" className="maintenance-secondary-button" disabled={state === "saving"} onClick={startProfiles}>Enable profiles</button></section>}
      {policyTab === "profiles" && profileFormat && <ProfilesPane profiles={profiles} assignments={assignments} targets={settings?.monitoringTargets ?? []} rules={rows} metrics={settings?.metrics ?? []} busy={state === "saving"} onProfiles={setProfiles} onAssignments={setAssignments} />}
      {policyTab === "assignments" && profileFormat && <AssignmentsPane assignments={assignments} targets={settings?.monitoringTargets ?? []} profiles={profiles} rules={rows} busy={state === "saving"} onAssignments={setAssignments} />}
      </section>
      </div><footer className="maintenance-actions maintenance-actions-floating"><span className={"maintenance-message maintenance-message-" + state} role="status">{state === "loading" ? "Loading alert rules…" : message}</span><button type="submit" className="maintenance-save-button button-with-icon" disabled={!settings || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Applying…" : "Apply"}</button></footer>
    </form>
  </PaneFrame>;
}

function copyProfile(profile: AlertProfile): AlertProfile { return { ...profile, rule_ids: [...profile.rule_ids] }; }
function profileIsEqual(left: AlertProfile, right: AlertProfile) { return left.id === right.id && left.title === right.title && left.rule_ids.length === right.rule_ids.length && left.rule_ids.every((id, index) => id === right.rule_ids[index]); }
function ruleCondition(rule: AlertRule) { if (rule.type === "counter_delta") return rule.metric + " " + (rule.operator ?? ">") + " Δ" + String(rule.delta_threshold ?? "—") + " / " + String(rule.recover_after_sec ?? 3) + "s"; return rule.metric + " " + (rule.operator ?? ">") + " " + String(rule.error_threshold ?? "—") + " (recover " + String(rule.recover_threshold ?? "—") + ")"; }

type TargetPickerProps = { value: string; targets: MonitoringTargetDefinition[]; busy: boolean; onChange: (id: string, targetType: "single" | "group") => void };
function targetLabel(target: MonitoringTargetDefinition) { return (target.title || "Unnamed target") + " · " + target.proto + " · " + target.target_type; }
function targetLabelById(id: string, targets: MonitoringTargetDefinition[]) { const target = targets.find((item) => item.id === id); return target ? targetLabel(target) : "Unavailable target"; }
function TargetPicker({ value, targets, busy, onChange }: TargetPickerProps) {
  return <select value={value} disabled={busy} aria-label="Select Monitoring Target" onChange={(event) => { const target = targets.find((item) => item.id === event.target.value); if (target) onChange(target.id, target.target_type); }}><option value="">Select target</option>{targets.map((target) => <option key={target.id} value={target.id}>{targetLabel(target)}</option>)}</select>;
}

type ProfilesPaneProps = { profiles: AlertProfile[]; assignments: AlertAssignment[]; targets: MonitoringTargetDefinition[]; rules: AlertRule[]; metrics: AlertMetricDefinition[]; busy: boolean; onProfiles: (profiles: AlertProfile[]) => void; onAssignments: (assignments: AlertAssignment[]) => void };
function ProfilesPane({ profiles, assignments, targets, rules, metrics, busy, onProfiles, onAssignments }: ProfilesPaneProps) {
  const [selectedId, setSelectedId] = useState<string | null>(profiles[0]?.id ?? null);
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState<AlertProfile | null>(profiles[0] ? copyProfile(profiles[0]) : null);
  const selected = profiles.find((profile) => profile.id === selectedId) ?? null;
  useEffect(() => { if (!selectedId || !profiles.some((profile) => profile.id === selectedId)) setSelectedId(profiles[0]?.id ?? null); }, [profiles, selectedId]);
  useEffect(() => { if (selected && !editing) setDraft(copyProfile(selected)); }, [selected, editing]);
  const selectProfile = (profile: AlertProfile) => { if (editing && draft && selected && !profileIsEqual(draft, selected) && !window.confirm("Discard unsaved profile changes and switch profiles?")) return; setSelectedId(profile.id); setDraft(copyProfile(profile)); setEditing(false); };
  const newProfile = () => { const profile = { id: nextProfileId(profiles), title: "", rule_ids: [] }; onProfiles([...profiles, profile]); setSelectedId(profile.id); setDraft(copyProfile(profile)); setEditing(true); };
  const saveProfile = () => { if (!selected || !draft) return; onProfiles(profiles.map((profile) => profile.id === selected.id ? copyProfile(draft) : profile)); if (draft.id !== selected.id) onAssignments(assignments.map((assignment) => ({ ...assignment, profile_ids: assignment.profile_ids.map((id) => id === selected.id ? draft.id : id) }))); setSelectedId(draft.id); setEditing(false); };
  const toggleRule = (id: string) => { if (!draft) return; setDraft({ ...draft, rule_ids: draft.rule_ids.includes(id) ? draft.rule_ids.filter((current) => current !== id) : [...draft.rule_ids, id] }); };
  const deleteProfile = () => { if (!selected || !window.confirm("Delete this profile and remove it from its assignments?")) return; onProfiles(profiles.filter((profile) => profile.id !== selected.id)); onAssignments(assignments.map((assignment) => ({ ...assignment, profile_ids: assignment.profile_ids.filter((id) => id !== selected.id) }))); setSelectedId(profiles.find((profile) => profile.id !== selected.id)?.id ?? null); setEditing(false); };
  const uses = (profileId: string) => assignments.filter((assignment) => assignment.profile_ids.includes(profileId));
  return <section className="maintenance-section alerts-master-section"><div className="alerts-master-workspace"><div className="alerts-master-list"><div className="maintenance-table-wrap"><table className="maintenance-table alerts-master-table"><thead><tr><th>#</th><th>Profile ID</th><th>Title</th><th>Rules</th><th>Assignments</th></tr></thead><tbody>{profiles.map((profile, index) => <tr key={profile.id} className={profile.id === selected?.id ? "is-selected" : ""} onClick={() => selectProfile(profile)}><td>{index + 1}</td><td>{profile.id}</td><td>{profile.title || "—"}</td><td>{profile.rule_ids.length}</td><td>{uses(profile.id).length}</td></tr>)}{profiles.length === 0 && <tr><td colSpan={5} className="alerts-empty">No profiles. Add a profile to begin.</td></tr>}</tbody></table></div><div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={newProfile}><Icon name="add" size={16} />Add profile</button></div></div><ProfileDetail profile={selected} draft={draft} editing={editing} rules={rules} metrics={metrics} assignments={selected ? uses(selected.id) : []} targets={targets} busy={busy} onEdit={() => { if (selected) { setDraft(copyProfile(selected)); setEditing(true); } }} onCancel={() => { if (selected) setDraft(copyProfile(selected)); setEditing(false); }} onSave={saveProfile} onDraft={setDraft} onToggleRule={toggleRule} onDelete={deleteProfile} /></div></section>;
}

type ProfileDetailProps = { profile: AlertProfile | null; draft: AlertProfile | null; editing: boolean; rules: AlertRule[]; metrics: AlertMetricDefinition[]; assignments: AlertAssignment[]; targets: MonitoringTargetDefinition[]; busy: boolean; onEdit: () => void; onCancel: () => void; onSave: () => void; onDraft: (profile: AlertProfile) => void; onToggleRule: (id: string) => void; onDelete: () => void };
function ProfileDetail({ profile, draft, editing, rules, metrics, assignments, targets, busy, onEdit, onCancel, onSave, onDraft, onToggleRule, onDelete }: ProfileDetailProps) {
  const [ruleQuery, setRuleQuery] = useState("");
  if (!profile || !draft) return <aside className="alerts-profile-detail"><p>Select a profile to view its settings.</p></aside>;
  const included = rules.filter((rule) => (editing ? draft.rule_ids : profile.rule_ids).includes(rule.id));
  const shownRules = (editing ? rules : included).filter((rule) => matchesSearch(ruleQuery, rule.id, rule.metric, rule.proto, rule.severity, ruleConditionText(rule, metrics.find((metric) => metric.key === rule.metric))));
  return <aside className="alerts-profile-detail"><header><div><h3>{editing ? "Edit profile" : profile.id}</h3><p>{editing ? "Changes stay local until Save profile." : profile.title || "No title"}</p></div>{editing ? <span className="alerts-detail-actions"><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onDelete}>Delete</button><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onCancel}>Cancel</button><button type="button" className="maintenance-save-button" disabled={busy} onClick={onSave}>Save profile</button></span> : <button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onEdit}>Edit</button>}</header>{editing ? <div className="alerts-profile-fields"><label>Profile ID<input value={draft.id} disabled={busy} onChange={(event) => onDraft({ ...draft, id: event.target.value })} /></label><label>Title<input value={draft.title ?? ""} disabled={busy} onChange={(event) => onDraft({ ...draft, title: event.target.value })} /></label></div> : <dl className="alerts-profile-meta"><div><dt>Rule count</dt><dd>{profile.rule_ids.length}</dd></div><div><dt>Assignments</dt><dd>{assignments.length}</dd></div></dl>}{editing && <label className="alerts-selection-search">Find rules<input type="search" value={ruleQuery} onChange={(event) => setRuleQuery(event.target.value)} placeholder="Rule ID, metric, severity…" /></label>}<h4>{editing ? "Select rules" : "Included rules"}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-profile-rules"><thead><tr>{editing && <th /> }<th>Rule</th><th>Condition</th><th>Severity</th><th>State</th></tr></thead><tbody>{shownRules.map((rule) => <tr key={rule.id}>{editing && <td><input type="checkbox" checked={draft.rule_ids.includes(rule.id)} disabled={busy} onChange={() => onToggleRule(rule.id)} aria-label={"Include " + rule.id} /></td>}<td>{rule.id}</td><td><RuleCondition rule={rule} metric={metrics.find((metric) => metric.key === rule.metric)} /></td><td>{rule.severity ?? "warning"}</td><td>{rule.enabled === false ? "Off" : "On"}</td></tr>)}{shownRules.length === 0 && <tr><td colSpan={editing ? 5 : 4} className="alerts-empty">No rules selected.</td></tr>}</tbody></table></div>{!editing && <><h4>Applied assignments</h4><ul className="alerts-assignment-summary">{assignments.map((assignment, index) => <li key={index}>{assignmentSummary(assignment, targets)}</li>)}{assignments.length === 0 && <li>No assignments.</li>}</ul></>}</aside>;
}

function assignmentSummary(assignment: AlertAssignment, targets: MonitoringTargetDefinition[] = []) { const scope = assignment.scope; return scope.kind === "managed_target" ? "Monitoring Target · " + targetLabelById(scope.target_id, targets) : "Protocol default · " + (scope.proto ?? "all"); }
function copyAssignment(assignment: AlertAssignment): AlertAssignment { return { ...assignment, scope: { ...assignment.scope }, profile_ids: [...assignment.profile_ids] }; }
function assignmentIsEqual(left: AlertAssignment, right: AlertAssignment) { return JSON.stringify(left) === JSON.stringify(right); }
type AssignmentsPaneProps = { assignments: AlertAssignment[]; targets: MonitoringTargetDefinition[]; profiles: AlertProfile[]; rules: AlertRule[]; busy: boolean; onAssignments: (assignments: AlertAssignment[]) => void };
function AssignmentsPane({ assignments, targets, profiles, rules, busy, onAssignments }: AssignmentsPaneProps) {
  const [selectedIndex, setSelectedIndex] = useState<number | null>(assignments.length ? 0 : null);
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState<AlertAssignment | null>(assignments[0] ? copyAssignment(assignments[0]) : null);
  const selected = selectedIndex === null ? null : assignments[selectedIndex] ?? null;
  useEffect(() => { if (selectedIndex === null || !assignments[selectedIndex]) setSelectedIndex(assignments.length ? 0 : null); }, [assignments, selectedIndex]);
  useEffect(() => { if (selected && !editing) setDraft(copyAssignment(selected)); }, [selected, editing]);
  const selectAssignment = (index: number) => { if (editing && draft && selected && !assignmentIsEqual(draft, selected) && !window.confirm("Discard unsaved assignment changes and switch assignments?")) return; setSelectedIndex(index); setDraft(copyAssignment(assignments[index])); setEditing(false); };
  const addAssignment = () => { const assignment: AlertAssignment = { scope: { kind: "protocol", proto: "RTP", target: "flow" }, profile_ids: [] }; onAssignments([...assignments, assignment]); setSelectedIndex(assignments.length); setDraft(copyAssignment(assignment)); setEditing(true); };
  const saveAssignment = () => { if (selectedIndex === null || !draft) return; onAssignments(assignments.map((assignment, index) => index === selectedIndex ? copyAssignment(draft) : assignment)); setEditing(false); };
  const deleteAssignment = () => { if (selectedIndex === null || !window.confirm("Delete this assignment?")) return; onAssignments(assignments.filter((_, index) => index !== selectedIndex)); setSelectedIndex(assignments.length > 1 ? Math.min(selectedIndex, assignments.length - 2) : null); setEditing(false); };
  return <section className="maintenance-section alerts-master-section"><div className="alerts-master-workspace"><div className="alerts-master-list"><div className="maintenance-table-wrap"><table className="maintenance-table alerts-master-table"><thead><tr><th>#</th><th>Scope</th><th>Target / Protocol</th><th>Type</th><th>Profiles</th></tr></thead><tbody>{assignments.map((assignment, index) => { const scope = assignment.scope; const target = scope.kind === "managed_target" ? targetLabelById(scope.target_id, targets) : (scope.proto || "All protocols"); return <tr key={index} className={index === selectedIndex ? "is-selected" : ""} onClick={() => selectAssignment(index)}><td>{index + 1}</td><td>{scope.kind === "managed_target" ? "Monitoring target" : "Protocol default"}</td><td>{target}</td><td>{scope.kind === "managed_target" ? (scope.target_type ?? "single") : "—"}</td><td>{assignment.profile_ids.length}</td></tr>; })}{assignments.length === 0 && <tr><td colSpan={5} className="alerts-empty">No assignments. Add an assignment to begin.</td></tr>}</tbody></table></div><div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={addAssignment}><Icon name="add" size={16} />Add assignment</button></div></div><AssignmentDetail assignment={selected} draft={draft} profiles={profiles} rules={rules} targets={targets} busy={busy} editing={editing} onEdit={() => { if (selected) { setDraft(copyAssignment(selected)); setEditing(true); } }} onCancel={() => { if (selected) setDraft(copyAssignment(selected)); setEditing(false); }} onSave={saveAssignment} onDelete={deleteAssignment} onDraft={setDraft} /></div></section>;
}

type AssignmentDetailProps = { assignment: AlertAssignment | null; draft: AlertAssignment | null; profiles: AlertProfile[]; rules: AlertRule[]; targets: MonitoringTargetDefinition[]; busy: boolean; editing: boolean; onEdit: () => void; onCancel: () => void; onSave: () => void; onDelete: () => void; onDraft: (assignment: AlertAssignment) => void };
function AssignmentDetail({ assignment, draft, profiles, rules, targets, busy, editing, onEdit, onCancel, onSave, onDelete, onDraft }: AssignmentDetailProps) {
  const [profileQuery, setProfileQuery] = useState("");
  if (!assignment || !draft) return <aside className="alerts-profile-detail"><p>Select an assignment to view its settings.</p></aside>;
  const current = editing ? draft : assignment;
  const scope = current.scope;
  const selectedProfiles = current.profile_ids.map((id) => profiles.find((profile) => profile.id === id) ?? { id, title: "Undefined profile", rule_ids: [] });
  const candidateProfiles = editing ? [...profiles, ...draft.profile_ids.filter((id) => !profiles.some((profile) => profile.id === id)).map((id) => ({ id, title: "Undefined profile", rule_ids: [] }))] : selectedProfiles;
  const shownProfiles = candidateProfiles.filter((profile) => matchesSearch(profileQuery, profile.id, profile.title, String(profile.rule_ids.length)));
  const effective = effectiveAssignmentRules(current, profiles, rules);
  const setScope = (next: AlertAssignment["scope"]) => onDraft({ ...draft, scope: next });
  const toggleProfile = (id: string) => onDraft({ ...draft, profile_ids: draft.profile_ids.includes(id) ? draft.profile_ids.filter((currentId) => currentId !== id) : [...draft.profile_ids, id] });
  return <aside className="alerts-profile-detail alerts-assignment-detail"><header><div><h3>{editing ? "Edit assignment" : assignmentSummary(assignment, targets)}</h3><p>{editing ? "Changes stay local until Save assignment." : selectedProfiles.length + " assigned profiles"}</p></div>{editing ? <span className="alerts-detail-actions"><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onDelete}>Delete</button><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onCancel}>Cancel</button><button type="button" className="maintenance-save-button" disabled={busy} onClick={onSave}>Save assignment</button></span> : <button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onEdit}>Edit</button>}</header>{editing ? <div className="alerts-profile-fields"><label>Scope<select value={draft.scope.kind} disabled={busy} onChange={(event) => setScope(event.target.value === "managed_target" ? { kind: "managed_target", target_id: "", target_type: "single" } : { kind: "protocol", proto: "RTP", target: "flow" })}><option value="protocol">Protocol default</option><option value="managed_target">Monitoring target</option></select></label>{draft.scope.kind === "managed_target" ? <><label>Monitoring target<TargetPicker value={draft.scope.target_id} targets={targets} busy={busy} onChange={(target_id, target_type) => setScope({ ...draft.scope, target_id, target_type } as AlertAssignment["scope"])} /></label><label>Target type<input value={draft.scope.target_type ?? "single"} readOnly /></label></> : <label>Protocol<select value={draft.scope.proto ?? ""} disabled={busy} onChange={(event) => setScope({ ...draft.scope, proto: event.target.value } as AlertAssignment["scope"])}><option value="">All protocols</option><option value="RTP">RTP</option><option value="SRT">SRT</option><option value="RTMP">RTMP</option><option value="HLS">HLS</option></select></label>}</div> : <dl className="alerts-profile-meta"><div><dt>Scope</dt><dd>{scope.kind === "managed_target" ? "Monitoring target" : "Protocol default"}</dd></div><div><dt>{scope.kind === "managed_target" ? "Monitoring target" : "Protocol"}</dt><dd>{scope.kind === "managed_target" ? targetLabelById(scope.target_id, targets) : scope.proto || "All protocols"}</dd></div>{scope.kind === "managed_target" && <div><dt>Target type</dt><dd>{scope.target_type ?? "single"}</dd></div>}</dl>}{editing && <label className="alerts-selection-search">Find profiles<input type="search" value={profileQuery} onChange={(event) => setProfileQuery(event.target.value)} placeholder="Profile ID or title…" /></label>}<h4>{editing ? "Select profiles" : "Assigned profiles"}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-profile-rules"><thead><tr>{editing && <th /> }<th>Profile ID</th><th>Title</th><th>Rules</th></tr></thead><tbody>{shownProfiles.map((profile) => <tr key={profile.id}>{editing && <td><input type="checkbox" checked={draft.profile_ids.includes(profile.id)} disabled={busy} onChange={() => toggleProfile(profile.id)} aria-label={"Assign " + profile.id} /></td>}<td>{profile.id}</td><td>{profile.title || "—"}</td><td>{profile.rule_ids.length}</td></tr>)}{shownProfiles.length === 0 && <tr><td colSpan={editing ? 4 : 3} className="alerts-empty">No profiles selected.</td></tr>}</tbody></table></div>{!editing && <><h4>Effective rules</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-profile-rules"><thead><tr><th>Rule</th><th>Template</th><th>Override</th><th>Effective</th></tr></thead><tbody>{effective.map(({ rule, override }) => <tr key={rule.id}><td>{rule.id}</td><td>{ruleCondition(rule)}</td><td>{override ? "Yes" : "—"}</td><td>{ruleCondition({ ...rule, ...(override ?? {}) })}</td></tr>)}{effective.length === 0 && <tr><td colSpan={4} className="alerts-empty">No rules are selected by this assignment.</td></tr>}</tbody></table></div></>}</aside>;
}
function effectiveAssignmentRules(assignment: AlertAssignment, profiles: AlertProfile[], rules: AlertRule[]) {
  const byId = new Map(rules.map((rule) => [rule.id, rule]));
  const seen = new Set<string>();
  return assignment.profile_ids.flatMap((profileId) => profiles.find((profile) => profile.id === profileId)?.rule_ids ?? []).flatMap((ruleId) => {
    if (seen.has(ruleId)) return [];
    seen.add(ruleId);
    const rule = byId.get(ruleId);
    return rule ? [{ rule, override: assignment.overrides?.[ruleId] }] : [];
  });
}

function nextProfileId(profiles: AlertProfile[]) { let n = 1; while (profiles.some((profile) => profile.id === "profile_" + n)) n += 1; return "profile_" + n; }

type AlertNumberInputProps = { value: number | undefined; unit?: string; busy: boolean; min?: number; ariaLabel: string; onValue: (value: number | undefined) => void };
function AlertNumberInput({ value, unit, busy, min, ariaLabel, onValue }: AlertNumberInputProps) {
