  const availableRoles = (row.target ?? "any") === "flow" && row.proto ? flowRoles[row.proto] ?? [] : [];
  const target = row.target ?? "any";
  const type = row.type ?? "threshold";
  const candidates = metrics.filter((metric) => supportsMetric(metric, target, row.proto));
  const selected = metrics.find((metric) => metric.key === row.metric);
  const unit = selected?.unit;
  const listId = "alert-metrics-" + index;
  const changeType = (nextType: AlertRule["type"]) => {
    if (nextType === "counter_delta") onUpdate(index, { type: nextType, delta_threshold: row.delta_threshold ?? 0, recover_after_sec: row.recover_after_sec ?? 3, error_threshold: undefined, recover_threshold: undefined, trigger_after_sec: undefined, inactive_after_sec: undefined });
    else if (nextType === "availability") onUpdate(index, { type: nextType, operator: undefined, error_threshold: undefined, recover_threshold: undefined, delta_threshold: undefined, trigger_after_sec: undefined, recover_after_sec: undefined, missing_after_sec: undefined, inactive_after_sec: row.inactive_after_sec ?? 5 });
    else onUpdate(index, { type: "threshold", operator: row.operator ?? ">", error_threshold: row.error_threshold ?? 0, recover_threshold: row.recover_threshold ?? 0, delta_threshold: undefined, recover_after_sec: row.recover_after_sec ?? 0, inactive_after_sec: undefined });
  };
