import json
from pathlib import Path


def threshold(id, proto, roles, metric, operator, value, severity='warning', category=None):
    rule = {
        'id': id, 'target': 'flow', 'proto': proto, 'flow_roles': roles,
        'metric': metric, 'type': 'threshold', 'operator': operator,
        'error_threshold': value, 'recover_threshold': value,
        'trigger_after_sec': 1, 'recover_after_sec': 1, 'severity': severity,
    }
    if category:
        rule['indicator_category'] = category
    return rule


def availability(id, proto, roles):
    return {
        'id': id, 'target': 'flow', 'proto': proto, 'flow_roles': roles,
        'metric': 'bitrate.bps', 'type': 'availability',
        'inactive_after_sec': 5, 'severity': 'error',
    }


def rate_conditions(prefix, proto, roles):
    return [
        threshold('bitrate-low', proto, roles, 'bitrate.bps', '<', 1_600_000),
        threshold('bitrate-high', proto, roles, 'bitrate.bps', '>', 2_400_000),
        availability('availability', proto, roles),
    ]


def jitter_conditions(proto, roles):
    return [
        threshold('jitter-low', proto, roles, 'jitter.avg', '<', 0.0005),
        threshold('jitter-high', proto, roles, 'jitter.avg', '>', 0.0020),
    ]


def quality_conditions(proto, roles):
    return [
        threshold('loss', proto, roles, 'seq_stats.gap.window', '>', 0, 'error', 'quality'),
        threshold('duplicate', proto, roles, 'seq_stats.dup.window', '>', 0, 'error', 'quality'),
        threshold('reorder', proto, roles, 'seq_stats.reorder.window', '>', 0, 'error', 'quality'),
    ]

