    {'id': 'rtp-rate-quality', 'title': 'RTP media bitrate, availability, and quality errors', 'conditions': rate_conditions('rtp', 'RTP', rtp_roles) + quality_conditions('RTP', rtp_roles)},
    {'id': 'srt-rate', 'title': 'SRT data bitrate and availability', 'conditions': rate_conditions('srt', 'SRT', srt_roles)},
    {'id': 'srt-rate-jitter', 'title': 'SRT data bitrate, availability, and jitter', 'conditions': rate_conditions('srt', 'SRT', srt_roles) + jitter_conditions('SRT', srt_roles)},
    {'id': 'srt-rate-quality', 'title': 'SRT data bitrate, availability, and quality errors', 'conditions': rate_conditions('srt', 'SRT', srt_roles) + quality_conditions('SRT', srt_roles)},
]


