    adjusted('sg.srt.bitrate-step', 'srt-rate', {'bitrate-low': 1_000_000, 'bitrate-high': 2_500_000}),
    adjusted('sg.srt.jitter-fixed', 'srt-rate-jitter', {'jitter-low': 0.0005, 'jitter-high': 0.025}),
    adjusted('sg.srt.jitter-random', 'srt-rate-jitter', {'jitter-low': 0.0005, 'jitter-high': 0.0020}),
    shared('sg.srt.errors', 'srt-rate-quality'),
