    if (scope.target && scope.target !== "any" && scope.target !== context.target) return -1;
    return 0;
  }
  if (!context.monitoringTargetIds?.includes(scope.target_id)) return -1;
  return scope.target_type === "group" ? 1 : 2;
}

export function policyTitle(document: AlertsDocument, policyId: string | undefined) {
  if (!policyId) return undefined;
  const policy = document.policies.find((item) => item.id === policyId);
  return policy?.title || policy?.id || policyId;
}

export function emptyDocument(): AlertsDocument {
  return { policies: [], bindings: [] };
}

export function replaceBinding(document: AlertsDocument, next: AlertBinding) {
  const key = bindingKey(next);
  const bindings = document.bindings.some((binding) => bindingKey(binding) === key)
    ? document.bindings.map((binding) => bindingKey(binding) === key ? next : binding)
    : [...document.bindings, next];
  return { ...document, bindings };
}

export function removeBinding(document: AlertsDocument, scope: AlertBindingScope) {
  const key = scope.kind === "protocol" ? "protocol:" + (scope.proto ?? "") + ":" + (scope.target ?? "any") : "managed_target:" + scope.target_id;
  return { ...document, bindings: document.bindings.filter((binding) => bindingKey(binding) !== key) };
