import { useEffect, useState, type FormEvent } from "react";
import { getAlertsSettings, getProtocolMapSettings, saveAlertsSettings, saveProtocolMapSettings } from "../api/client";
import type { AlertAssignment, AlertRule, AlertsDocument, AlertsResponse, ProtocolMapDocument, ProtocolMapResponse, ProtocolRule } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type Row = Omit<ProtocolRule, "proto"> & { proto: ProtocolRule["proto"] | "RTP-FEC"; target: "endpoint" | "host"; value: string; port: string; vlanMode: "any" | "untagged" | "id"; vlanId: string };

const modes = ["all", "configured_only", "configured_plus_other"] as const;

export function ProtocolMapPane() {
  const [settings, setSettings] = useState<ProtocolMapResponse | null>(null);
  const [alertSettings, setAlertSettings] = useState<AlertsResponse | null>(null);
  const [path, setPath] = useState("");
  const [mode, setMode] = useState<ProtocolMapDocument["observe_mode"]>("all");
  const [rows, setRows] = useState<Row[]>([]);
  const [assignments, setAssignments] = useState<AlertAssignment[]>([]);
  const [profileTargetId, setProfileTargetId] = useState<string | null>(null);
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");
  const locked = mode === "all";
  const profiles = alertSettings?.document.profiles ?? [];
  const profileTarget = rows.find((row) => row.id === profileTargetId) ?? null;

  const load = () => {
    setState("loading");
    void Promise.all([getProtocolMapSettings(), getAlertsSettings()]).then(([next, alerts]) => {
      setSettings(next); setAlertSettings(alerts); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setAssignments(alerts.document.assignments ?? []); setState("idle"); setMessage("");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to load Monitoring targets"); });
  };
  useEffect(load, []);

  const updateRow = (index: number, patch: Partial<Row>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => {
    const id = rows[index]?.id;
    setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
    if (id) setAssignments((current) => current.filter((assignment) => assignment.scope.kind !== "managed_target" || assignment.scope.target_id !== id));
  };
  const addRow = () => setRows((current) => [...current, { enabled: true, observe: true, id: newTargetId(), target_type: "single", target_name: "", proto: "RTP", target: "endpoint", value: "", port: "", vlanMode: "any", vlanId: "" }]);
  const assignedProfiles = (id: string) => assignments.find((assignment) => assignment.scope.kind === "managed_target" && assignment.scope.target_id === id)?.profile_ids ?? [];
  const setAssignedProfiles = (row: Row, profileIds: string[]) => setAssignments((current) => {
    const index = current.findIndex((assignment) => assignment.scope.kind === "managed_target" && assignment.scope.target_id === row.id);
    if (!profileIds.length) return index < 0 ? current : current.filter((_, itemIndex) => itemIndex !== index);
    const next = { scope: { kind: "managed_target" as const, target_id: row.id ?? newTargetId(), target_type: row.target_type ?? "single" }, profile_ids: profileIds };
    return index < 0 ? [...current, next] : current.map((assignment, itemIndex) => itemIndex === index ? { ...assignment, ...next } : assignment);
  });

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving"); setMessage("");
    const document: ProtocolMapDocument = { observe_mode: mode, protocols: rows.map(fromRow) };
    const alertDocument = alertSettings ? alertsDocument(alertSettings.document, assignments) : null;
    const saveAlerts = alertSettings && alertDocument && JSON.stringify(alertSettings.document.assignments ?? []) !== JSON.stringify(assignments)
      ? saveAlertsSettings(alertSettings.revision, alertDocument).then(setAlertSettings)
      : Promise.resolve();
    void saveAlerts.then(() => saveProtocolMapSettings(settings.revision, path, document)).then((next) => {
      setSettings(next); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setState("saved"); setMessage("Saved. Restart STM to apply the new Monitoring targets and alert assignments.");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to apply Monitoring targets"); });
  };

  return <PaneFrame className="maintenance-frame protocol-map-frame maintenance-floating-actions-frame" header={<PaneHeader title="Monitoring targets" icon="protocolMap" meta="STM classification, display names, and alert profile assignment" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form maintenance-form-with-floating-actions" onSubmit={submit}><div className="maintenance-form-content">
      <div className="maintenance-intro">Target name identifies this monitoring setting. Stream name is the label shown for a matched stream. Alert profiles can be assigned here; leaving it empty uses the protocol default. STM restart is required before changes take effect.</div>
      <section className="maintenance-section"><div className="maintenance-section-copy"><h2>Protocol map file</h2><p>Path relative to the STM unified config file.</p></div><div className="protocol-map-controls"><label>Path<input value={path} disabled={state === "saving"} onChange={(event) => setPath(event.target.value)} /></label><label>Observe mode<select value={mode} disabled={state === "saving"} onChange={(event) => setMode(event.target.value as ProtocolMapDocument["observe_mode"])}>{modes.map((item) => <option key={item} value={item}>{item}</option>)}</select></label></div></section>
