function ConditionRow({ rule, metrics, protocols, flowRoles, busy, lockedIdentity, onUpdate, onRemove }: { rule: AlertRule; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; lockedIdentity: boolean; onUpdate: (patch: Partial<AlertRule>) => void; onRemove: () => void }) {
