ility" && <select value={rule.operator ?? ">"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ operator: event.target.value as AlertRule["operator"] })}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</td><td>{type === "availability" ? <NumberInput value={rule.inactive_after_sec} disabled={busy} onChange={(inactive_after_sec) => onUpdate({ inactive_after_sec })} /> : <NumberInput value={type === "counter_delta" ? rule.delta_threshold : rule.error_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} />}</td><td>{type === "availability" ? "Packet received" : <NumberInput value={type === "counter_delta" ? rule.recover_after_sec : rule.recover_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { recover_after_sec: value } : { recover_threshold: value })} />}</td><td><select value={rule.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate({ severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td>{!lockedIdentity && <button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={onRemove} aria-label="Delete condition" title="Delete condition"><Icon name="delete" size={16} /></button>}</td></tr>;
