type MenuSeparator = { type: "separator"; key: string; placement: MenuPlacement };
type MenuEntry = MenuItem | MenuSeparator;
type StandaloneView = "streams" | "timeline" | "events" | "detail" | "inspector-cell" | null;

const MENU_PLACEMENTS: MenuPlacement[] = ["top", "center", "bottom"];
const MENU_ITEMS: MenuEntry[] = [
  { type: "separator", key: "information-section", placement: "top" },
  { type: "item", key: "dashboard", icon: "dashboard", label: "Dashboard", hint: "Overview panels", placement: "top" },
  { type: "item", key: "streams", icon: "streams", label: "Streams", hint: "Tree and filters", placement: "top" },
  { type: "item", key: "detail", icon: "detail", label: "Inspector", hint: "Metrics and flows", placement: "top" },
  { type: "item", key: "timeline", icon: "timeline", label: "Timeline", hint: "History bands", placement: "top" },
  { type: "item", key: "topology", icon: "topology", label: "Topology", hint: "Network map", placement: "top" },
  { type: "item", key: "events", icon: "events", label: "Events", hint: "Alerts and logs", placement: "top" },
  { type: "separator", key: "configuration", placement: "top" },
  { type: "item", key: "alerts", icon: "alertRules", label: "Alert policies", hint: "Rules, profiles, and target assignments", placement: "top" },
  { type: "item", key: "protocol-map", icon: "protocolMap", label: "Monitoring targets", hint: "Classification and alert target rules", placement: "top" },
  { type: "separator", key: "information-section", placement: "top" },
  { type: "item", key: "preferences", icon: "preferences", label: "Preferences", hint: "Application preferences", placement: "top" },
  { type: "item", key: "maintenance", icon: "maintenance", label: "Maintenance", hint: "STM runtime settings", placement: "top" },
  { type: "separator", key: "information-section", placement: "top" },
  { type: "separator", key: "information-section", placement: "bottom" },
  { type: "item", key: "help", icon: "help", label: "Help", hint: "Guides and operating instructions", placement: "bottom" },
  { type: "item", key: "information", icon: "information", label: "Information", hint: "Version and license information", placement: "bottom" }
];
const RANGE_OPTIONS = ["24h", "12h", "6h", "3h", "1h", "30m", "10m", "5m", "1m"];
const DEFAULT_DASHBOARD_LAYOUT: DashboardLayout = {
function filterInspectorPickerStreams(streams: StreamListItem[], query: string) {
  if (!query.trim()) return streams;
  return streams.flatMap((stream) => {
    const streamMatches = matchesSearch([stream.kind, stream.proto, stream.displayName, stream.label, stream.streamKey, stream.endpointA, stream.endpointB, stream.interfaceName, stream.flowRoles.join(" ")], query);
    if (streamMatches) return [stream];
    const flows = stream.flows.filter((flow) => matchesSearch([flow.flowKey, flow.label, flow.role, flow.endpointSrc, flow.endpointDst, flow.interfaceName], query));
    return flows.length > 0 ? [{ ...stream, flows, flowCount: flows.length }] : [];
  });
}

function DashboardCellLoadingOverlay({ label }: { label: string }) {
  return <div className="dashboard-cell-loading-overlay" role="status" aria-live="polite">
    <div className="dashboard-cell-loading-dialog"><div className="timeline-loading-spinner" /><span>{label}</span></div>
  </div>;
}

function DashboardDetailEmptyState({ onChoose }: { onChoose: () => void }) {
  const { t } = useI18n();
  return <aside className="detail-pane empty-state dashboard-detail-empty-state">
    <div>
      <p>{t("dashboard.selectStreamToShow")}</p>
      <button type="button" className="button-with-icon" onClick={onChoose}><Icon name="targetFollow" size={15} />{t("dashboard.selectTargetButton")}</button>
    </div>
  </aside>;
}

function withAlertDocument(document: AlertsDocument) {
  const rules = [...(document.alerts ?? document.rules ?? [])] as AlertRule[] & { document?: AlertsDocument };
  rules.document = document;
  return rules;
}

function streamListItemToState(stream: StreamListItem): StreamState {
  return {
    ...stream,
    flows: stream.flows.map((flow) => ({ ...flow, metrics: {} }))
  };
}

function streamEndpointLabel(stream: StreamListItem) {
  const endpointA = stream.endpointA ?? "Unknown endpoint";
  return stream.displayName ?? (stream.endpointB ? `${endpointA} ⟶ ${stream.endpointB}` : endpointA);
}

function dashboardDetailMode(cell: DashboardCell): DetailMode {
  return dashboardCellTextParam(cell, "detailMode") === "detail" ? "detail" : "overview";
}

function dashboardEventsTab(cell: DashboardCell): EventLogTab {
  return dashboardCellTextParam(cell, "eventsTab") === "selected" ? "selected" : "all";
}

