function NumberInput({ value, disabled, onChange }: { value: number | undefined; disabled: boolean; onChange: (value: number | undefined) => void }) {
  return <input type="number" value={value ?? ""} disabled={disabled} onChange={(event) => onChange(event.target.value === "" ? undefined : Number(event.target.value))} />;
}

function newCondition(proto: string | undefined, flowRoles: Record<string, string[]>, existing: AlertRule[] = []): AlertRule {
  const roles = proto === "RTP" ? ["media"] : proto === "SRT" ? ["data"] : undefined;
  return { id: nextId("condition", existing.map((rule) => rule.id)), target: "flow", ...(proto ? { proto } : {}), ...(roles && flowRoles[proto ?? ""] ? { flow_roles: roles } : {}), metric: "bitrate.bps", type: "threshold", operator: "<", error_threshold: 0, recover_threshold: 0, severity: "warning" };
}

function nextId(prefix: string, ids: string[]) { let index = 1; while (ids.includes(prefix + "-" + index)) index += 1; return prefix + "-" + index; }
function targetModeLabel(mode: "inherit" | AlertBindingMode) { return mode === "inherit" ? "Inherited default" : mode === "shared" ? "Common policy" : mode === "individual" ? "Target-specific policy" : mode === "shared_with_adjustments" ? "Common policy + adjustments" : "Alert evaluation disabled"; }
function bindingLabel(binding: AlertBinding, targets: MonitoringTargetDefinition[]) { return binding.scope.kind === "protocol" ? (binding.scope.proto ?? "All protocols") + " default" : targets.find((target) => target.id === binding.scope.target_id)?.title || binding.scope.target_id; }
function adjustmentPatch(base: AlertRule, effective: AlertRule): Partial<AlertRule> { const fields: Array<keyof AlertRule> = ["enabled", "severity", "error_threshold", "recover_threshold", "delta_threshold", "trigger_after_sec", "recover_after_sec", "missing_after_sec", "inactive_after_sec"]; return Object.fromEntries(fields.flatMap((field) => base[field] !== effective[field] ? [[field, effective[field]]] : [])) as Partial<AlertRule>; }
function changedPolicyIds(previous: AlertsDocument, next: AlertsDocument) { const before = new Map(previous.policies.map((policy) => [policy.id, JSON.stringify(policy)])); return next.policies.filter((policy) => before.get(policy.id) !== JSON.stringify(policy)).map((policy) => policy.id); }
    .sort((left, right) => right.priority - left.priority || bindingKey(left.binding).localeCompare(bindingKey(right.binding)))[0]?.binding;
  if (!candidate) return { mode: "unconfigured", conditions: [] };
  if (candidate.mode === "disabled") return { mode: "disabled", binding: candidate, conditions: [] };
  if (candidate.mode === "individual") return {
    mode: candidate.mode,
    binding: candidate,
    conditions: (candidate.conditions ?? []).map((rule) => ({ rule, source: "individual" as const }))
  };
  const policy = document.policies.find((item) => item.id === candidate.policy_id);
  if (!policy) return { mode: candidate.mode, binding: candidate, conditions: [] };
  const conditions = policy.conditions.map((rule) => {
    const adjustment = candidate.mode === "shared_with_adjustments" ? candidate.adjustments?.[rule.id] : undefined;
    return { rule: { ...rule, ...(adjustment ?? {}) }, source: adjustment ? "individual_adjustment" as const : "shared" as const };
  });
  if (candidate.mode === "shared_with_adjustments") {
    conditions.push(...(candidate.additional_conditions ?? []).map((rule) => ({ rule, source: "additional" as const })));
  }
  return { mode: candidate.mode, binding: candidate, policy, conditions };
}

export function directTargetBinding(document: AlertsDocument, targetId: string) {
  return document.bindings.find((binding) => binding.scope.kind === "managed_target" && binding.scope.target_id === targetId);
}

