import type { AlertBinding, AlertBindingScope, AlertPolicy, AlertRule, AlertsDocument } from "./types/api";

export type AlertPolicyContext = {
  target: "flow" | "interface";
  proto?: string;
  monitoringTargetIds?: string[];
};

export type ResolvedAlertCondition = {
  rule: AlertRule;
  source: "shared" | "individual" | "individual_adjustment" | "additional";
};

export type ResolvedAlertPolicy = {
  mode: AlertBinding["mode"] | "unconfigured";
  binding?: AlertBinding;
  policy?: AlertPolicy;
  conditions: ResolvedAlertCondition[];
};

export function resolveAlertPolicy(document: AlertsDocument | undefined, context: AlertPolicyContext): ResolvedAlertPolicy {
  if (!document) return { mode: "unconfigured", conditions: [] };
  const candidate = document.bindings
    .map((binding) => ({ binding, priority: bindingPriority(binding, context) }))
    .filter((item) => item.priority >= 0)
    .sort((left, right) => right.priority - left.priority || bindingKey(left.binding).localeCompare(bindingKey(right.binding)))[0]?.binding;
  if (!candidate) return { mode: "unconfigured", conditions: [] };
  if (candidate.mode === "disabled") return { mode: "disabled", binding: candidate, conditions: [] };
  if (candidate.mode === "individual") return {
    mode: candidate.mode,
    binding: candidate,
    conditions: (candidate.conditions ?? []).map((rule) => ({ rule, source: "individual" as const }))
  };
  const policy = document.policies.find((item) => item.id === candidate.policy_id);
  if (!policy) return { mode: candidate.mode, binding: candidate, conditions: [] };
  const conditions: ResolvedAlertCondition[] = policy.conditions.map((rule) => {
    const adjustment = candidate.mode === "shared_with_adjustments" ? candidate.adjustments?.[rule.id] : undefined;
    return { rule: { ...rule, ...(adjustment ?? {}) }, source: adjustment ? "individual_adjustment" as const : "shared" as const };
  });
  if (candidate.mode === "shared_with_adjustments") {
    conditions.push(...(candidate.additional_conditions ?? []).map((rule) => ({ rule, source: "additional" as const })));
  }
  return { mode: candidate.mode, binding: candidate, policy, conditions };
}

export function directTargetBinding(document: AlertsDocument, targetId: string) {
  return document.bindings.find((binding) => binding.scope.kind === "managed_target" && binding.scope.target_id === targetId);
}

export function bindingKey(binding: AlertBinding) {
  const scope = binding.scope;
  return scope.kind === "protocol" ? "protocol:" + (scope.proto ?? "") + ":" + (scope.target ?? "any") : "managed_target:" + scope.target_id;
}

export function bindingPriority(binding: AlertBinding, context: AlertPolicyContext) {
  const scope = binding.scope;
  if (scope.kind === "protocol") {
    if (scope.proto && scope.proto !== context.proto) return -1;
    if (scope.target && scope.target !== "any" && scope.target !== context.target) return -1;
    return 0;
  }
  if (!context.monitoringTargetIds?.includes(scope.target_id)) return -1;
  return scope.target_type === "group" ? 1 : 2;
}

export function policyTitle(document: AlertsDocument, policyId: string | undefined) {
  if (!policyId) return undefined;
  const policy = document.policies.find((item) => item.id === policyId);
  return policy?.title || policy?.id || policyId;
}

export function emptyDocument(): AlertsDocument {
  return { policies: [], bindings: [] };
}

export function replaceBinding(document: AlertsDocument, next: AlertBinding) {
  const key = bindingKey(next);
  const bindings = document.bindings.some((binding) => bindingKey(binding) === key)
    ? document.bindings.map((binding) => bindingKey(binding) === key ? next : binding)
    : [...document.bindings, next];
  return { ...document, bindings };
}

export function removeBinding(document: AlertsDocument, scope: AlertBindingScope) {
  const key = scope.kind === "protocol" ? "protocol:" + (scope.proto ?? "") + ":" + (scope.target ?? "any") : "managed_target:" + scope.target_id;
  return { ...document, bindings: document.bindings.filter((binding) => bindingKey(binding) !== key) };
}
