    if (next === "shared") update({ scope, mode: "shared", ...(fallbackPolicy ? { policy_id: fallbackPolicy.id } : {}) });
    else if (next === "shared_with_adjustments") update({ scope, mode: "shared_with_adjustments", ...(fallbackPolicy ? { policy_id: fallbackPolicy.id } : {}) });
