  const updateIndividual = (conditions: AlertRule[]) => { if (direct?.mode === "individual") update({ ...direct, conditions }); };
  const basePolicy = direct?.policy_id ? document.policies.find((policy) => policy.id === direct.policy_id) : undefined;
  const adjustedConditions = basePolicy?.conditions.map((rule) => ({ ...rule, ...(direct?.adjustments?.[rule.id] ?? {}) })) ?? [];
  const updateAdjusted = (rules: AlertRule[]) => {
    if (direct?.mode !== "shared_with_adjustments" || !basePolicy) return;
    const base = new Map(basePolicy.conditions.map((rule) => [rule.id, rule]));
    const adjustments = Object.fromEntries(rules.flatMap((rule) => {
      const source = base.get(rule.id);
      if (!source) return [];
