import { useEffect, useMemo, useState, type FormEvent } from "react";
import { getAlertsSettings, saveAlertsSettings } from "../api/client";
import { directTargetBinding, emptyDocument, policyTitle, removeBinding, replaceBinding, resolveAlertPolicy } from "../alertsPolicy";
import type { AlertBinding, AlertBindingMode, AlertMetricDefinition, AlertPolicy, AlertRule, AlertsDocument, AlertsResponse, MonitoringTargetDefinition } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type PolicyTab = "targets" | "policies" | "defaults";
type PaneState = "loading" | "idle" | "saving" | "saved" | "error";
type AlertsPaneProps = { onSaved: (document: AlertsDocument) => void; onOpenMonitoringTargets: () => void };

const operators = [">", ">=", "<", "<=", "==", "!="] as const;
const severities = ["info", "warning", "error", "critical"];

export function AlertsPane({ onSaved, onOpenMonitoringTargets }: AlertsPaneProps) {
  const [settings, setSettings] = useState<AlertsResponse | null>(null);
  const [document, setDocument] = useState<AlertsDocument>(emptyDocument());
  const [savedDocument, setSavedDocument] = useState<AlertsDocument>(emptyDocument());
  const [policyTab, setPolicyTab] = useState<PolicyTab>("targets");
  const [selectedTargetId, setSelectedTargetId] = useState("");
  const [selectedPolicyId, setSelectedPolicyId] = useState("");
  const [selectedProtocol, setSelectedProtocol] = useState("RTP");
  const [state, setState] = useState<PaneState>("loading");
  const [message, setMessage] = useState("");

  const load = () => {
    setState("loading");
    void getAlertsSettings().then((next) => {
      setSettings(next); setDocument(next.document); setSavedDocument(next.document);
      setSelectedTargetId((current) => next.monitoringTargets.some((target) => target.id === current) ? current : next.monitoringTargets[0]?.id ?? "");
      setSelectedPolicyId((current) => next.document.policies.some((policy) => policy.id === current) ? current : next.document.policies[0]?.id ?? "");
      setSelectedProtocol((current) => next.protocols.includes(current) ? current : next.protocols[0] ?? "RTP");
      setState("idle"); setMessage("");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to load monitoring policies"); });
  };
  useEffect(load, []);

  const selectedTarget = settings?.monitoringTargets.find((target) => target.id === selectedTargetId) ?? null;
  const selectedPolicy = document.policies.find((policy) => policy.id === selectedPolicyId) ?? null;
  const policyChanges = useMemo(() => changedPolicyIds(savedDocument, document), [savedDocument, document]);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    const affected = policyChanges.flatMap((policyId) => document.bindings.filter((binding) => binding.policy_id === policyId).map((binding) => bindingLabel(binding, settings.monitoringTargets)));
    if (affected.length && !window.confirm(`共通ポリシーの変更は ${affected.length} 件の設定へ影響します。\n\n${affected.slice(0, 12).join("\n")}${affected.length > 12 ? "\n…" : ""}\n\n保存しますか？`)) return;
    setState("saving"); setMessage("");
    void saveAlertsSettings(settings.revision, document).then((next) => {
      setSettings(next); setDocument(next.document); setSavedDocument(next.document); onSaved(next.document);
      setState("saved"); setMessage("Saved. Restart STM to apply the new monitoring policies.");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to save monitoring policies"); });
  };

  const selectPolicy = (policyId: string) => { setSelectedPolicyId(policyId); setPolicyTab("policies"); };
  const addPolicy = () => {
    const id = nextId("policy", document.policies.map((policy) => policy.id));
    setDocument((current) => ({ ...current, policies: [...current.policies, { id, title: "New common policy", conditions: [] }] }));
    setSelectedPolicyId(id); setPolicyTab("policies");
  };
  const updatePolicy = (next: AlertPolicy) => setDocument((current) => ({ ...current, policies: current.policies.map((policy) => policy.id === selectedPolicyId ? next : policy) }));
  const renamePolicy = (id: string) => {
    if (!selectedPolicy || !id.trim() || id === selectedPolicy.id) return;
    if (document.policies.some((policy) => policy.id === id)) { setMessage("A common policy already uses that ID."); setState("error"); return; }
    setDocument((current) => ({
      ...current,
      policies: current.policies.map((policy) => policy.id === selectedPolicy.id ? { ...policy, id } : policy),
      bindings: current.bindings.map((binding) => binding.policy_id === selectedPolicy.id ? { ...binding, policy_id: id } : binding)
    }));
    setSelectedPolicyId(id);
  };
  const deletePolicy = () => {
    if (!selectedPolicy) return;
    const uses = document.bindings.filter((binding) => binding.policy_id === selectedPolicy.id);
    if (uses.length) { setState("error"); setMessage(`This common policy is used by ${uses.length} binding(s). Change those settings before deleting it.`); return; }
    if (!window.confirm(`Delete common policy '${selectedPolicy.title || selectedPolicy.id}'?`)) return;
    setDocument((current) => ({ ...current, policies: current.policies.filter((policy) => policy.id !== selectedPolicy.id) }));
    setSelectedPolicyId(document.policies.find((policy) => policy.id !== selectedPolicy.id)?.id ?? "");
  };

  return <PaneFrame className="maintenance-frame alerts-frame maintenance-floating-actions-frame" header={<PaneHeader title="Monitoring policies" icon="alertRules" meta="Target settings and common policy library" actions={<><button type="button" className="maintenance-secondary-button" onClick={onOpenMonitoringTargets} disabled={state === "loading" || state === "saving"}>Monitoring targets</button><button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button></>} />}>
    <form className="maintenance-form maintenance-form-with-floating-actions" onSubmit={submit}><div className="maintenance-form-content">
      <div className="maintenance-intro">Choose a policy for each Monitoring target. Target-specific settings never modify a common policy. Common policy changes show their affected settings before saving. STM restart is required after saving.</div>
      <section className="maintenance-section alerts-policy-navigation">
        <div className="alerts-tabs" role="tablist" aria-label="Monitoring policy section">
          {([ ["targets", "Monitoring targets", settings?.monitoringTargets.length ?? 0], ["policies", "Common policies", document.policies.length], ["defaults", "Protocol defaults", document.bindings.filter((binding) => binding.scope.kind === "protocol").length] ] as const).map(([key, label, count]) => <button key={key} type="button" role="tab" aria-selected={policyTab === key} className={"alerts-tab" + (policyTab === key ? " is-active" : "")} onClick={() => setPolicyTab(key)}>{label}<span>{count}</span></button>)}
        </div>
      </section>
      {policyTab === "targets" && <TargetsPane target={selectedTarget} targets={settings?.monitoringTargets ?? []} document={document} metrics={settings?.metrics ?? []} protocols={settings?.protocols ?? []} flowRoles={settings?.flowRoles ?? {}} busy={state === "saving"} onSelect={setSelectedTargetId} onDocument={setDocument} onOpenPolicy={selectPolicy} />}
      {policyTab === "policies" && <PoliciesPane policy={selectedPolicy} policies={document.policies} bindings={document.bindings} targets={settings?.monitoringTargets ?? []} metrics={settings?.metrics ?? []} protocols={settings?.protocols ?? []} flowRoles={settings?.flowRoles ?? {}} busy={state === "saving"} onSelect={setSelectedPolicyId} onAdd={addPolicy} onUpdate={updatePolicy} onRename={renamePolicy} onDelete={deletePolicy} />}
      {policyTab === "defaults" && <DefaultsPane document={document} protocols={settings?.protocols ?? []} busy={state === "saving"} selectedProtocol={selectedProtocol} onSelect={setSelectedProtocol} onDocument={setDocument} />}
    </div><footer className="maintenance-actions maintenance-actions-floating"><span className={"maintenance-message maintenance-message-" + state} role="status">{state === "loading" ? "Loading monitoring policies…" : message}</span><button type="submit" className="maintenance-save-button button-with-icon" disabled={!settings || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Saving…" : "Save"}</button></footer>
    </form>
  </PaneFrame>;
}

function TargetsPane({ target, targets, document, metrics, protocols, flowRoles, busy, onSelect, onDocument, onOpenPolicy }: { target: MonitoringTargetDefinition | null; targets: MonitoringTargetDefinition[]; document: AlertsDocument; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; onSelect: (id: string) => void; onDocument: (document: AlertsDocument) => void; onOpenPolicy: (id: string) => void }) {
  if (!target) return <section className="maintenance-section"><p>No Monitoring targets are configured.</p></section>;
  const direct = directTargetBinding(document, target.id);
  const effective = resolveAlertPolicy(document, { target: "flow", proto: target.proto, monitoringTargetIds: [target.id] });
  const mode = direct?.mode ?? "inherit";
  const update = (next: AlertBinding) => onDocument(replaceBinding(document, next));
  const setMode = (next: "inherit" | AlertBindingMode) => {
    if (next === "inherit") { onDocument(removeBinding(document, { kind: "managed_target", target_id: target.id })); return; }
    const scope = { kind: "managed_target" as const, target_id: target.id, target_type: target.target_type };
    const fallbackPolicy = document.policies.find((policy) => policy.conditions.some((condition) => condition.proto === target.proto)) ?? document.policies[0];
    if (next === "shared") update({ scope, mode: "shared", ...(fallbackPolicy ? { policy_id: fallbackPolicy.id } : {}) });
    else if (next === "shared_with_adjustments") update({ scope, mode: "shared_with_adjustments", ...(fallbackPolicy ? { policy_id: fallbackPolicy.id } : {}) });
    else if (next === "individual") update({ scope, mode: "individual", conditions: [newCondition(target.proto, flowRoles)] });
    else update({ scope, mode: "disabled" });
  };
  const selectSharedPolicy = (policyId: string) => { if (direct && (direct.mode === "shared" || direct.mode === "shared_with_adjustments")) update({ ...direct, policy_id: policyId }); };
  const updateIndividual = (conditions: AlertRule[]) => { if (direct?.mode === "individual") update({ ...direct, conditions }); };
  const basePolicy = direct?.policy_id ? document.policies.find((policy) => policy.id === direct.policy_id) : undefined;
  const adjustedConditions = basePolicy?.conditions.map((rule) => ({ ...rule, ...(direct?.adjustments?.[rule.id] ?? {}) })) ?? [];
  const updateAdjusted = (rules: AlertRule[]) => {
    if (direct?.mode !== "shared_with_adjustments" || !basePolicy) return;
    const base = new Map(basePolicy.conditions.map((rule) => [rule.id, rule]));
    const adjustments = Object.fromEntries(rules.flatMap((rule) => {
      const source = base.get(rule.id);
      if (!source) return [];
      const patch = adjustmentPatch(source, rule);
      return Object.keys(patch).length ? [[rule.id, patch]] : [];
    }));
    const { adjustments: _previousAdjustments, ...withoutAdjustments } = direct;
    update({ ...withoutAdjustments, ...(Object.keys(adjustments).length ? { adjustments } : {}) });
  };
  const updateAdditional = (additional_conditions: AlertRule[]) => { if (direct?.mode === "shared_with_adjustments") { const { additional_conditions: _previousAdditional, ...withoutAdditional } = direct; update({ ...withoutAdditional, ...(additional_conditions.length ? { additional_conditions } : {}) }); } };

  return <section className="maintenance-section alerts-master-section"><div className="alerts-master-workspace"><aside className="alerts-master-list"><h2>Monitoring targets</h2><div className="alerts-profile-list">{targets.map((item) => <button key={item.id} type="button" className={"alerts-profile-list-row" + (item.id === target.id ? " is-selected" : "")} onClick={() => onSelect(item.id)}><strong>{item.title || item.id}</strong><span>{item.proto} · {item.target_type}</span><small>{targetModeLabel(directTargetBinding(document, item.id)?.mode ?? "inherit")}</small></button>)}</div></aside><section className="alerts-profile-detail"><header><div><h3>{target.title || target.id}</h3><p>{target.id} · {target.proto} · {target.target_type}</p></div></header><label>Monitoring method<select value={mode} disabled={busy} onChange={(event) => setMode(event.target.value as "inherit" | AlertBindingMode)}><option value="inherit">Use protocol or group default</option><option value="shared">Common policy only</option><option value="individual">Target-specific policy only</option><option value="shared_with_adjustments">Common policy with target-specific adjustments</option><option value="disabled">Alert evaluation disabled</option></select></label>{mode === "inherit" && <p className="protocol-map-notice">{effective.mode === "unconfigured" ? "No applicable default policy is configured." : `Effective policy: ${policyTitle(document, effective.binding?.policy_id) ?? targetModeLabel(effective.mode)}`}</p>}{(mode === "shared" || mode === "shared_with_adjustments") && <><label>Common policy<select value={direct?.policy_id ?? ""} disabled={busy || document.policies.length === 0} onChange={(event) => selectSharedPolicy(event.target.value)}><option value="" disabled>Select a common policy</option>{document.policies.map((policy) => <option key={policy.id} value={policy.id}>{policy.title || policy.id}</option>)}</select></label>{basePolicy && <button type="button" className="maintenance-secondary-button" onClick={() => onOpenPolicy(basePolicy.id)}>Open common policy</button>}</>}{mode === "disabled" && <p className="protocol-map-notice">No alert conditions will be evaluated for this Monitoring target, even if a protocol default exists.</p>}{mode === "individual" && <ConditionTable title="Target-specific conditions" rules={direct?.conditions ?? []} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} onChange={updateIndividual} />}{mode === "shared_with_adjustments" && basePolicy && <><ConditionTable title="Target-specific adjustments" rules={adjustedConditions} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} onChange={updateAdjusted} lockedIdentity /><ConditionTable title="Additional target-specific conditions" rules={direct?.additional_conditions ?? []} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} onChange={updateAdditional} /></>}</section></div></section>;
}

function PoliciesPane({ policy, policies, bindings, targets, metrics, protocols, flowRoles, busy, onSelect, onAdd, onUpdate, onRename, onDelete }: { policy: AlertPolicy | null; policies: AlertPolicy[]; bindings: AlertBinding[]; targets: MonitoringTargetDefinition[]; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; onSelect: (id: string) => void; onAdd: () => void; onUpdate: (policy: AlertPolicy) => void; onRename: (id: string) => void; onDelete: () => void }) {
  const usage = policy ? bindings.filter((binding) => binding.policy_id === policy.id) : [];
  return <section className="maintenance-section alerts-master-section"><div className="alerts-master-workspace"><aside className="alerts-master-list"><h2>Common policies</h2><div className="alerts-profile-list">{policies.map((item) => <button key={item.id} type="button" className={"alerts-profile-list-row" + (item.id === policy?.id ? " is-selected" : "")} onClick={() => onSelect(item.id)}><strong>{item.title || item.id}</strong><span>{item.id}</span><small>{item.conditions.length} conditions · {bindings.filter((binding) => binding.policy_id === item.id).length} bindings</small></button>)}</div><div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={onAdd}><Icon name="add" size={16} />Add common policy</button></div></aside><section className="alerts-profile-detail">{!policy ? <p>Select or create a common policy.</p> : <><header><div><h3>Common policy</h3><p>Changes apply to every listed target after saving and restarting STM.</p></div><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onDelete}>Delete</button></header><div className="alerts-profile-fields"><label>Policy ID<input key={policy.id} defaultValue={policy.id} disabled={busy} onBlur={(event) => onRename(event.target.value.trim())} /></label><label>Title<input value={policy.title ?? ""} disabled={busy} onChange={(event) => onUpdate({ ...policy, title: event.target.value })} /></label></div><h4>Impact</h4><p>{usage.length ? `Used by ${usage.length} binding(s): ${usage.map((binding) => bindingLabel(binding, targets)).join(", ")}` : "Not assigned to any target."}</p><ConditionTable title="Common policy conditions" rules={policy.conditions} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} onChange={(conditions) => onUpdate({ ...policy, conditions })} /></>}</section></div></section>;
}

function DefaultsPane({ document, protocols, busy, selectedProtocol, onSelect, onDocument }: { document: AlertsDocument; protocols: string[]; busy: boolean; selectedProtocol: string; onSelect: (proto: string) => void; onDocument: (document: AlertsDocument) => void }) {
  const binding = document.bindings.find((item) => item.scope.kind === "protocol" && item.scope.proto === selectedProtocol && (item.scope.target ?? "flow") === "flow");
  const update = (mode: "shared" | "disabled", policyId?: string) => {
    const scope = { kind: "protocol" as const, proto: selectedProtocol, target: "flow" as const };
    onDocument(replaceBinding(document, mode === "disabled" ? { scope, mode } : { scope, mode, ...(policyId ? { policy_id: policyId } : {}) }));
  };
  return <section className="maintenance-section alerts-master-section"><h2>Protocol defaults</h2><p>These apply only when no higher-priority group or target-specific setting matches. Target-specific policies are managed in the Monitoring targets tab.</p><div className="alerts-profile-fields"><label>Protocol<select value={selectedProtocol} disabled={busy} onChange={(event) => onSelect(event.target.value)}>{protocols.map((proto) => <option key={proto} value={proto}>{proto}</option>)}</select></label><label>Default method<select value={binding?.mode ?? "inherit"} disabled={busy} onChange={(event) => { const value = event.target.value; if (value === "inherit") onDocument(removeBinding(document, { kind: "protocol", proto: selectedProtocol, target: "flow" })); else update(value as "shared" | "disabled", binding?.policy_id ?? document.policies[0]?.id); }}><option value="inherit">No protocol default</option><option value="shared">Common policy only</option><option value="disabled">Alert evaluation disabled</option></select></label>{binding?.mode === "shared" && <label>Common policy<select value={binding.policy_id ?? ""} disabled={busy} onChange={(event) => update("shared", event.target.value)}>{document.policies.map((policy) => <option key={policy.id} value={policy.id}>{policy.title || policy.id}</option>)}</select></label>}</div></section>;
}

function ConditionTable({ title, rules, metrics, protocols, flowRoles, busy, onChange, lockedIdentity = false }: { title: string; rules: AlertRule[]; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; onChange: (rules: AlertRule[]) => void; lockedIdentity?: boolean }) {
  const update = (index: number, patch: Partial<AlertRule>) => onChange(rules.map((rule, ruleIndex) => ruleIndex === index ? { ...rule, ...patch } : rule));
  const remove = (index: number) => onChange(rules.filter((_, ruleIndex) => ruleIndex !== index));
  const add = () => onChange([...rules, newCondition(undefined, flowRoles, rules)]);
  return <section className="alerts-rules-table-section"><h4>{title}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table"><thead><tr><th>Enabled</th><th>Condition ID</th><th>Target</th><th>Protocol</th><th>Roles</th><th>Indicator</th><th>Metric</th><th>Type</th><th>Trigger</th><th>Recovery</th><th>Timing</th><th>Severity</th><th /></tr></thead><tbody>{rules.map((rule, index) => <ConditionRow key={rule.id + ":" + index} rule={rule} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} lockedIdentity={lockedIdentity} onUpdate={(patch) => update(index, patch)} onRemove={() => remove(index)} />)}{rules.length === 0 && <tr><td colSpan={13} className="alerts-empty">No conditions.</td></tr>}</tbody></table></div>{!lockedIdentity && <div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={add}><Icon name="add" size={16} />Add condition</button></div>}</section>;
  return <section className="alerts-rules-table-section"><h4>{title}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table"><thead><tr><th>Enabled</th><th>Condition ID</th><th>Target</th><th>Protocol</th><th>Roles</th><th>Indicator</th><th>Metric</th><th>Type</th><th>Trigger</th><th>Recovery</th><th>Timing</th><th>Severity</th><th /></tr></thead><tbody>{rules.map((rule, index) => <ConditionRow key={rule.id + ":" + index} rule={rule} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} lockedIdentity={lockedIdentity} onUpdate={(patch) => update(index, patch)} onRemove={() => remove(index)} />)}{rules.length === 0 && <tr><td colSpan={13} className="alerts-empty">No conditions.</td></tr>}</tbody></table></div>{!lockedIdentity && <div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={add}><Icon name="add" size={16} />Add condition</button></div>}</section>;
}

function ConditionRow({ rule, metrics, protocols, flowRoles, busy, lockedIdentity, onUpdate, onRemove }: { rule: AlertRule; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; lockedIdentity: boolean; onUpdate: (patch: Partial<AlertRule>) => void; onRemove: () => void }) {
  const type = rule.type ?? "threshold";
  const target = rule.target ?? "flow";
  const roles = (rule.flow_roles ?? []).join(", ");
  const setType = (next: AlertRule["type"]) => {
    if (next === "availability") onUpdate({ type: next, operator: undefined, error_threshold: undefined, recover_threshold: undefined, delta_threshold: undefined, inactive_after_sec: rule.inactive_after_sec ?? 5 });
    else if (next === "counter_delta") onUpdate({ type: next, operator: rule.operator ?? ">", error_threshold: undefined, recover_threshold: undefined, delta_threshold: rule.delta_threshold ?? 0, recover_after_sec: rule.recover_after_sec ?? 3, inactive_after_sec: undefined });
    else onUpdate({ type: "threshold", operator: rule.operator ?? ">", error_threshold: rule.error_threshold ?? 0, recover_threshold: rule.recover_threshold ?? rule.error_threshold ?? 0, delta_threshold: undefined, inactive_after_sec: undefined });
  };
  return <tr><td><button type="button" role="switch" aria-checked={rule.enabled !== false} className={"maintenance-switch " + (rule.enabled !== false ? "is-on" : "is-off")} disabled={busy} onClick={() => onUpdate({ enabled: rule.enabled === false })}>{rule.enabled === false ? "Off" : "On"}</button></td><td><input className="alerts-id-input" value={rule.id} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ id: event.target.value })} /></td><td><select value={target} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ target: event.target.value as AlertRule["target"] })}><option value="flow">Flow</option><option value="stream">Stream</option><option value="interface">Interface</option><option value="any">Any</option></select></td><td><select value={rule.proto ?? ""} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ proto: event.target.value || undefined })}><option value="">Any</option>{protocols.map((proto) => <option key={proto} value={proto}>{proto}</option>)}</select></td><td><input value={roles} disabled={busy || lockedIdentity || target !== "flow"} placeholder="media, data" onChange={(event) => onUpdate({ flow_roles: event.target.value.split(",").map((value) => value.trim()).filter(Boolean) })} title={rule.proto ? "Available: " + (flowRoles[rule.proto] ?? []).join(", ") : undefined} /></td><td><input list={"alert-metrics-" + rule.id} value={rule.metric} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ metric: event.target.value })} /><datalist id={"alert-metrics-" + rule.id}>{metrics.map((metric) => <option key={metric.key} value={metric.key} label={metric.description ?? metric.key} />)}</datalist></td><td><select value={type} disabled={busy || lockedIdentity} onChange={(event) => setType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option><option value="availability">Availability</option></select>{type !== "availability" && <select value={rule.operator ?? ">"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ operator: event.target.value as AlertRule["operator"] })}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</td><td>{type === "availability" ? <NumberInput value={rule.inactive_after_sec} disabled={busy} onChange={(inactive_after_sec) => onUpdate({ inactive_after_sec })} /> : <NumberInput value={type === "counter_delta" ? rule.delta_threshold : rule.error_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} />}</td><td>{type === "availability" ? "Packet received" : <NumberInput value={type === "counter_delta" ? rule.recover_after_sec : rule.recover_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { recover_after_sec: value } : { recover_threshold: value })} />}</td><td><TimingFields rule={rule} disabled={busy || lockedIdentity} onUpdate={onUpdate} /></td><td><select value={rule.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate({ severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td>{!lockedIdentity && <button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={onRemove} aria-label="Delete condition" title="Delete condition"><Icon name="delete" size={16} /></button>}</td></tr>;
}

function TimingFields({ rule, disabled, onUpdate }: { rule: AlertRule; disabled: boolean; onUpdate: (patch: Partial<AlertRule>) => void }) {
  if ((rule.type ?? "threshold") === "availability") return <span title="Evaluated from the most recent packet capture time">Last packet</span>;
  return <span className="alerts-inline-field">{(rule.type ?? "threshold") === "threshold" && <><label>On<NumberInput value={rule.trigger_after_sec} disabled={disabled} onChange={(trigger_after_sec) => onUpdate({ trigger_after_sec })} /></label><label>Off<NumberInput value={rule.recover_after_sec} disabled={disabled} onChange={(recover_after_sec) => onUpdate({ recover_after_sec })} /></label></>}<label>Missing<NumberInput value={rule.missing_after_sec} disabled={disabled} onChange={(missing_after_sec) => onUpdate({ missing_after_sec })} /></label></span>;
}

function NumberInput({ value, disabled, onChange }: { value: number | undefined; disabled: boolean; onChange: (value: number | undefined) => void }) {
  return <input type="number" value={value ?? ""} disabled={disabled} onChange={(event) => onChange(event.target.value === "" ? undefined : Number(event.target.value))} />;
}

function newCondition(proto: string | undefined, flowRoles: Record<string, string[]>, existing: AlertRule[] = []): AlertRule {
  const roles = proto === "RTP" ? ["media"] : proto === "SRT" ? ["data"] : undefined;
  return { id: nextId("condition", existing.map((rule) => rule.id)), target: "flow", ...(proto ? { proto } : {}), ...(roles && flowRoles[proto ?? ""] ? { flow_roles: roles } : {}), metric: "bitrate.bps", type: "threshold", operator: "<", error_threshold: 0, recover_threshold: 0, severity: "warning" };
}

function nextId(prefix: string, ids: string[]) { let index = 1; while (ids.includes(prefix + "-" + index)) index += 1; return prefix + "-" + index; }
function targetModeLabel(mode: "inherit" | AlertBindingMode) { return mode === "inherit" ? "Inherited default" : mode === "shared" ? "Common policy" : mode === "individual" ? "Target-specific policy" : mode === "shared_with_adjustments" ? "Common policy + adjustments" : "Alert evaluation disabled"; }
function bindingLabel(binding: AlertBinding, targets: MonitoringTargetDefinition[]) { if (binding.scope.kind === "protocol") return (binding.scope.proto ?? "All protocols") + " default"; const targetId = binding.scope.target_id; return targets.find((target) => target.id === targetId)?.title || targetId; }
function adjustmentPatch(base: AlertRule, effective: AlertRule): Partial<AlertRule> { const fields: Array<keyof AlertRule> = ["enabled", "severity", "error_threshold", "recover_threshold", "delta_threshold", "trigger_after_sec", "recover_after_sec", "missing_after_sec", "inactive_after_sec"]; return Object.fromEntries(fields.flatMap((field) => base[field] !== effective[field] ? [[field, effective[field]]] : [])) as Partial<AlertRule>; }
function changedPolicyIds(previous: AlertsDocument, next: AlertsDocument) { const before = new Map(previous.policies.map((policy) => [policy.id, JSON.stringify(policy)])); return next.policies.filter((policy) => before.get(policy.id) !== JSON.stringify(policy)).map((policy) => policy.id); }

