    setDocument((current) => ({ ...current, policies: current.policies.map((policy) => policy.id === selectedPolicy.id ? { ...policy, id } : policy), bindings: current.bindings.map((binding) => binding.policy_id === selectedPolicy.id ? { ...binding, policy_id: id } : binding) }));
    setSelectedPolicyId(id);
