import type { AlertMetricDefinition, AlertRule } from "../types/api";
import { Icon } from "./ui/Icon";

const operators = [">", ">=", "<", "<=", "==", "!="] as const;
const severities = ["info", "warning", "error", "critical"];

export function AlertConditionTable({ title, rules, metrics, protocols, flowRoles, busy, onChange, lockedIdentity = false }: { title: string; rules: AlertRule[]; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; onChange: (rules: AlertRule[]) => void; lockedIdentity?: boolean }) {
  const update = (index: number, patch: Partial<AlertRule>) => onChange(rules.map((rule, ruleIndex) => ruleIndex === index ? { ...rule, ...patch } : rule));
  const remove = (index: number) => onChange(rules.filter((_, ruleIndex) => ruleIndex !== index));
  const add = () => onChange([...rules, newAlertCondition(undefined, flowRoles, rules)]);
  return <section className="alerts-rules-table-section"><h4>{title}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table"><thead><tr><th>Enabled</th><th>Condition ID</th><th>Target</th><th>Protocol</th><th>Roles</th><th>Indicator</th><th>Metric</th><th>Type</th><th>Trigger</th><th>Recovery</th><th>Timing</th><th>Severity</th><th /></tr></thead><tbody>{rules.map((rule, index) => <ConditionRow key={rule.id + ":" + index} rule={rule} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} lockedIdentity={lockedIdentity} onUpdate={(patch) => update(index, patch)} onRemove={() => remove(index)} />)}{rules.length === 0 && <tr><td colSpan={13} className="alerts-empty">No conditions.</td></tr>}</tbody></table></div>{!lockedIdentity && <div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={add}><Icon name="add" size={16} />Add condition</button></div>}</section>;
}

function ConditionRow({ rule, metrics, protocols, flowRoles, busy, lockedIdentity, onUpdate, onRemove }: { rule: AlertRule; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; lockedIdentity: boolean; onUpdate: (patch: Partial<AlertRule>) => void; onRemove: () => void }) {
  const type = rule.type ?? "threshold";
  const target = rule.target ?? "flow";
  const roles = (rule.flow_roles ?? []).join(", ");
  const setType = (next: AlertRule["type"]) => {
    if (next === "availability") onUpdate({ type: next, operator: undefined, error_threshold: undefined, recover_threshold: undefined, delta_threshold: undefined, inactive_after_sec: rule.inactive_after_sec ?? 5 });
    else if (next === "counter_delta") onUpdate({ type: next, operator: rule.operator ?? ">", error_threshold: undefined, recover_threshold: undefined, delta_threshold: rule.delta_threshold ?? 0, recover_after_sec: rule.recover_after_sec ?? 3, inactive_after_sec: undefined });
    else onUpdate({ type: "threshold", operator: rule.operator ?? ">", error_threshold: rule.error_threshold ?? 0, recover_threshold: rule.recover_threshold ?? rule.error_threshold ?? 0, delta_threshold: undefined, inactive_after_sec: undefined });
  };
  return <tr><td><button type="button" role="switch" aria-checked={rule.enabled !== false} className={"maintenance-switch " + (rule.enabled !== false ? "is-on" : "is-off")} disabled={busy} onClick={() => onUpdate({ enabled: rule.enabled === false })}>{rule.enabled === false ? "Off" : "On"}</button></td><td><input className="alerts-id-input" value={rule.id} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ id: event.target.value })} /></td><td><select value={target} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ target: event.target.value as AlertRule["target"] })}><option value="flow">Flow</option><option value="stream">Stream</option><option value="interface">Interface</option><option value="any">Any</option></select></td><td><select value={rule.proto ?? ""} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ proto: event.target.value || undefined })}><option value="">Any</option>{protocols.map((proto) => <option key={proto} value={proto}>{proto}</option>)}</select></td><td><input value={roles} disabled={busy || lockedIdentity || target !== "flow"} placeholder="media, data" onChange={(event) => onUpdate({ flow_roles: event.target.value.split(",").map((value) => value.trim()).filter(Boolean) })} title={rule.proto ? "Available: " + (flowRoles[rule.proto] ?? []).join(", ") : undefined} /></td><td><select value={rule.indicator_category ?? "other"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ indicator_category: event.target.value as AlertRule["indicator_category"] })}><option value="other">Other</option><option value="quality">Quality</option></select></td><td><input list={"alert-metrics-" + rule.id} value={rule.metric} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ metric: event.target.value })} /><datalist id={"alert-metrics-" + rule.id}>{metrics.map((metric) => <option key={metric.key} value={metric.key} label={metric.description ?? metric.key} />)}</datalist></td><td><select value={type} disabled={busy || lockedIdentity} onChange={(event) => setType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option><option value="availability">Availability</option></select>{type !== "availability" && <select value={rule.operator ?? ">"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ operator: event.target.value as AlertRule["operator"] })}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</td><td>{type === "availability" ? <NumberInput value={rule.inactive_after_sec} disabled={busy} onChange={(inactive_after_sec) => onUpdate({ inactive_after_sec })} /> : <NumberInput value={type === "counter_delta" ? rule.delta_threshold : rule.error_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} />}</td><td>{type === "availability" ? "Packet received" : <NumberInput value={type === "counter_delta" ? rule.recover_after_sec : rule.recover_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { recover_after_sec: value } : { recover_threshold: value })} />}</td><td><TimingFields rule={rule} disabled={busy || lockedIdentity} onUpdate={onUpdate} /></td><td><select value={rule.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate({ severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td>{!lockedIdentity && <button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={onRemove} aria-label="Delete condition" title="Delete condition"><Icon name="delete" size={16} /></button>}</td></tr>;
}

function TimingFields({ rule, disabled, onUpdate }: { rule: AlertRule; disabled: boolean; onUpdate: (patch: Partial<AlertRule>) => void }) {
  if ((rule.type ?? "threshold") === "availability") return <span title="Evaluated from the most recent packet capture time">Last packet</span>;
  return <span className="alerts-inline-field">{(rule.type ?? "threshold") === "threshold" && <><label>On<NumberInput value={rule.trigger_after_sec} disabled={disabled} onChange={(trigger_after_sec) => onUpdate({ trigger_after_sec })} /></label><label>Off<NumberInput value={rule.recover_after_sec} disabled={disabled} onChange={(recover_after_sec) => onUpdate({ recover_after_sec })} /></label></>}<label>Missing<NumberInput value={rule.missing_after_sec} disabled={disabled} onChange={(missing_after_sec) => onUpdate({ missing_after_sec })} /></label></span>;
}

function NumberInput({ value, disabled, onChange }: { value: number | undefined; disabled: boolean; onChange: (value: number | undefined) => void }) {
  return <input type="number" value={value ?? ""} disabled={disabled} onChange={(event) => onChange(event.target.value === "" ? undefined : Number(event.target.value))} />;
}

export function newAlertCondition(proto: string | undefined, flowRoles: Record<string, string[]>, existing: AlertRule[] = []): AlertRule {
  const roles = proto === "RTP" ? ["media"] : proto === "SRT" ? ["data"] : undefined;
  return { id: nextId("condition", existing.map((rule) => rule.id)), target: "flow", ...(proto ? { proto } : {}), ...(roles && flowRoles[proto ?? ""] ? { flow_roles: roles } : {}), metric: "bitrate.bps", type: "threshold", operator: "<", error_threshold: 0, recover_threshold: 0, severity: "warning" };
}

function nextId(prefix: string, ids: string[]) { let index = 1; while (ids.includes(prefix + "-" + index)) index += 1; return prefix + "-" + index; }
import { Fragment, useEffect, useState, type FormEvent } from "react";
import { getAlertsSettings, getProtocolMapSettings, saveAlertsSettings, saveProtocolMapSettings } from "../api/client";
import type { AlertsDocument, AlertsResponse, MonitoringTargetDefinition, ProtocolMapDocument, ProtocolMapResponse, ProtocolRule } from "../types/api";
import { TargetAlertPolicyPanel } from "./TargetAlertPolicyPanel";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type Row = Omit<ProtocolRule, "proto"> & { proto: ProtocolRule["proto"] | "RTP-FEC"; target: "endpoint" | "host"; value: string; port: string; vlanMode: "any" | "untagged" | "id"; vlanId: string };

const modes = ["all", "configured_only", "configured_plus_other"] as const;

export function ProtocolMapPane({ onAlertSaved }: { onAlertSaved: (document: AlertsDocument) => void }) {
  const [settings, setSettings] = useState<ProtocolMapResponse | null>(null);
  const [path, setPath] = useState("");
  const [mode, setMode] = useState<ProtocolMapDocument["observe_mode"]>("all");
  const [rows, setRows] = useState<Row[]>([]);
  const [alertSettings, setAlertSettings] = useState<AlertsResponse | null>(null);
  const [alertDocument, setAlertDocument] = useState<AlertsDocument | null>(null);
  const [alertState, setAlertState] = useState<"idle" | "saving" | "saved" | "error">("idle");
  const [alertMessage, setAlertMessage] = useState("");
  const [expandedAlertTargetId, setExpandedAlertTargetId] = useState("");
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");
  const locked = mode === "all";

  const load = () => {
    setState("loading");
    void Promise.all([getProtocolMapSettings(), getAlertsSettings()]).then(([next, nextAlerts]) => {
      setSettings(next); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow));
      setAlertSettings(nextAlerts); setAlertDocument(nextAlerts.document); setAlertState("idle"); setAlertMessage("");
      setState("idle"); setMessage("");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to load Monitoring targets"); });
  };
  useEffect(load, []);

  const updateRow = (index: number, patch: Partial<Row>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
  const addRow = () => setRows((current) => [...current, { enabled: true, observe: true, id: newTargetId(), target_type: "single", target_name: "", proto: "RTP", target: "endpoint", value: "", port: "", vlanMode: "any", vlanId: "" }]);
  const saveAlertPolicies = () => {
    if (!alertSettings || !alertDocument) return;
    setAlertState("saving"); setAlertMessage("");
    void saveAlertsSettings(alertSettings.revision, alertDocument).then((next) => {
      setAlertSettings(next); setAlertDocument(next.document); onAlertSaved(next.document);
      setAlertState("saved"); setAlertMessage("Alert policy saved. Restart STM to apply the change.");
    }).catch((error: unknown) => { setAlertState("error"); setAlertMessage(error instanceof Error ? error.message : "Failed to save Alert policy"); });
  };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving"); setMessage("");
    const document: ProtocolMapDocument = { observe_mode: mode, protocols: rows.map(fromRow) };
    void saveProtocolMapSettings(settings.revision, path, document).then((next) => {
      setSettings(next); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setState("saved"); setMessage("Saved. Restart STM to apply the new Monitoring targets.");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to apply Monitoring targets"); });
  };

  return <PaneFrame className="maintenance-frame protocol-map-frame maintenance-floating-actions-frame" header={<PaneHeader title="Monitoring targets" icon="protocolMap" meta="STM classification and display names" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form maintenance-form-with-floating-actions" onSubmit={submit}><div className="maintenance-form-content">
