lue={type} disabled={busy || lockedIdentity} onChange={(event) => setType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option><option value="availability">Availability</option></select>{type !== "availability" && <select value={rule.operator ?? ">"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ operator: event.target.value as AlertRule["operator"] })}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</td><td>{type === "availability" ? <NumberInput value={rule.inactive_after_sec} disabled={busy} onChange={(inactive_after_sec) => onUpdate({ inactive_after_sec })} /> : <NumberInput value={type === "counter_delta" ? rule.delta_threshold : rule.error_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} />}</td><td>{type === "availability" ? "Packet received" : <NumberInput value={type === "counter_delta" ? rule.recover_after_sec : rule.recover_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { recover_after_sec: value } : { recover_threshold: value })} />}</td><td><TimingFields rule={rule} disabled={busy || lockedIdentity} onUpdate={onUpdate} /></td><td><select value={rule.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate({ severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td>{!lockedIdentity && <button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={onRemove} aria-label="Delete condition" title="Delete condition"><Icon name="delete" size={16} /></button>}</td></tr>;
}

function TimingFields({ rule, disabled, onUpdate }: { rule: AlertRule; disabled: boolean; onUpdate: (patch: Partial<AlertRule>) => void }) {
  if ((rule.type ?? "threshold") === "availability") return <span title="Evaluated from the most recent packet capture time">Last packet</span>;
  return <span className="alerts-inline-field">{(rule.type ?? "threshold") === "threshold" && <><label>On<NumberInput value={rule.trigger_after_sec} disabled={disabled} onChange={(trigger_after_sec) => onUpdate({ trigger_after_sec })} /></label><label>Off<NumberInput value={rule.recover_after_sec} disabled={disabled} onChange={(recover_after_sec) => onUpdate({ recover_after_sec })} /></label></>}<label>Missing<NumberInput value={rule.missing_after_sec} disabled={disabled} onChange={(missing_after_sec) => onUpdate({ missing_after_sec })} /></label></span>;
}

function NumberInput({ value, disabled, onChange }: { value: number | undefined; disabled: boolean; onChange: (value: number | undefined) => void }) {
  return <input type="number" value={value ?? ""} disabled={disabled} onChange={(event) => onChange(event.target.value === "" ? undefined : Number(event.target.value))} />;
}

export function newAlertCondition(proto: string | undefined, flowRoles: Record<string, string[]>, existing: AlertRule[] = []): AlertRule {
  const roles = proto === "RTP" ? ["media"] : proto === "SRT" ? ["data"] : undefined;
  return { id: nextId("condition", existing.map((rule) => rule.id)), target: "flow", ...(proto ? { proto } : {}), ...(roles && flowRoles[proto ?? ""] ? { flow_roles: roles } : {}), metric: "bitrate.bps", type: "threshold", operator: "<", error_threshold: 0, recover_threshold: 0, severity: "warning" };
}

function nextId(prefix: string, ids: string[]) { let index = 1; while (ids.includes(prefix + "-" + index)) index += 1; return prefix + "-" + index; }
