.protocol-map-table th { white-space: nowrap; }
.protocol-map-table input, .protocol-map-table select { width: 100%; min-width: 0; }
.protocol-map-table .maintenance-switch { min-width: 60px; width: 60px; gap: 4px; padding: 0 4px; }
.protocol-map-table td:nth-child(9) { white-space: nowrap; }
.protocol-map-table td:nth-child(9) select { width: 76px; }
.protocol-map-table td:nth-child(9) input { width: 40px; margin-left: 4px; }
.protocol-map-notice { padding: var(--space-3); border: 1px solid var(--warning); border-radius: var(--radius-md); background: var(--warning-soft); color: var(--warning); }
.protocol-map-alert-policy-button { width: 100%; min-width: 0; }
.protocol-map-alert-row > td { padding: var(--space-3); background: var(--surface-muted); }
.protocol-map-alert-policy { display: grid; gap: var(--space-3); min-width: 0; padding: var(--space-3); border: 1px solid var(--accent-border); border-radius: var(--radius-md); background: var(--surface); }
.protocol-map-alert-policy > header, .protocol-map-alert-policy-actions { display: flex; align-items: start; justify-content: space-between; gap: var(--space-3); }
.protocol-map-alert-policy h3, .protocol-map-alert-policy p { margin: 0; }
.protocol-map-alert-policy header p { margin-top: var(--space-1); color: var(--muted); }
.protocol-map-alert-policy-controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--space-3); }
.protocol-map-alert-policy-controls > label { display: grid; min-width: 240px; gap: var(--space-1); color: var(--muted); font-size: var(--font-size-xs); font-weight: 700; }
.protocol-map-alert-policy-controls select { min-height: var(--control-height); }
.protocol-map-alert-policy-actions { align-items: center; }
.protocol-map-alert-policy-actions .maintenance-message { min-width: 0; }

.alerts-frame { max-width: none; }
.alerts-toolbar { display: grid; grid-template-columns: minmax(0, 1fr) minmax(240px, 320px); gap: var(--space-3); }
.alerts-policy-rules { display: grid; gap: var(--space-3); min-width: 0; padding-top: var(--space-3); }
.alerts-rules-table-section { min-width: 0; }
.alerts-rules-table-section .maintenance-table-wrap { overflow: visible; }
.alerts-policy-rules > .alerts-toolbar { padding: 0 var(--space-3); }
.alerts-toolbar > input { width: 100%; min-width: 0; min-height: var(--control-height); padding: 0 var(--space-2); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-muted); color: var(--text-strong); }
.alerts-tabs { display: flex; flex-wrap: wrap; align-items: stretch; gap: 0; border-bottom: 1px solid var(--line); }
.alerts-tab { position: relative; display: inline-flex; min-height: var(--control-height); align-items: center; gap: 7px; padding: 0 var(--space-3); border: 0; border-radius: 0; background: transparent; color: var(--muted); cursor: pointer; font-weight: 700; }
.alerts-tab:hover { color: var(--text-strong); }

