      setAlertSettings(nextAlerts); setAlertDocument(nextAlerts.document); setAlertState("idle"); setAlertMessage("");
      setState("idle"); setMessage("");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to load Monitoring targets"); });
  };
  useEffect(load, []);
  useEffect(() => () => { if (alertPanelFrame.current !== null) cancelAnimationFrame(alertPanelFrame.current); }, []);

  const updateRow = (index: number, patch: Partial<Row>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
  const addRow = () => setRows((current) => [...current, { enabled: true, observe: true, id: newTargetId(), target_type: "single", proto: "RTP", target: "endpoint", value: "", port: "", vlanMode: "any", vlanId: "" }]);
  const toggleAlertPanel = (rowId: string) => {
    if (alertPanelFrame.current !== null) cancelAnimationFrame(alertPanelFrame.current);
    if (expandedAlertTargetId === rowId) { setExpandedAlertTargetId(""); return; }
    setRenderedAlertTargetIds((current) => new Set(current).add(rowId));
    alertPanelFrame.current = requestAnimationFrame(() => { setExpandedAlertTargetId(rowId); alertPanelFrame.current = null; });
  };
  const saveAlertPolicies = () => {
    if (!alertSettings || !alertDocument) return;
    setAlertState("saving"); setAlertMessage("");
    void saveAlertsSettings(alertSettings.revision, alertDocument).then((next) => {
      setAlertSettings(next); setAlertDocument(next.document); onAlertSaved(next.document);
      setAlertState("saved"); setAlertMessage("Alert policy saved. Restart STM to apply the change.");
    }).catch((error: unknown) => { setAlertState("error"); setAlertMessage(error instanceof Error ? error.message : "Failed to save Alert policy"); });
  };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving"); setMessage("");
    const document: ProtocolMapDocument = { observe_mode: mode, protocols: rows.map(fromRow) };
    void saveProtocolMapSettings(settings.revision, path, document).then((next) => {
      setSettings(next); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setState("saved"); setMessage("Saved. Restart STM to apply the new Monitoring targets.");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to apply Monitoring targets"); });
  };

  return <PaneFrame className="maintenance-frame protocol-map-frame maintenance-floating-actions-frame" header={<PaneHeader title="Monitoring targets" icon="protocolMap" meta="STM classification and display names" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form maintenance-form-with-floating-actions" onSubmit={submit}><div className="maintenance-form-content">
      <div className="maintenance-intro">Target ID identifies a stable monitoring setting. Use Alert policy on each target row to assign a common policy, configure a target-specific policy, or apply target-specific adjustments. Restart STM before changes take effect.</div>
      <section className="maintenance-section"><div className="maintenance-section-copy"><h2>Protocol map file</h2><p>Path relative to the STM unified config file.</p></div><div className="protocol-map-controls"><label>Path<input value={path} disabled={state === "saving"} onChange={(event) => setPath(event.target.value)} /></label><label>Observe mode<select value={mode} disabled={state === "saving"} onChange={(event) => setMode(event.target.value as ProtocolMapDocument["observe_mode"])}>{modes.map((item) => <option key={item} value={item}>{item}</option>)}</select></label></div></section>
      {locked && <div className="protocol-map-notice">all observes every classified stream. Target definitions remain visible but cannot be edited in this mode. Alert policies can still be configured for saved targets.</div>}
      <section className="maintenance-section"><div className="maintenance-table-wrap"><table className="maintenance-table protocol-map-table"><colgroup><col className="protocol-map-col-index" /><col className="protocol-map-col-enabled" /><col className="protocol-map-col-type" /><col className="protocol-map-col-protocol" /><col className="protocol-map-col-target" /><col className="protocol-map-col-address" /><col className="protocol-map-col-port" /><col className="protocol-map-col-vlan" /><col className="protocol-map-col-stream-name" /><col className="protocol-map-col-profiles" /><col className="protocol-map-col-delete" /></colgroup><thead><tr><th>#</th><th>Enabled</th><th>Type</th><th>Protocol</th><th>Target</th><th>Address / domain</th><th>Port</th><th>VLAN</th><th>Stream name</th><th>Alert policy</th><th /></tr></thead><tbody>{rows.map((row, index) => { const rowId = row.id ?? "row-" + index; const alertTarget = alertSettings?.monitoringTargets.find((target) => target.id === row.id); return <Fragment key={rowId}><tr><td>{index + 1}</td><td><button type="button" role="switch" aria-checked={row.enabled !== false} className={`maintenance-switch ${row.enabled !== false ? "is-on" : "is-off"}`} disabled={locked || state === "saving"} onClick={() => updateRow(index, { enabled: row.enabled === false })}>{row.enabled === false ? "Off" : "On"}</button></td><td><select value={row.target_type ?? "single"} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { target_type: event.target.value as ProtocolRule["target_type"] })}><option value="single">Single</option><option value="group">Group</option></select></td><td><select value={row.proto} disabled={locked || state === "saving"} onChange={(event) => { const proto = event.target.value as Row["proto"]; updateRow(index, { proto, target: proto === "HLS" ? row.target : "endpoint", fec: proto === "RTP-FEC" }); }}><option value="RTP">RTP</option><option value="RTP-FEC">RTP-FEC</option><option value="SRT">SRT</option><option value="HLS">HLS</option></select></td><td><select value={row.target} disabled={locked || state === "saving" || row.proto !== "HLS"} onChange={(event) => updateRow(index, { target: event.target.value as Row["target"], value: "", port: "" })}><option value="endpoint">Endpoint</option><option value="host">Host</option></select></td><td><input value={row.value} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { value: event.target.value })} placeholder={row.target === "host" ? "media.example.com" : "239.1.1.1"} /></td><td>{row.target === "endpoint" && <input type="number" min="1" max="65535" value={row.port} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { port: event.target.value })} />}</td><td><select value={row.vlanMode} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanMode: event.target.value as Row["vlanMode"] })}><option value="any">Any</option><option value="untagged">Untagged</option><option value="id">ID</option></select>{row.vlanMode === "id" && <input type="number" min="0" max="4094" value={row.vlanId} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanId: event.target.value })} />}</td><td><input value={row.stream_name ?? ""} placeholder="Camera 1" disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { stream_name: event.target.value })} /></td><td><button type="button" className="maintenance-secondary-button protocol-map-alert-policy-button" aria-expanded={expandedAlertTargetId === rowId} onClick={() => toggleAlertPanel(rowId)} disabled={alertState === "saving"}>Alert policy</button></td><td><button type="button" className="maintenance-secondary-button icon-only" disabled={locked || state === "saving"} onClick={() => removeRow(index)} aria-label="Delete Monitoring target" title="Delete Monitoring target"><Icon name="delete" size={16} /></button></td></tr><tr className="protocol-map-alert-row"><td colSpan={11}><div className={"protocol-map-alert-disclosure" + (expandedAlertTargetId === rowId ? " is-open" : "")}><div className="protocol-map-alert-disclosure-inner">{renderedAlertTargetIds.has(rowId) && (alertTarget && alertDocument ? <><TargetAlertPolicyPanel target={alertTarget} document={alertDocument} metrics={alertSettings?.metrics ?? []} protocols={alertSettings?.protocols ?? []} flowRoles={alertSettings?.flowRoles ?? {}} busy={alertState === "saving"} onDocument={setAlertDocument} /><div className="protocol-map-alert-policy-actions"><span className={"maintenance-message maintenance-message-" + alertState} role="status">{alertMessage}</span><button type="button" className="maintenance-save-button button-with-icon" onClick={saveAlertPolicies} disabled={alertState === "saving"}><Icon name="save" size={16} />{alertState === "saving" ? "Saving…" : "Save Alert policy"}</button></div></> : <p className="protocol-map-notice">Save this new Monitoring target before assigning its Alert policy.</p>)}</div></div></td></tr></Fragment>; })}</tbody></table></div><div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={locked || state === "saving"} onClick={addRow}><Icon name="add" size={16} />Add target</button></div></section>
    </div><footer className="maintenance-actions maintenance-actions-floating"><span className={`maintenance-message maintenance-message-${state}`} role="status">{state === "loading" ? "Loading Monitoring targets…" : message}</span><button type="submit" className="maintenance-save-button button-with-icon" disabled={!settings || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Applying…" : "Apply"}</button></footer>
    </form>
  </PaneFrame>;
}

function toRow(rule: ProtocolRule): Row {
  const endpoint = first(rule.endpoints); const host = first(rule.hosts) || first(rule.domains); const target = host ? "host" : "endpoint"; const split = endpoint ? splitEndpoint(endpoint) : { value: host ?? "", port: "" }; const vlan = rule.vlan === null ? { vlanMode: "untagged" as const, vlanId: "" } : rule.vlan === undefined ? { vlanMode: "any" as const, vlanId: "" } : { vlanMode: "id" as const, vlanId: String(rule.vlan) };
  return { ...rule, id: rule.id || newTargetId(), proto: rule.proto === "RTP" && rule.fec === true ? "RTP-FEC" : rule.proto, target, value: split.value, port: split.port, ...vlan };
}
function fromRow(row: Row): ProtocolRule {
  const { target, value, port, vlanMode, vlanId, proto, ...rule } = row; const next: ProtocolRule = { ...rule, observe: rule.observe ?? true, enabled: rule.enabled !== false, proto: proto === "RTP-FEC" ? "RTP" : proto, ...(vlanMode === "untagged" ? { vlan: null } : vlanMode === "id" ? { vlan: Number(vlanId) } : {}) };
  if (target === "host") next.hosts = [value.trim()]; else next.endpoints = [`${formatHost(value.trim())}:${port}`];
  if (proto === "RTP-FEC") next.fec = true; else delete next.fec;
  if (!next.stream_name?.trim()) delete next.stream_name;
  return next;
}
function newTargetId() { return globalThis.crypto?.randomUUID?.() ?? "target_" + Math.random().toString(36).slice(2) + Date.now().toString(36); }
function first(value: string | string[] | undefined) { return typeof value === "string" ? value : value?.[0] ?? ""; }
function splitEndpoint(endpoint: string) { const ipv6 = endpoint.match(/^\[(.*)]:(\d+)$/); if (ipv6) return { value: ipv6[1], port: ipv6[2] }; const index = endpoint.lastIndexOf(":"); return index > 0 ? { value: endpoint.slice(0, index), port: endpoint.slice(index + 1) } : { value: endpoint, port: "" }; }
function formatHost(value: string) { return value.includes(":") && !value.startsWith("[") ? `[${value}]` : value; }
