import { useEffect, useRef, useState, type ReactNode } from "react";

export function useDisclosurePanel() {
  const [expandedId, setExpandedId] = useState("");
  const [renderedIds, setRenderedIds] = useState<Set<string>>(() => new Set());
  const frame = useRef<number | null>(null);

  useEffect(() => () => { if (frame.current !== null) cancelAnimationFrame(frame.current); }, []);

  const open = (id: string) => {
    if (frame.current !== null) cancelAnimationFrame(frame.current);
    setRenderedIds((current) => new Set(current).add(id));
    frame.current = requestAnimationFrame(() => { setExpandedId(id); frame.current = null; });
  };
  const toggle = (id: string) => {
    if (expandedId === id) { if (frame.current !== null) cancelAnimationFrame(frame.current); setExpandedId(""); return; }
    open(id);
  };
  const close = () => { if (frame.current !== null) cancelAnimationFrame(frame.current); setExpandedId(""); };

  return { isOpen: (id: string) => expandedId === id, isRendered: (id: string) => renderedIds.has(id), open, toggle, close };
}

export function DisclosurePanel({ open, rendered, children, className = "" }: { open: boolean; rendered: boolean; children: ReactNode; className?: string }) {
  return <div className={`maintenance-detail-disclosure${open ? " is-open" : ""}${className ? ` ${className}` : ""}`}><div className="maintenance-detail-disclosure-inner">{rendered && children}</div></div>;
}

