.protocol-map-table td:nth-child(8) { white-space: nowrap; }
.protocol-map-table td:nth-child(8) select { width: 76px; }
.protocol-map-table td:nth-child(8) input { width: 40px; margin-left: 4px; }
.protocol-map-notice { padding: var(--space-3); border: 1px solid var(--warning); border-radius: var(--radius-md); background: var(--warning-soft); color: var(--warning); }
.protocol-map-alert-policy-button { width: 100%; min-width: 0; }
.protocol-map-alert-row > td { padding: 0; background: var(--surface-muted); }
.protocol-map-alert-disclosure { display: grid; grid-template-rows: 0fr; opacity: 0; transform: translateY(-12px); transition: grid-template-rows 540ms cubic-bezier(.16, .84, .28, 1), opacity 210ms ease, transform 540ms cubic-bezier(.16, .84, .28, 1); }
.protocol-map-alert-disclosure.is-open { grid-template-rows: 1fr; opacity: 1; transform: translateY(0); }
.protocol-map-alert-disclosure-inner { min-height: 0; overflow: hidden; }
@media (prefers-reduced-motion: reduce) { .protocol-map-alert-disclosure { transition: none; } }
.protocol-map-alert-policy { display: grid; gap: var(--space-3); min-width: 0; padding: var(--space-3); border: 1px solid var(--accent-border); border-radius: var(--radius-md); background: var(--surface); }
.protocol-map-alert-policy > header, .protocol-map-alert-policy-actions { display: flex; align-items: start; justify-content: space-between; gap: var(--space-3); }
.protocol-map-alert-policy h3, .protocol-map-alert-policy p { margin: 0; }
.protocol-map-alert-policy header p { margin-top: var(--space-1); color: var(--muted); }
.protocol-map-alert-policy-controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--space-3); }
.protocol-map-alert-policy-controls > label { display: grid; min-width: 240px; gap: var(--space-1); color: var(--muted); font-size: var(--font-size-xs); font-weight: 700; }
.alerts-assignment-page { display: grid; gap: var(--space-3); }
@media (max-width: 540px) { .alerts-profile-migration { display: grid; } }

/* Alert policy master/detail tables use the same compact table treatment as Rules. */
.alerts-master-section { padding: var(--space-3); }
.alerts-master-workspace { display: grid; grid-template-columns: minmax(420px, 1fr) minmax(0, 1.25fr); gap: var(--space-3); min-width: 0; }
.alerts-master-list { min-width: 0; }
.alerts-master-table { min-width: 560px; table-layout: fixed; }
.alerts-master-table th:first-child, .alerts-master-table td:first-child { width: 44px; }
.alerts-master-table th, .alerts-master-table td { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.alerts-master-table tbody tr { cursor: pointer; }
.alerts-master-table tbody tr:hover { background: var(--accent-soft); }
.alerts-master-table tbody tr.is-selected { background: var(--accent-soft); color: var(--accent); }
