.alerts-master-table tbody tr.is-selected td { border-color: color-mix(in srgb, var(--accent-border) 48%, var(--line)); }
.alerts-master-list .protocol-map-row-actions { padding: var(--space-3) 0 0; }
.alerts-master-workspace .alerts-profile-detail { border-radius: var(--radius-sm); }
.alerts-assignment-detail .alerts-profile-fields { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.alerts-assignment-detail .alerts-target-picker { min-width: 0; }
.alerts-assignment-detail .alerts-target-picker select, .alerts-assignment-detail .alerts-target-picker input { min-width: 0; }
@media (max-width: 900px) { .alerts-master-workspace { grid-template-columns: 1fr; } .alerts-master-table { min-width: 520px; } }
.alerts-selection-search { display: grid; gap: var(--space-1); margin-top: var(--space-3); color: var(--muted); font-size: var(--font-size-xs); font-weight: 700; }
.alerts-selection-search input { width: 100%; min-height: var(--control-height); padding: 0 var(--space-2); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-muted); color: var(--text-strong); }
