.alerts-common-policy-item { overflow: clip; border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); }
.alerts-common-policy-summary { display: grid; grid-template-columns: minmax(220px, 1fr) minmax(100px, auto) minmax(90px, auto) 24px; align-items: center; gap: var(--space-3); width: 100%; min-height: 68px; padding: var(--space-3); border: 0; background: transparent; color: var(--text); text-align: left; cursor: pointer; }
.alerts-common-policy-summary:hover { background: var(--accent-soft); }
.alerts-common-policy-summary:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.alerts-common-policy-summary > span:first-child { display: grid; gap: 2px; min-width: 0; }
.alerts-common-policy-summary strong, .alerts-common-policy-summary small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.alerts-common-policy-summary small { color: var(--muted); font-size: var(--font-size-xs); }
.alerts-common-policy-chevron { color: var(--muted); font-size: 20px; line-height: 1; text-align: center; transition: transform 220ms ease; }
.alerts-common-policy-summary[aria-expanded="true"] .alerts-common-policy-chevron { transform: rotate(180deg); }
.alerts-common-policy-detail { display: grid; gap: var(--space-3); padding: var(--space-3); border-top: 1px solid var(--accent-border); background: var(--surface-muted); }
.alerts-common-policy-detail h4 { margin-top: var(--space-1); font-size: var(--font-size-sm); }
.alerts-common-policy-empty { margin: 0; padding: var(--space-4); border: 1px dashed var(--line-strong); border-radius: var(--radius-md); color: var(--muted); text-align: center; }
@media (max-width: 640px) { .alerts-common-policies-heading, .alerts-common-policy-detail > header { display: grid; } .alerts-common-policy-summary { grid-template-columns: minmax(0, 1fr) 24px; } .alerts-common-policy-summary > small { grid-column: 1; } .alerts-common-policy-chevron { grid-column: 2; grid-row: 1; } }

.alerts-master-section { padding: var(--space-3); }
.alerts-master-workspace { display: grid; grid-template-columns: minmax(420px, 1fr) minmax(0, 1.25fr); gap: var(--space-3); min-width: 0; }
.alerts-master-list { min-width: 0; }
.alerts-master-table { min-width: 560px; table-layout: fixed; }
.alerts-master-table th:first-child, .alerts-master-table td:first-child { width: 44px; }
.alerts-master-table th, .alerts-master-table td { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.alerts-master-table tbody tr { cursor: pointer; }
.alerts-master-table tbody tr:hover { background: var(--accent-soft); }
.alerts-master-table tbody tr.is-selected { background: var(--accent-soft); color: var(--accent); }
.alerts-master-table tbody tr.is-selected td:first-child { box-shadow: inset 3px 0 0 var(--accent); }
.alerts-master-table tbody tr.is-selected td { border-color: color-mix(in srgb, var(--accent-border) 48%, var(--line)); }
.alerts-master-list .protocol-map-row-actions { padding: var(--space-3) 0 0; }
.alerts-master-workspace .alerts-profile-detail { border-radius: var(--radius-sm); }
.alerts-assignment-detail .alerts-profile-fields { grid-template-columns: repeat(2, minmax(0, 1fr)); }

