item.stdout:
import { Fragment, useEffect, useMemo, useState, type FormEvent } from "react";
import { getAlertsSettings, saveAlertsSettings } from "../api/client";
import { emptyDocument, removeBinding, replaceBinding } from "../alertsPolicy";
import type { AlertBinding, AlertMetricDefinition, AlertPolicy, AlertsDocument, AlertsResponse, MonitoringTargetDefinition } from "../types/api";
import { AlertConditionTable } from "./AlertConditionTable";
import { Icon } from "./ui/Icon";
import { DisclosurePanel, useDisclosurePanel } from "./ui/DisclosurePanel";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type PolicyTab = "policies" | "defaults";
type PaneState = "loading" | "idle" | "saving" | "saved" | "error";
type AlertsPaneProps = { onSaved: (document: AlertsDocument) => void; onOpenMonitoringTargets: () => void };

const operators = [">", ">=", "<", "<=", "==", "!="] as const;
const severities = ["info", "warning", "error", "critical"];

export function AlertsPane({ onSaved }: { onSaved: (document: AlertsDocument) => void }) {
  const [settings, setSettings] = useState<AlertsResponse | null>(null);
  const [document, setDocument] = useState<AlertsDocument>(emptyDocument());
  const [savedDocument, setSavedDocument] = useState<AlertsDocument>(emptyDocument());
  const [policyTab, setPolicyTab] = useState<PolicyTab>("policies");
  const policyDisclosure = useDisclosurePanel();
  const [selectedProtocol, setSelectedProtocol] = useState("RTP");
  const [state, setState] = useState<PaneState>("loading");
  const [message, setMessage] = useState("");

  const load = () => {
    setState("loading");
    void getAlertsSettings().then((next) => {
      setSettings(next); setDocument(next.document); setSavedDocument(next.document);
      setSelectedProtocol((current) => next.protocols.includes(current) ? current : next.protocols[0] ?? "RTP");
      setState("idle"); setMessage("");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to load monitoring policies"); });
  };
  useEffect(load, []);

  const policyChanges = useMemo(() => changedPolicyIds(savedDocument, document), [savedDocument, document]);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    const affected = policyChanges.flatMap((policyId) => document.bindings.filter((binding) => binding.policy_id === policyId).map((binding) => bindingLabel(binding, settings.monitoringTargets)));
    if (affected.length && !window.confirm(`共通ポリシーの変更は ${affected.length} 件の設定へ影響します。\n\n${affected.slice(0, 12).join("\n")}${affected.length > 12 ? "\n…" : ""}\n\n保存しますか？`)) return;
    setState("saving"); setMessage("");
    void saveAlertsSettings(settings.revision, document).then((next) => {
      setSettings(next); setDocument(next.document); setSavedDocument(next.document); onSaved(next.document);
      setState("saved"); setMessage("Saved. Restart STM to apply the Alert policies.");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to save Alert policies"); });
  };

  const addPolicy = () => {
    const id = nextId("policy", document.policies.map((policy) => policy.id));
    setDocument((current) => ({ ...current, policies: [...current.policies, { id, title: "New common policy", conditions: [] }] }));
    policyDisclosure.open(id); setPolicyTab("policies");
  };
  const updatePolicy = (policyId: string, next: AlertPolicy) => setDocument((current) => ({ ...current, policies: current.policies.map((policy) => policy.id === policyId ? next : policy) }));
  const renamePolicy = (policyId: string, id: string) => {
    if (!id.trim() || id === policyId) return;
    if (document.policies.some((policy) => policy.id === id)) { setMessage("A common policy already uses that ID."); setState("error"); return; }
    setDocument((current) => ({
      ...current,
      policies: current.policies.map((policy) => policy.id === policyId ? { ...policy, id } : policy),
      bindings: current.bindings.map((binding) => binding.policy_id === policyId ? { ...binding, policy_id: id } : binding)
    }));
    policyDisclosure.open(id);
  };
  const deletePolicy = (policy: AlertPolicy) => {
    const uses = document.bindings.filter((binding) => binding.policy_id === policy.id);
    if (uses.length) { setState("error"); setMessage(`This common policy is used by ${uses.length} binding(s). Change those settings before deleting it.`); return; }
    if (!window.confirm(`Delete common policy '${policy.title || policy.id}'?`)) return;
    setDocument((current) => ({ ...current, policies: current.policies.filter((item) => item.id !== policy.id) }));
    policyDisclosure.close();
  };

  return <PaneFrame className="maintenance-frame alerts-frame maintenance-floating-actions-frame" header={<PaneHeader title="Alert policies" icon="alertRules" meta="Common policy library and protocol defaults" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form maintenance-form-with-floating-actions" onSubmit={submit}><div className="maintenance-form-content">
      <div className="maintenance-intro">Assign a policy to each Monitoring target from the Monitoring targets screen. Common policy changes show their affected settings before saving. STM restart is required after saving.</div>
      <section className="maintenance-section alerts-policy-navigation">
        <div className="alerts-tabs" role="tablist" aria-label="Monitoring policy section">
          {([ ["policies", "Common policies", document.policies.length], ["defaults", "Protocol defaults", document.bindings.filter((binding) => binding.scope.kind === "protocol").length] ] as const).map(([key, label, count]) => <button key={key} type="button" role="tab" aria-selected={policyTab === key} className={"alerts-tab" + (policyTab === key ? " is-active" : "")} onClick={() => setPolicyTab(key)}>{label}<span>{count}</span></button>)}
        </div>
        {policyTab === "policies" && <PoliciesPane policies={document.policies} bindings={document.bindings} targets={settings?.monitoringTargets ?? []} metrics={settings?.metrics ?? []} protocols={settings?.protocols ?? []} flowRoles={settings?.flowRoles ?? {}} busy={state === "saving"} disclosure={policyDisclosure} onAdd={addPolicy} onUpdate={updatePolicy} onRename={renamePolicy} onDelete={deletePolicy} />}
        {policyTab === "defaults" && <DefaultsPane document={document} protocols={settings?.protocols ?? []} busy={state === "saving"} selectedProtocol={selectedProtocol} onSelect={setSelectedProtocol} onDocument={setDocument} />}
      </section>
    </div><footer className="maintenance-actions maintenance-actions-floating"><span className={"maintenance-message maintenance-message-" + state} role="status">{state === "loading" ? "Loading Alert policies…" : message}</span><button type="submit" className="maintenance-save-button button-with-icon" disabled={!settings || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Saving…" : "Save"}</button></footer>
    </form>
  </PaneFrame>;
}

function PoliciesPane({ policies, bindings, targets, metrics, protocols, flowRoles, busy, disclosure, onAdd, onUpdate, onRename, onDelete }: { policies: AlertPolicy[]; bindings: AlertBinding[]; targets: MonitoringTargetDefinition[]; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; disclosure: ReturnType<typeof useDisclosurePanel>; onAdd: () => void; onUpdate: (policyId: string, policy: AlertPolicy) => void; onRename: (policyId: string, id: string) => void; onDelete: (policy: AlertPolicy) => void }) {
