int main(int argc, char** argv) {
    std::signal(SIGINT, on_signal);
    std::signal(SIGTERM, on_signal);

    const auto parsed = parse_args(argc, argv);
    if (!parsed) {
        usage(argv[0]);
        return 1;
    }

    const auto& opt = *parsed;

#ifdef ENABLE_SRT
    srt_startup();
#endif

    switch (opt.proto) {
    case proto_type::rtp:
        run_rtp(opt);
        break;
    case proto_type::srt:
        run_srt(opt);
        break;
    }

#ifdef ENABLE_SRT
    srt_cleanup();
#endif

    return 0;
}
