        const auto base = next_base_time_.value_or(clock_type::now());
        const double bitrate = bitrate_modulation_.enabled()
            ? bitrate_modulation_.value_at(base)
            : static_cast<double>(bitrate_bps_);
        next_base_time_ = base + std::chrono::duration_cast<clock_type::duration>(
            std::chrono::duration<double>(static_cast<double>(payload_size_) * 8.0 / bitrate));

        const double target_ms = jitter_modulation_.enabled()
            ? jitter_modulation_.value_at(base)
            : jitter_target_ms_;
        auto due = base;
        if (target_ms > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(next_target_offset_ms(target_ms)));
        } else if (jitter_ms_ > 0.0) {
            due += std::chrono::duration_cast<clock_type::duration>(
                std::chrono::duration<double, std::milli>(jitter_distribution_(rng_)));
        }

        if (!target_reorder_ && last_due_ && due < *last_due_) {
            due = *last_due_;
        }
        scheduled_.emplace(due, std::move(value));
        last_due_ = due;
    }

    double next_target_offset_ms(double target_ms) {
        const double offset_ms = jitter_target_offset_ms(
            jitter_target_protocol::srt, target_ms, target_high_phase_);
        target_high_phase_ = !target_high_phase_;
        return offset_ms;
    }

    void flush_ready() {
        const auto now = clock_type::now();
        while (!scheduled_.empty() && scheduled_.begin()->first <= now) {
            send_downstream(scheduled_.begin()->second);
            scheduled_.erase(scheduled_.begin());
