const names=["fec-low","fixed-high","bitrate-sine","jitter-fixed","jitter-triangle","errors","outage-mute","outage-reconnect"];
const srtNames=["fixed-low","fixed-high","bitrate-step","jitter-fixed","jitter-random","errors","outage-mute","outage-reconnect"];
const labelsR=["SG RTP 0 FEC 500k","SG RTP 1 fixed 4M","SG RTP 2 bitrate sine","SG RTP 3 jitter 3ms","SG RTP 4 jitter 1-12ms","SG RTP 5 counted errors","SG RTP 6 FEC mute 60s/10s","SG RTP 7 reconnect 90s/15s"];
const labelsS=["SG SRT 0 fixed 500k","SG SRT 1 fixed 4M","SG SRT 2 bitrate step","SG SRT 3 jitter 8ms","SG SRT 4 jitter 2-30ms","SG SRT 5 counted errors","SG SRT 6 mute 60s/10s","SG SRT 7 reconnect 90s/15s"];
const protocolMap={observe_mode:"configured_only",protocols:[
...names.map((name,i)=>({id:`sg.rtp.${name}`,target_type:"single",proto:"RTP",enabled:true,observe:true,stream_name:labelsR[i],endpoints:[`127.0.0.1:${5000+i*100}`],interfaces:["lo"],...([0,6].includes(i)?{fec:true}:{})})),
...srtNames.map((name,i)=>({id:`sg.srt.${name}`,target_type:"single",proto:"SRT",enabled:true,observe:true,stream_name:labelsS[i],endpoints:[`127.0.0.1:${4201+i}`],interfaces:["lo"]}))
]};
const roles=p=>p==="RTP"?["media"]:["data","mixed"];
function rule(p,id,metric,op,threshold,recovery,extra={}){
 return {id,target:"flow",proto:p,flow_roles:roles(p),metric,type:"threshold",operator:op,error_threshold:threshold,recover_threshold:recovery,trigger_after_sec:1,recover_after_sec:1,severity:"warning",indicator_category:"other",...extra};
}
function base(p,withJitter){
 const allRoles=p==="RTP"?["media","fec_row","fec_col"]:["data","mixed"];
 const conditions=[
 rule(p,"bitrate-low","bitrate.bps","<",1600000,1800000),
 rule(p,"bitrate-high","bitrate.bps",">",2600000,2400000),
 rule(p,"packet-rate-low","packet_rate.pps","<",142,161),
 rule(p,"packet-rate-high","packet_rate.pps",">",257,228),
 {id:"availability",target:"flow",proto:p,flow_roles:allRoles,metric:"bitrate.bps",type:"availability",inactive_after_sec:5,severity:"error",indicator_category:"other"},
 ...["gap","dup","reorder"].map((kind)=>rule(p,kind==="gap"?"loss":kind==="dup"?"duplicate":"reorder",`seq_stats.${kind}.window`,">",0,0,{trigger_after_sec:0,severity:"error",indicator_category:"quality"})),
 rule(p,"jitter-high","jitter.seconds",">",withJitter?(p==="RTP"?.0045:.020):.030,withJitter?(p==="RTP"?.004:.018):.020,{trigger_after_sec:2,indicator_category:"quality"})
 ];
 if(withJitter)conditions.push(rule(p,"jitter-low","jitter.seconds","<",p==="RTP"?.0015:.003,p==="RTP"?.002:.004,{trigger_after_sec:2,indicator_category:"quality"}));
 if(p==="SRT")conditions.push(rule(p,"data-silence","packet_breakdown.data.window","<",1,1,{trigger_after_sec:2,severity:"error"}));
 return {id:`sg.${p.toLowerCase()}.${withJitter?"jitter":"standard"}`,title:`${p} ${p==="RTP"?"media":"data"}: bitrate / packet rate / availability / quality${withJitter?" / jitter range":""}`,conditions};
}
const policies=[base("RTP",false),base("RTP",true),base("SRT",false),base("SRT",true)];
function fixed(r){
 const pps=r/10528;
 return {"bitrate-low":{error_threshold:r*.8,recover_threshold:r*.9},"bitrate-high":{error_threshold:r*1.3,recover_threshold:r*1.2},
 "packet-rate-low":{error_threshold:Math.floor(pps*.75),recover_threshold:Math.floor(pps*.85)},
 "packet-rate-high":{error_threshold:Math.ceil(pps*1.35),recover_threshold:Math.ceil(pps*1.2)}};
}
const bindings=[];
for(const p of ["RTP","SRT"]){
 for(let i=0;i<8;i++){
 const isJitter=i===3||i===4;
 const rates=[500000,4000000,1000000,2000000,2000000,2000000,1000000,1000000];
 let adjustments=(i===3||i===4||i===5)?{}:fixed(rates[i]);
 if(i===2){
 const isRtp=p==="RTP";
 const min=isRtp?500000:750000,max=isRtp?2000000:3000000;
 adjustments={
 "bitrate-low":{error_threshold:isRtp?800000:1000000,recover_threshold:isRtp?1000000:1200000},
 "bitrate-high":{error_threshold:isRtp?1600000:2500000,recover_threshold:isRtp?1400000:2200000},
 "packet-rate-low":{error_threshold:Math.floor(min/10528*.7),recover_threshold:Math.floor(min/10528*.8)},
 "packet-rate-high":{error_threshold:Math.ceil(max/10528*1.4),recover_threshold:Math.ceil(max/10528*1.25)}
 };
 }
 if(i===4){
 adjustments["jitter-low"]={error_threshold:p==="RTP"?.003:.005,recover_threshold:p==="RTP"?.004:.007};
 adjustments["jitter-high"]={error_threshold:p==="RTP"?.008:.020,recover_threshold:p==="RTP"?.007:.018};
 }
 const additional=[];
 if(p==="RTP" && [0,6].includes(i)){
 const fecRate=rates[i]/4;
 additional.push(rule(p,"fec-bitrate-low","bitrate.bps","<",fecRate*.6,fecRate*.75,{flow_roles:["fec_row","fec_col"],trigger_after_sec:2}),
 rule(p,"fec-bitrate-high","bitrate.bps",">",fecRate*1.6,fecRate*1.4,{flow_roles:["fec_row","fec_col"],trigger_after_sec:2}));
 }
 const id=`sg.${p.toLowerCase()}.${(p==="RTP"?names:srtNames)[i]}`;
 const customized=Object.keys(adjustments).length>0||additional.length>0;
 bindings.push({scope:{kind:"managed_target",target_id:id,target_type:"single"},mode:customized?"shared_with_adjustments":"shared",policy_id:`sg.${p.toLowerCase()}.${isJitter?"jitter":"standard"}`,
 ...(Object.keys(adjustments).length?{adjustments}:{}),...(additional.length?{additional_conditions:additional}:{})});
 }
}
const alerts={_note:"test-sg.yml: RTP_0..7 / SRT_TX_0..7 on lo. Units: bps, packets/s, jitter seconds. Thresholds are demo tolerances, not assertions. Counter window > 0 triggers immediately; SRT data-silence monitors application data despite control keepalive. See conf/streamgen-monitoring.md.",policies,bindings};
const stm=JSON.parse(originals["conf/stm_config.json"]);
stm.capture.interfaces=["lo"];stm.capture.auto_interfaces=false;stm.capture.include_loopback=true;
stm.capture.bpf_filter="udp and (portrange 4201-4208 or port 5000 or port 5002 or port 5004 or port 5100 or port 5200 or port 5300 or port 5400 or port 5500 or port 5600 or port 5602 or port 5604 or port 5700)";
stm.configs.protocol_map="protocol_map.json";stm.configs.alerts="alerts_config.json";
const configs={"conf/protocol_map.json":protocolMap,"conf/alerts_config.json":alerts,"conf/stm_config.json":stm};
const patch="*** Begin Patch\n"+Object.entries(configs).map(([file,obj])=>"*** Update File: "+file+"\n@@\n"+originals[file].trimEnd().split("\n").map(x=>"-"+x).join("\n")+"\n"+JSON.stringify(obj,null,2).split("\n").map(x=>"+"+x).join("\n")+"\n").join("")+"*** End Patch\n";
store("sg_monitor_configs",configs);
const r=await tools.exec_command({cmd:"apply_patch <<'STM_MONITOR_PATCH'\n"+patch+"STM_MONITOR_PATCH",sandbox_permissions:"require_escalated",justification:"退避済みの設定を、16信号の宛先識別・対象別閾値・SRTデータ停止検出・loopbackキャプチャに対応する設定へ置き換えます。",max_output_tokens:2000});text(r.output);
