const fs = require('node:fs');
const path = require('node:path');
const Module = require('node:module');
const assert = require('node:assert/strict');
const config = path.resolve('conf/stm_config.json');
const { AlertsSettings } = require('./fe/server/dist/alertsSettings.js');
const { ProtocolMapSettings } = require('./fe/server/dist/protocolMapSettings.js');
(async () => {
  const alerts = await new AlertsSettings(config).get();
  const map = await new ProtocolMapSettings(config).get();
  // Use the deployed validator with schema metadata, without update()/file writes.
  const validatorFile = path.resolve('fe/server/dist/alertsSettings.js');
  const validator = new Module(validatorFile, module);
  validator.filename = validatorFile;
  validator.paths = Module._nodeModulePaths(path.dirname(validatorFile));
  validator._compile(fs.readFileSync(validatorFile, 'utf8') + '\nexports.validateForCheck = validateDocument;', validatorFile);
  validator.exports.validateForCheck(alerts.document, alerts.metrics, alerts.protocols);
  assert.equal(map.document.protocols.length, 16);
  assert.equal(alerts.monitoringTargets.length, 16);
  assert.equal(alerts.document.bindings.length, 16);
  const ids = new Set(map.document.protocols.map(x => x.id));
  const metrics = new Set(alerts.metrics.map(x => x.key));
  const allowedRoles = { RTP: new Set(['media','fec_row','fec_col']), SRT: new Set(['data','mixed','control']) };
  const policyMap = new Map(alerts.document.policies.map(p => [p.id, p]));
  const effective = [];
  for (const binding of alerts.document.bindings) {
    assert(ids.has(binding.scope.target_id), binding.scope.target_id);
    const target = map.document.protocols.find(x => x.id === binding.scope.target_id);
    const rules = policyMap.get(binding.policy_id).conditions.map(r => ({...r, ...(binding.adjustments?.[r.id] || {})})).concat(binding.additional_conditions || []);
    for (const r of rules) {
      assert(metrics.has(r.metric), r.metric);
      assert.equal(r.proto, target.proto);
      for (const role of r.flow_roles || []) assert(allowedRoles[r.proto].has(role));
      for (const k of ['error_threshold','recover_threshold']) if (k in r) assert(Number.isFinite(r[k]));
      if (r.id === 'loss' || r.id === 'duplicate' || r.id === 'reorder') {
        assert.equal(r.trigger_after_sec, 0);
        assert.equal(r.error_threshold, 0);
      }
    }
    assert(rules.some(r => r.id === 'availability'));
    if (target.proto === 'SRT') assert(rules.some(r => r.id === 'data-silence' && r.metric === 'packet_breakdown.data.window'));
    effective.push({id: target.id, conditions:rules.length, bitrate:[rules.find(r=>r.id==='bitrate-low').error_threshold,rules.find(r=>r.id==='bitrate-high').error_threshold]});
  }
  const stm = JSON.parse(fs.readFileSync(config,'utf8'));
  assert.deepEqual(stm.capture.interfaces, ['lo']);
  assert.equal(stm.capture.include_loopback, true);
  for (const f of ['stm_config.json','protocol_map.json','alerts_config.json','README.md']) assert(fs.statSync('conf/_bk/test-sg-20261016-WfJKuC/'+f).size > 0);
  console.log(JSON.stringify({targets:ids.size,policies:policyMap.size,bindings:effective.length,conditions:effective.reduce((n,x)=>n+x.conditions,0),effective},null,2));
})().catch(error => { console.error(error); process.exitCode=1; });
