    tsv::vlan_info vlan = {}
) {
    return stream_id::from_endpoints(interface_id, src_ip, src_port, dst_ip, dst_port, streamid_sv, std::move(vlan));
}

inline flow_id make_flow_id(
    std::uint32_t interface_id,
    const ip_addr& src_ip, std::uint16_t src_port,
    const ip_addr& dst_ip, std::uint16_t dst_port,
    tsv::vlan_info vlan = {}
) {
    return flow_id::from_packet(interface_id, src_ip, src_port, dst_ip, dst_port, std::move(vlan));
}

inline std::string make_stream_key(const stream_id& sid) {
    return sid.to_stream_key();
}

