class SrtOutageTests(unittest.TestCase):
    def test_mute_preserves_connection_beyond_default_peer_idle_timeout(self):
        peer = SrtPeer()
        sender = Sender(["--proto", "srt", "--port", str(peer.port), "--outage",
                         "mode=mute,period=6500ms,duration=6000ms", "--impair",
                         "jitter,mode=random,max-ms=5"])
        try:
            time.sleep(13.0)
            sender.stop()
        finally:
            sender.stop()
            peer.close()
        self.assertFalse(peer.errors)
        self.assertEqual(sender.process.returncode, 0, sender.output)
        self.assertEqual(len(peer.connections), 1, sender.output)
        self.assertEqual(sender.output.count("outage: resume"), 1, sender.output)
        self.assertGreater(max(b[0] - a[0] for a, b in zip(peer.records, peer.records[1:])), 5.7)
        # The same accepted connection must actually deliver after the 6 second pause.
        self.assertGreater(peer.records[-1][0] - peer.records[0][0], 12.7)

    def test_srt_mute_and_reconnect_direct_and_proxy(self):
        for mode in ["mute", "reconnect"]:
            for proxy in [False, True]:
                with self.subTest(mode=mode, proxy=proxy):
                    peer = SrtPeer()
                    sender = Sender(["--proto", "srt", "--port", str(peer.port),
                                     "--bitrate", "1000000", "--srt-streamid", "test/outage",
                                     "--outage", f"mode={mode},period=800ms,duration=350ms"] +
                                    (["--impair", "jitter,mode=random,max-ms=5"] if proxy else []))
                    try:
                        time.sleep(2.1)
                        sender.stop()
                    finally:
                        if sender.process.poll() is None:
                            sender.stop()
                        peer.close()
                    self.assertFalse(peer.errors)
                    self.assertEqual(sender.process.returncode, 0, sender.output)
                    self.assertEqual(len(peer.connections), 1 if mode == "mute" else 3, sender.output)
                    self.assertTrue(all(c[2] == b"test/outage" for c in peer.connections))
                    self.assertTrue(all(a[1] != b[1] for a, b in zip(peer.connections, peer.connections[1:])))
                    self.assertTrue(all(any(r[1] == c[0] for r in peer.records) for c in peer.connections))
                    if mode == "mute":
                        self.assertGreater(max(b[0] - a[0] for a, b in zip(peer.records, peer.records[1:])), 0.25)
                    self.assertEqual(sender.output.count("outage: resume"), 2, sender.output)

    def test_reconnect_failure_exits_nonzero(self):
        peer = SrtPeer()
        sender = Sender(["--proto", "srt", "--port", str(peer.port), "--outage",
                         "mode=reconnect,period=600ms,duration=300ms"])
        try:
            deadline = time.monotonic() + 3
            while not any(line.startswith("outage: stop") for _, line in sender.lines):
                self.assertLess(time.monotonic(), deadline, sender.output)
                time.sleep(0.01)
            peer.close()
            sender.process.wait(timeout=5)
            sender.stop()
            self.assertNotEqual(sender.process.returncode, 0, sender.output)
            self.assertIn("srt_connect failed", sender.output)
        finally:
            sender.stop()
            if not peer.done.is_set():
                peer.close()

    def test_signal_during_connect(self):
        # A bound UDP endpoint without SRT replies leaves the handshake pending.
        dummy = udp_socket()
        sender = Sender(["--proto", "srt", "--port", str(dummy.getsockname()[1])])
        try:
            time.sleep(0.05)
            started = time.monotonic()
            sender.stop()
            self.assertLess(time.monotonic() - started, 0.5)
            self.assertEqual(sender.process.returncode, 0, sender.output)
        finally:
            sender.stop()
            dummy.close()


