// Bind explicitly so a reconnect cannot accidentally reuse its previous port.
int open_udp_socket(std::uint16_t previous_port = 0) {
    for (int attempt = 0; attempt < 32; ++attempt) {
        const int fd = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (fd < 0) return -1;
        sockaddr_in address{};
        address.sin_family = AF_INET;
        address.sin_addr.s_addr = htonl(INADDR_ANY);
        socklen_t length = sizeof(address);
        if (::bind(fd, reinterpret_cast<const sockaddr*>(&address), sizeof(address)) < 0 ||
            ::getsockname(fd, reinterpret_cast<sockaddr*>(&address), &length) < 0) {
            ::close(fd); return -1;
        }
        if (ntohs(address.sin_port) != previous_port) return fd;
        ::close(fd);
    }
    std::cerr << "could not allocate a different UDP source port\n";
    return -1;
}

std::uint16_t udp_source_port(int fd) {
    sockaddr_in address{};
    socklen_t length = sizeof(address);
    return ::getsockname(fd, reinterpret_cast<sockaddr*>(&address), &length) == 0
        ? ntohs(address.sin_port) : 0;
}

void wait_until_or_stop(clock_type::time_point until) {
    const auto quantum = std::chrono::duration_cast<clock_type::duration>(std::chrono::milliseconds(10));
    while (!g_stop && clock_type::now() < until) {
        std::this_thread::sleep_until(std::min(until, clock_type::now() + quantum));
    scheduler.stop();
    media.close();
    if (opt.fec) {
        fec_row.close();
        fec_col.close();
    }
    return true;
}
#ifdef ENABLE_SRT
class srt_impairment_proxy {
public:
    explicit srt_impairment_proxy(const options& opt)
        : jitter_ms_(opt.jitter.max_ms)
        , jitter_target_ms_(opt.jitter.target_ms)
        , jitter_modulation_(
            opt.jitter_modulation,
            modulation_seed(opt, opt.jitter_modulation, 0xbb67ae85U))
        , bitrate_modulation_(
            opt.bitrate_modulation,
            modulation_seed(opt, opt.bitrate_modulation, 0x6a09e667U))
        , target_reorder_(jitter_target_reorders(opt))
        , payload_size_(opt.payload_size)
        , bitrate_bps_(opt.bitrate_bps)
        , rng_(opt.seed ? (*opt.seed ^ 0x85ebca6bU) : std::random_device{}())
        , jitter_distribution_(0.0, jitter_ms_)
        , impairment_(opt, [this](packet value) {
            schedule(std::move(value));
        }) {}

    ~srt_impairment_proxy() {
        stop();
    }

    bool open(const std::string& dst, std::uint16_t port, std::uint16_t previous_port = 0) {
        downstream_fd_ = open_udp_socket(previous_port);
        if (downstream_fd_ < 0) {
            perror("SRT proxy downstream socket");
            return false;
        }

        std::memset(&destination_, 0, sizeof(destination_));
        destination_.sin_family = AF_INET;
        destination_.sin_port = htons(port);
        if (::inet_pton(AF_INET, dst.c_str(), &destination_.sin_addr) != 1) {
            std::cerr << "invalid SRT destination ip: " << dst << "\n";
            close_fds();
            return false;
        }

        upstream_fd_ = ::socket(AF_INET, SOCK_DGRAM, 0);
        if (upstream_fd_ < 0) {
            perror("SRT proxy upstream socket");
            close_fds();
            return false;
        }

        sockaddr_in listen{};
        listen.sin_family = AF_INET;
        listen.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        listen.sin_port = 0;
        if (::bind(upstream_fd_, reinterpret_cast<const sockaddr*>(&listen), sizeof(listen)) < 0) {
            perror("SRT proxy bind");
            close_fds();
            return false;
        }

        socklen_t length = sizeof(listen);
        if (::getsockname(upstream_fd_, reinterpret_cast<sockaddr*>(&listen), &length) < 0) {
            perror("SRT proxy getsockname");
            close_fds();
            return false;
        }

        local_port_ = ntohs(listen.sin_port);
        return true;
    }

    void start() {
        worker_ = std::thread([this] { run(); });
    }

    void stop() {
        stopping_ = true;
        if (worker_.joinable()) {
            worker_.join();
        }
        close_fds();
    }

    std::uint16_t local_port() const {
        return local_port_;
    }

    std::uint16_t source_port() const { return udp_source_port(downstream_fd_); }

    void set_start(clock_type::time_point started) {
        std::lock_guard<std::mutex> lock(state_mutex_);
        bitrate_modulation_.set_start(started);
        jitter_modulation_.set_start(started);
    }

    void set_muted(bool muted) {
        std::lock_guard<std::mutex> lock(state_mutex_);
        muted_ = muted;
        scheduled_.clear();
        impairment_.discard_pending();
    std::optional<clock_type::time_point> next_base_time_;
    std::optional<clock_type::time_point> last_due_;
    std::multimap<clock_type::time_point, packet> scheduled_;
    packet_impairer impairment_;
    std::mutex state_mutex_;
    bool muted_{false};
    std::atomic<bool> stopping_{false};
    std::thread worker_;
};
#endif

// One connection owns both the libsrt socket and its optional wire-level proxy.
#ifdef ENABLE_SRT
class srt_connection {
public:
    ~srt_connection() { close(); }

    void close() {
        if (sock != SRT_INVALID_SOCK) { srt_close(sock); sock = SRT_INVALID_SOCK; }
        proxy.reset();
    }

    bool open(const options& opt, clock_type::time_point epoch, std::uint16_t previous_port = 0) {
        std::string destination = opt.dst;
        std::uint16_t port = opt.port;
        if (impairment_enabled(opt)) {
            proxy = std::make_unique<srt_impairment_proxy>(opt);
            if (!proxy->open(opt.dst, opt.port, previous_port)) return false;
            proxy->set_start(epoch);
            proxy->start();
            destination = "127.0.0.1";
            port = proxy->local_port();
        }
        for (int attempt = 0; attempt < 32; ++attempt) {
            sock = srt_create_socket();
            if (sock == SRT_INVALID_SOCK) return error("srt_create_socket");
            int yes = 1;
            int no = 0;
            if (srt_setsockopt(sock, 0, SRTO_SENDER, &yes, sizeof(yes)) == SRT_ERROR ||
                srt_setsockopt(sock, 0, SRTO_RCVSYN, &no, sizeof(no)) == SRT_ERROR ||
                (opt.outage && srt_setsockopt(sock, 0, SRTO_SNDSYN, &no, sizeof(no)) == SRT_ERROR))
                return error("srt socket setup");
            if (!opt.srt_streamid.empty() && srt_setsockopt(sock, 0, SRTO_STREAMID,
                opt.srt_streamid.data(), static_cast<int>(opt.srt_streamid.size())) == SRT_ERROR)
                return error("srt stream ID setup");
            sockaddr_in local{};
            local.sin_family = AF_INET;
            local.sin_addr.s_addr = htonl(INADDR_ANY);
            if (srt_bind(sock, reinterpret_cast<sockaddr*>(&local), sizeof(local)) == SRT_ERROR)
                return error("srt_bind");
            if (proxy || source_port() != previous_port) break;
            srt_close(sock); sock = SRT_INVALID_SOCK;
        }
        if (sock == SRT_INVALID_SOCK) return error("SRT different source port allocation");
        sockaddr_in remote{};
        remote.sin_family = AF_INET;
        remote.sin_port = htons(port);
        if (::inet_pton(AF_INET, destination.c_str(), &remote.sin_addr) != 1) {
            std::cerr << "invalid SRT destination: " << destination << "\n"; return false;
        }
        const int result = srt_connect(sock, reinterpret_cast<sockaddr*>(&remote), sizeof(remote));
        if (result == SRT_ERROR && srt_getsockstate(sock) != SRTS_CONNECTING)
            return error("srt_connect");
        while (!g_stop && srt_getsockstate(sock) == SRTS_CONNECTING)
            wait_until_or_stop(clock_type::now() + std::chrono::milliseconds(10));
        if (g_stop) return false;
        if (srt_getsockstate(sock) != SRTS_CONNECTED) return error("srt_connect");
        return true;
    }

    std::uint16_t source_port() const {
        if (proxy) return proxy->source_port();
        sockaddr_in address{};
        int length = sizeof(address);
        return srt_getsockname(sock, reinterpret_cast<sockaddr*>(&address), &length) == 0
            ? ntohs(address.sin_port) : 0;
    }

    SRTSOCKET sock{SRT_INVALID_SOCK};
    std::unique_ptr<srt_impairment_proxy> proxy;

private:
    bool error(const char* action) {
        std::cerr << action << " failed: " << srt_getlasterror_str() << "\n";
        return false;
    }
};
#endif

bool run_srt(const options& opt) {
#ifndef ENABLE_SRT
    std::cerr << "SRT disabled. Build with -DENABLE_SRT and link libsrt.\n";
    (void)opt;
    return false;
#else
    srt_connection connection;
    if (!connection.open(opt, clock_type::now())) return g_stop != 0;
    const auto started = clock_type::now();
    if (connection.proxy) connection.proxy->set_start(started);
    outage_schedule outage(opt.outage);
    outage.start(started);

    const double packets_per_sec =
        static_cast<double>(opt.bitrate_bps) /
        static_cast<double>(opt.payload_size * 8);

    if (packets_per_sec <= 0.0) {
        std::cerr << "invalid SRT packets_per_sec\n";
        return false;
    }

    std::vector<char> payload(opt.payload_size, 0);

    std::cerr
        << "SRT: " << opt.dst << ":" << opt.port
        << " bitrate=" << opt.bitrate_bps
        << " payload=" << opt.payload_size
        << " pps=" << packets_per_sec
        << (opt.srt_streamid.empty() ? "" : " streamid=" + opt.srt_streamid)
        << "\n";

    if (connection.proxy) {
        std::cerr << "SRT impairment proxy: 127.0.0.1:" << connection.proxy->local_port()
                  << " -> " << opt.dst << ":" << opt.port << "\n";
    }
    print_impairment(opt);
    print_modulation(opt);
    print_impairment_warnings(opt);
    print_outage(opt);

    auto next = started;
    std::uint64_t counter = 0;
    modulation_driver bitrate_modulation(
        opt.bitrate_modulation,
        modulation_seed(opt, opt.bitrate_modulation, 0x6a09e667U));
    bitrate_modulation.set_start(started);
    bool was_muted = false;
    std::uint16_t previous_port = 0;

    while (!g_stop) {
        const auto now = clock_type::now();
        const bool muted = outage.muted(now);
        if (muted != was_muted) {
            was_muted = muted;
            if (muted) {
                outage.log("stop");
                if (opt.outage->mode == outage_mode::reconnect) {
                    previous_port = connection.source_port();
                    connection.close();
                } else if (connection.proxy) connection.proxy->set_muted(true);
            } else {
                if (opt.outage->mode == outage_mode::reconnect) {
                    outage.log("reconnecting");
                    if (!connection.open(opt, started, previous_port)) return g_stop != 0;
                    std::cerr << "SRT reconnect: source-port=" << connection.source_port() << "\n";
                } else if (connection.proxy) connection.proxy->set_muted(false);
                next = clock_type::now();
                outage.log("resume");
                // A slow handshake may have crossed into a later stop window.
                continue;
            }
        }
        if (muted) {
            wait_until_or_stop(outage.next_boundary(now));
            continue;
        }
        if (now < next) {
            wait_until_or_stop(std::min(next, outage.next_boundary(now)));
            continue;
        }
        for (std::size_t i = 0; i < payload.size(); ++i) {
            payload[i] = static_cast<char>((counter + i) & 0xff);
        }

        const int ret = srt_sendmsg(
            connection.sock,
            payload.data(),
            static_cast<int>(payload.size()),
            -1,
            0);

        if (ret == SRT_ERROR) {
            if (opt.outage && srt_getlasterror(nullptr) == SRT_EASYNCSND) {
                wait_until_or_stop(std::min(clock_type::now() + std::chrono::milliseconds(1), outage.next_boundary(now)));
                continue;
            }
            std::cerr << "srt_sendmsg failed: " << srt_getlasterror_str() << "\n";
            return false;
        }

        ++counter;
        const double bitrate = bitrate_modulation.enabled()
            ? bitrate_modulation.value_at(next)
            : static_cast<double>(opt.bitrate_bps);
        const auto interval = std::chrono::duration_cast<clock_type::duration>(
            std::chrono::duration<double>(static_cast<double>(opt.payload_size * 8) / bitrate));
        next += interval;
        if (next < clock_type::now() - interval) next = clock_type::now();
    }
    return true;
#endif
}

