        if (g_stop) return false;
        if (srt_getsockstate(sock) != SRTS_CONNECTED) return error("srt_connect");
        return true;
    }

    std::uint16_t source_port() const {
        if (proxy) return proxy->source_port();
        sockaddr_in address{};
        int length = sizeof(address);
        return srt_getsockname(sock, reinterpret_cast<sockaddr*>(&address), &length) == 0
            ? ntohs(address.sin_port) : 0;
    }

    SRTSOCKET sock{SRT_INVALID_SOCK};
    std::unique_ptr<srt_impairment_proxy> proxy;

private:
    srt_source_port_pool source_ports_;

    bool error(const char* action) {
        std::cerr << action << " failed: " << srt_getlasterror_str() << "\n";
        return false;
    }
