// Persist the externally visible port identities across connection/proxy teardown.
// A callback binds the requested port (0 asks the OS) and returns the actual port.
class srt_source_port_pool {
public:
    explicit srt_source_port_pool(std::size_t capacity) : capacity_(capacity) {}

    template <class Bind>
    bool bind_socket(Bind bind, std::uint16_t previous_port) {
        if (capacity_ != 0 && ports_.size() == capacity_) {
            for (std::size_t attempt = 0; attempt < ports_.size() && !g_stop; ++attempt) {
                const auto index = (next_ + attempt) % ports_.size();
                const auto port = ports_[index];
                if (bind(port) != port) continue;
                next_ = (index + 1) % ports_.size();
                log(port, "reuse");
                return true;
            }
            std::cerr << "SRT source-port pool: all " << ports_.size()
                      << " learned ports are unavailable; refusing to allocate another port\n";
            return false;
        }

        for (int attempt = 0; attempt < 32 && !g_stop; ++attempt) {
            const auto port = bind(0);
            if (port == 0) return false;
            if (capacity_ == 0) {
                if (port != previous_port) return true;
            } else if (std::find(ports_.begin(), ports_.end(), port) == ports_.end()) {
                ports_.push_back(port);
                log(port, "learn");
                return true;
            }
        }
        std::cerr << "could not allocate a different SRT source port\n";
        return false;
    }

private:
    void log(std::uint16_t port, const char* action) const {
        std::cerr << "SRT source-port pool: source-port=" << port
                  << " size=" << ports_.size() << " limit=" << capacity_
                  << " action=" << action << "\n";
    }

    const std::size_t capacity_;
    std::vector<std::uint16_t> ports_;
    std::size_t next_{0};
};

